INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f6ee330a-065a-5ce6-ab5b-68010d3a271f', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 12, 37, 'ራሱን እንደ ነቢይ አድርጎ ወይም መንፈስ ቅዱስ እንዳደረበት አድርጎ የሚቈጥር ቢኖር፥ የእግዚአብሔር ትእዛዝ ነውና ይህን የጻፍሁላችሁን ይወቅ።'),
  ('901b798e-956a-5151-a7f0-fdd9d24c474a', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 13, 38, 'ነገር ግን ይህን የማያውቅ ቢኖር እግዚአብሔርን አያውቀውም።'),
  ('598101ab-d487-5c5e-a937-b66b3af98ff7', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 14, 39, 'አሁንም ወንድሞቻችን ሆይ፥ ትንቢትን ለመናገር ቅኑ፤ በቋንቋ የሚናገረውንም አትከልክሉት።'),
  ('02fe9f42-4c41-5c43-ad5e-9d67c8e55125', 'b035958f-df8a-59bb-ae2e-5733f75dfe56', 'a2eda51e-58e8-5020-a3f8-a2df8d9f9a37', 15, 40, 'ነገር ግን ሁሉን በአገባብና በሥርዐት አድርጉ፤'),
  ('3d8641c0-baba-52c1-a8dd-3c4c4ada8758', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '083244d3-f382-5989-adb5-ec35f4d46809', 1, 1, 'ወንድሞቻችን ሆይ፥ ያስተማርኋችሁንና የተቀበላችሁትን ያላችሁበትን፥ በእርሱም የምትድኑበትን ወንጌል አሳስባችኋለሁ።'),
  ('b355dd0f-14f8-54bd-ab97-1977326fb070', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '083244d3-f382-5989-adb5-ec35f4d46809', 2, 2, 'ያስተማርኋችሁን ታስቡ እንደ ሆነ በቃሌ አስተምሬአችኋለሁ፤ ያለዚያ ግን ማመናችሁ ከንቱ ነው።'),
  ('f7f9fd5d-602f-56b5-a3fa-42d45ba3460e', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 1, 3, 'እኔ የተማርሁትን አስቀድሜ መጽሐፍ እንደሚል እንዲህ ብዬ አስተማርኋችሁ፥ “ክርስቶስ ስለ ኀጢአታችን ሞተ።'),
  ('82f0f70a-0586-5291-a07c-462060033ffa', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 2, 4, 'ተቀበረ፤ እንደ ተጻፈም በሦስተኛው ቀን ተነሣ።”'),
  ('22a8a953-ad7c-518c-a272-689620cb53a0', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 3, 5, 'ለጴጥሮስ ታየው፤ ከዚህም በኋላ ለዐሥራ አንዱ ደቀ መዛሙርቱ ታያቸው።'),
  ('4cc066dd-83a5-54bd-a20a-350bb55e1799', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 4, 6, 'ከዚህም በኋላ ከአምስት መቶ ለሚበዙ ወንድሞች በአንድ ጊዜ ታያቸው፤ ከእነርሱ ብዙዎቹ እስከ ዛሬ አሉ፤ አንዳንዶቹ ግን አንቀላፍተዋል።'),
  ('1bdd672d-8bd4-58ab-afd6-38d9a8ebb280', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 5, 7, 'ከዚህም በኋላ ለያዕቆብ ታየው፤ ኋላም ለሐዋርያት ሁሉ፤'),
  ('b343af9e-4f46-5a97-a2c5-224706069e73', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 6, 8, 'ከሁሉም በኋላ ጭንጋፍ ለምመስል ለእኔ ታየኝ።'),
  ('1503921f-1817-5832-a7d9-f53bea1ccc7c', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 7, 9, 'ከሐዋርያት ሁሉ እኔ አንሣለሁና፤ የእግዚአብሔርን ቤተ ክርስቲያን ስለ አሳደድሁ ሐዋርያ ተብዬ ልጠራ የማይገባኝ፥'),
  ('e297247f-96db-5c0b-ab3f-da2d1b4bce77', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 8, 10, 'ነገር ግን በእግዚአብሔር ጸጋ አሁን እኔ ባለሁበት አለሁ፤ ለእኔም የሰጠኝ ጸጋው ለከንቱ የሆነብኝ አይደለም፤ እኔም ከሁሉ ይልቅ ደከምሁ፤ ነገር ግን በእኔ ላይ ያደረው የእግዚአብሔር ጸጋ አጸናኝ እንጂ እኔ አይደለሁም።'),
  ('5aae80a0-8e0d-5b33-accb-46b02686925a', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '6620d593-c74f-5df0-aca5-7839a1e3d634', 9, 11, 'አሁንም እኔም ብሆን፥ እነርሱም ቢሆኑ እንዲህ እናስተምራለን፤ እናንተም እንዲሁ አምናችኋል።'),
  ('248751f5-1fac-5ade-a2bd-db3a450005e2', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 1, 12, 'ክርስቶስ ከሙታን ተለይቶ ተነሥቶአል ብለን ለሌላው የምናስተምር ከሆነ፥ እንግዲህ ከመካከላችሁ ሙታን አይነሡም የሚሉ እንዴት ይኖራሉ?'),
  ('727ac13d-b11b-5ff0-ae77-c146e28d26dd', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 2, 13, 'ሙታን የማይነሡ ከሆነ ክርስቶስም ከሙታን ተለይቶ አልተነሣማ፤'),
  ('ffc37461-effc-56c5-a62d-e9f5098a5ae9', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 3, 14, 'ክርስቶስም ከሙታን ካልተነሣ እንግዲያስ ትምህርታችን ከንቱ ነው፤ የእናንተም እምነታችሁ ከንቱ ነው።'),
  ('4f94e897-1bdb-53a9-af50-8d01781cf7eb', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 4, 15, 'እኛም በእግዚአብሔር ላይ የሐሰት ምስክሮች ሆነናል፤ ክርስቶስን አስነሣው ብለናልና፥ እንግዲያ ሳያስነሣው ነውን?።'),
  ('f6afb418-768d-59b1-af44-6a623c7f2a31', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 5, 16, 'ሙታን የማይነሡ ከሆነ ክርስቶስም ከሙታን አልተነሣማ።'),
  ('283bac25-1df4-536f-ab92-4bf85c28ae29', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 6, 17, 'ክርስቶስም ከሙታን ካልተነሣ ማመናችሁ ከንቱ ነው፤ ገናም በኀጢአታችሁ አላችሁ።'),
  ('418d811e-f7d5-5a06-a920-bcb6b4e3a17b', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 7, 18, 'እንግዲያስ በክርስቶስ አምነው የሞቱ ጠፍተዋላ።'),
  ('2f8b6ed7-2f2b-5b96-a9a4-d3b6ebe40d6c', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 8, 19, 'በዚህ ዓለም ሕይወት ብቻ ክርስቶስን ተስፋ ከአደረግነው ከሰው ሁሉ ይልቅ ጉዳተኞች ነን።'),
  ('86881308-7e03-507b-a0e7-c03a73a6eb75', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 9, 20, 'አሁንም ክርስቶስ ከሞቱ ሰዎች ሁሉ አስቀድሞ ተነሥቶአል።'),
  ('766cfc7d-dfec-5aa2-a64b-a756fcf51ba1', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 10, 21, 'በመጀመሪያው ሰው ሞት መጥቶአልና፤ በሁለተኛው ሰው ትንሣኤ ሙታን ሆነ።'),
  ('6437460b-1259-5b24-a37d-15caa27e6a41', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 11, 22, 'ሁሉ በአዳም እንደሚሞት እንዲሁ በክርስቶስ ሁሉ ሕያዋን ይሆናሉ።'),
  ('93905993-bc5b-593e-af64-25c34b8498fb', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 12, 23, 'ነገር ግን ሰው ሁሉ በየሥርዐቱ ይነሣል፤ በመጀመሪያ ከሙታን የተነሣ ክርስቶስ ነው፤ ከዚያ በኋላ በክርስቶስ ያመኑ እርሱ በሚመጣበት ጊዜ ይነሣሉ።'),
  ('674db593-e526-5ebf-acfd-0b9a06f07290', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 13, 24, 'እግዚአብሔር አብ መንግሥቱን እጅ ባደረገ ጊዜ፥ ገዥም ሁሉ፥ ንጉሥም ሁሉ፥ ኀይልም ሁሉ በተሻረ ጊዜ፥ ያንጊዜ ፍጻሜ ይሆናል።'),
  ('9ca26a03-0439-5807-a843-96e9420a0265', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 14, 25, 'ጠላቶቹ ሁሉ ከእግሩ በታች እስኪወድቁ ድረስ ይነግሥ ዘንድ አለውና።'),
  ('9800e22f-6456-5b0b-adc7-3cc8975ff258', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 15, 26, 'ከዚያ በኋላ የመጨረሻው ጠላት ይሻራል፤ ይኸውም ሞት ነው።'),
  ('62c5c4f3-298f-5f4c-a974-d7e4f94fb431', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 16, 27, 'ሁሉን ከእግሩ በታች አስገዝቶለታልና፥ “ሁሉ ይገዛለት” ባለ ጊዜ ግን ሁሉን ከሚያስገዛለት በቀር እንደ ሆነ የታወቀ ነው።'),
  ('1d1013c4-e450-5989-a25a-bb494105d11b', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 17, 28, 'ሁሉም በተገዛለት ጊዜ ግን እግዚአብሔር በሁሉ ቦታ በሁሉ ይሆን ዘንድ፥ ያን ዕለት ወልድም ሁሉን ላስገዛለት ይገዛል።'),
  ('28603e9e-e95d-5dd0-a057-b44c1c43afa1', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 18, 29, 'ያለዚያማ ለምን ያጠምቃሉ? ሙታን እንዲነሡ አይደለምን? ሙታን የማይነሡ ከሆነስ ለምን ያጠምቃሉ?'),
  ('3e38d042-f813-54d9-aae1-541468222cca', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 19, 30, 'እንግዲህ እኛስ ሁልጊዜ መከራን ስለምን እንቀበላለን?'),
  ('47a2ffe1-501a-5171-aa9c-843f7dc1599a', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 20, 31, 'ወንድሞቻችን ሆይ፥ በጌታችን በኢየሱስ ክርስቶስ በሆነውና በእናንተ ላይ ባለኝ ትምክህት ሁልጊዜ እገደላለሁ።'),
  ('42508e8e-7315-5f6d-aa40-3fb232ee77c1', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 21, 32, 'በውኑ በኤፌሶን ከአውሬ ጋር የታገልሁ ለሰው ብዬ ነውን? ምንስ ይጠቅመኛል? ሙታን የማይነሡ ከሆነ እንግዲህ እንብላ እንጠጣ፥ ነገም እንሞታለን።'),
  ('862510a8-a547-5d21-a85c-aff00bbe753f', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', 'cc291a5d-b6d0-503e-a208-beeead37ab67', 22, 33, 'ወንድሞቻችን አያስቱአችሁ፤ ክፉ ነገር መልካም ጠባይን ያበላሻልና።'),
  ('b9e0c2ec-2be9-527e-a7a7-0c2148868da0', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 1, 34, 'ለጽድቅ ትጉ፤ አትሳቱ፤ እግዚአብሔርን የማያውቁት ሰዎች አሉና፤ ነገር ግን እንድታፍሩ ይህን እላችኋለሁ፤'),
  ('d2e73f34-9e83-5b0d-aea9-60cb99176ba5', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 2, 35, 'ሙታን እንዴት ይነሣሉ? የሚነሡስ በምን አካላቸው ነው? የሚል አለ።'),
  ('af52c115-a795-56c0-a29f-f4f47966f5b3', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 3, 36, 'አንተ ሰነፍ! አንተ የምትዘራው እንኳን ካልፈረሰ አይበቅልም።'),
  ('4f72aa7c-b125-5c5a-a6a0-f35159cbe8b5', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 4, 37, 'የምትዘራውም የስንዴ ቢሆን፥ የሌላም ቢሆን የምትዘራት ቅንጣት ብቻ ናት እንጂ ይህ ኋላ የሚገኘው አገዳው አይደለም።'),
  ('04f8095f-3ac6-5001-aa46-83671f361fff', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 5, 38, 'እግዚአብሔር ግን እንደ ወደደ አገዳን ይሰጠዋል፤ ለእያንዳንዱ ዘርም አገዳው እየራሱ ነው።'),
  ('067c2bb7-a835-5c93-a109-e456c00b89fe', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 6, 39, 'የፍጥረቱ ሁሉ አካል አንድ አይደለምና፤ የሰው አካል ሌላ ነው፤ የእንስሳም አካል ሌላ ነው፤ የወፍ አካልም ሌላ ነው፤ የዓሣ አካልም ሌላ ነው።'),
  ('ed8d5e30-dffb-53ea-a809-691e2d67add8', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 7, 40, 'ሰማያዊ አካል አለ፤ ምድራዊ አካልም አለ፤ ነገር ግን በሰማይ ያለው አካል ክብሩ ልዩ ነው፤ በምድርም ያለው አካል ክብሩ ልዩ ነው።'),
  ('b015ced3-1bdb-5520-aa25-1ccd78fabcda', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 8, 41, 'የፀሐይ ክብሩ ሌላ ነው፤ የጨረቃም ክብሩ ሌላ ነው፤ የከዋክብትም ክብራቸው ሌላ ነው፤ ኮከብ ከኮከብ በክብር ይበልጣልና።'),
  ('60cc0ec1-69a9-5694-a894-4b5a3460b738', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 9, 42, 'የሙታን ትንሣኤያቸው እንዲሁ ነው፥ በሚፈርስ አካል ይዘራል፤ በማይፈርስ አካል ይነሣል።'),
  ('450756c4-cb33-523b-abea-cc706e721009', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 10, 43, 'በውርደት ይዘራል፤ በክብር ይነሣል፤ በድካም ይዘራል፤ በኀይል ይነሣል።'),
  ('2221c6d7-dd77-5c77-aaa7-6c28664a7807', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 11, 44, 'ሥጋዊ አካል ይዘራል፤ መንፈሳዊ አካል ይነሣል፤ ሥጋዊ አካል አለና መንፈሳዊ አካልም ደግሞ አለ።'),
  ('92328cf2-7abe-5e39-a0d4-68a67ad801ca', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 12, 45, 'መጽሐፍ እንዲሁ ብሎአልና የመጀመሪያው ሰው አዳም በነፍስ ሕያው ሆኖ ተፈጠረ፤ ሁለተኛው አዳም ግን ሕይወትን የሚሰጥ መንፈስ ነው።'),
  ('d612a5e0-d2dc-5254-a7e0-f4da0ca27589', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 13, 46, 'ነገር ግን አስቀድሞ ሥጋዊው፥ ቀጥሎም መንፈሳዊው ነው እንጂ፥ መንፈሳዊው መጀመሪያው አይደለም።'),
  ('34a9cfcd-0116-5716-acec-fd1c94b598f5', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 14, 47, 'መጀመሪያው ሰው ከመሬት የተገኘ መሬታዊ ነው፤ ሁለተኛው ሰው ከሰማይ የወረደ ሰማያዊ ነው።'),
  ('f272ac7c-2c85-5702-adaf-97ea58e55141', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 15, 48, 'መሬታውያኑ እንደዚያ እንደ መሬታዊው ናቸው፤ ሰማያውያኑም እንደዚያ እንደ ሰማያዊው ናቸው።'),
  ('16b18bdd-7d34-5d91-aa62-2a59d2e44376', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 16, 49, 'የመሬታዊውን መልክ እንደ ለበስን እንዲሁ የሰማያዊውን መልክ ደግሞ እንለብሳለን።'),
  ('3ccafecc-6774-5233-a38b-2ef1f0507b76', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 17, 50, 'ወንድሞቻችን ሆይ፥ ይህን እንነግራችኋለን፦ ሥጋዊና ደማዊ የእግዚአብሔርን መንግሥት አይወርስም፥ የሚፈርሰው የማይፈርሰውን አይወርስም።'),
  ('4d70bea9-78ae-5b1c-a580-ff7714407d45', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 18, 51, 'እነሆ፥ አንድ ምሥጢርን እነግራችኋለሁ፥ ሁላችን የምንሞት አይደለም።'),
  ('facdd618-98c1-5c29-a295-fa188b0ee6fe', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 19, 52, 'ነገር ግን የኋለኛው መለከት ሲነፋ ሁላችን እንደ ዐይን ጥቅሻ በአንድ ጊዜ እንለወጣለን፤ መለከት ይነፋል፤ ሙታንም የማይፈርሱ ሁነው ይነሣሉ፤ እኛም እንለወጣለን።'),
  ('d644145e-15a2-57d1-a759-a6fad75e65a8', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 20, 53, 'ይህ የሚፈርሰው የማይፈርሰውን፥ ይህም የሚሞተው የማይሞተውን ይለብስ ዘንድ አለውና።'),
  ('401af298-86c0-5990-a8ae-5a0d674a9bd5', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 21, 54, 'ይህ የሚፈርሰው የማይፈርሰውን በለበሰ ጊዜ፥ የሚሞተውም የማይሞተውን በለበሰ ጊዜ፤ “ሞት በመሸነፍ ተዋጠ” ተብሎ የተጻፈው ያንጊዜ ይፈጸማል።'),
  ('0cc13cdd-2e8a-5527-a20c-41c3f9976cc7', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 22, 55, '“ሞት ሆይ፥ እንግዲህ መውጊያህ ወዴት አለ? መቃብር ሆይ፥ አሸናፊነትህ ወዴት አለ?”'),
  ('377d5acb-6070-5f56-a574-258a24749d3e', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 23, 56, 'የሞት መውጊያ ኀጢአት ናት፥ የኀጢአትም ኀይልዋ ኦሪት ናት።'),
  ('1a696c99-55ab-5653-ac98-ca8fd26add26', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 24, 57, 'በጌታችን በኢየሱስ ክርስቶስ ድል መንሣትን ለሰጠን ለእግዚአብሔር ምስጋና ይሁን።'),
  ('bc8dcaf8-4f4b-5a8d-ab8d-8e54744342e2', '7a16a46f-26d0-58ed-aff2-6b04dd93a0b9', '11760a6b-a3f9-5b2c-a633-84c4645c1fde', 25, 58, 'አሁንም የተወደዳችሁ ወንድሞቻችን ሆይ፥ የጸናችሁና የማትናወጡ ሁኑ፤ ዘወትር በጎ ምግባርን አብዝታችሁ ለእግዚአብሔር አበርክቱ፤ ስለ ጌታችን መድከማችሁ ለከንቱ እንዳይደለ ታውቃላችሁና።'),
  ('69303b04-3ffc-5b8e-a72f-b99c5620213a', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 1, 1, 'ለቅዱሳን ስለሚደረገው አስተዋፅኦ በገላትያ ላሉት ምእመናን እንደ ደነገግሁት እናንተም እንዲሁ አድርጉ።'),
  ('26ccf098-3a75-5734-ae60-65a461dedbaf', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 2, 2, 'እኔ ስመጣ ይህ የገንዘብ ማዋጣት ያንጊዜ እንዳይሆን፥ ከእናንተ ሰው ሁሉ በየሳምንቱ እሑድ የተቻለውን ያወጣጣ፤ ያገኘውንም በቤቱ ይጠብቅ።'),
  ('71233b3f-b7ef-5027-a57b-e89ca15382bb', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 3, 3, 'በመጣሁ ጊዜም ስጦታችሁን ወደ ኢየሩሳሌም ያደርሱ ዘንድ የመረጣችኋቸውን ሰዎች መልእክቴን ጨምሬ እልካቸዋለሁ።'),
  ('57d4db76-c547-5e8d-add7-b3bd9f4db5e2', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 4, 4, 'ለመሄድ ቢቻለኝ ግን እኔ ራሴ እሄዳለሁና፥ እነርሱም አብረውኝ ይሄዳሉ።'),
  ('8fd4e3e7-8270-5039-a7ff-07bdb77b00e7', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 5, 5, 'መቄዶንያም ደርሼ ወደ እናንተ እመጣለሁ፤ በመቄዶንያ በኩል አልፋለሁና።'),
  ('5e65dabf-1c1f-5e40-a794-8617706afdd3', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 6, 6, 'እናንተም ወደምሄድበት ትሸኙኝ ዘንድ ምንአልባት የሆነውን ቀን ያህል በእናንተ ዘንድ እቈይ፥ ወይም እከርም ይሆናል።'),
  ('fc6372f2-a223-522b-a1f2-6633edd65ce9', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 7, 7, 'አሁን እግረ መንገዴን ላያችሁ አልሻም፤ ነገር ግን እግዚአብሔር የፈቀደ እንደ ሆነ የሆነውን ቀን ያህል በእናንተ ዘንድ እንደምቈይ ተስፋ አደርጋለሁ።'),
  ('731080a5-c4b2-5960-ac8f-42d66b6d8bf8', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 8, 8, 'እስከ በዓለ ኀምሳ በኤፌሶን እቈያለሁ።'),
  ('e31fccf1-ceda-5736-a3fd-9634e57f512c', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 9, 9, 'ሥራ የሞላበት ታላቅ በር ተከፍቶልኛልና፤ ነገር ግን ብዙዎች ተቃዋሚዎች አሉ።'),
  ('44cfbcbd-46ed-5ac0-a743-2c5650cc55b6', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 10, 10, 'ጢሞቴዎስም በመጣ ጊዜ በእናንተ ዘንድ ያለ ፍርሀት እንዲኖር ተጠንቀቁ፤ እንደ እኔ የእግዚአብሔርን ሥራ ይሠራልና።'),
  ('6ee9615b-901f-52cf-a2a6-78cfb25884e4', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 11, 11, 'የሚንቀውም አይኑር፤ ከወንድሞቻችን ጋር እጠብቀዋለሁና፥ ወደ እኔ እንዲመጣ በሰላም ሸኙት።'),
  ('6f67cdec-0051-5249-a985-6de232d5ee1f', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 12, 12, 'ስለ ወንድማችን ስለ አጵሎስም ከወንድሞች ጋር ወደ እናንተ እንዲመጣ መላልሼ ማልጄው ነበር፤ አሁን ሊመጣ አልወደደም፤ በተቻለው ጊዜ ግን ይመጣል።'),
  ('8bd4d1f1-17c9-5acd-a9e6-cdf2f1c9c298', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 13, 13, 'ትጉ፤ በሃይማኖትም ቁሙ፤ ታገሡ ጽኑ፤'),
  ('76b58ad4-2334-5564-ab75-42e657841f34', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 14, 14, 'ሁሉን በፍቅር አድርጉ።'),
  ('2e0838e2-608b-5ac9-a1f6-34f73ff65af4', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 15, 15, 'ወንድሞቻችን ሆይ፥ የእስጢፋኖስና የፈርዶናጥስ፥ የአካይቆስም ቤተሰቦች፥ የአካይያ መጀመሪያዎች እንደ ሆኑ፥ ቅዱሳንንም ለማገልገል ራሳቸውን እንደ ሰጡ ታውቁ ዘንድ እማልዳችኋለሁ።'),
  ('7745a8ff-b5d1-5fee-a919-cb8f1f4c0c73', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 16, 16, 'እናንተም እንደ እነዚህ ላሉትና ከእኛ ጋር በሥራ ተባብሮ ለሚደክም ሁሉ ትታዘዙላቸው ዘንድ እማልዳችኋለሁ።'),
  ('4e96dac6-b075-559b-abeb-89e4ba78c55c', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 17, 17, 'እስጢፋኖስ፥ ፈርዶናጥስና አካይቆስ በመምጣታቸውም ደስ ይለኛል፤ እናንተ ያጐደላችሁትን እነርሱ ፈጽመዋልና።'),
  ('e06f0d14-d8d8-50ec-a976-bafd43280c50', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 18, 18, 'እነርሱ መንፈሴንና መንፈሳችሁን ደስ አሰኝተዋል፤ እንዲህ ያሉትንም ዕወቋቸው።'),
  ('377b224c-0cb6-5ed9-ad56-3b2c2be25dc3', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 19, 19, 'በእስያ ያሉ ምእመናን ሰላምታ ያቀርቡላችኋል፤ አቂላና ጵርስቅላ በቤታቸው ከእነርሱ ጋር ያሉ ምእመናንም ሁሉ በጌታችን እጅግ ሰላምታ ያቀርቡላችኋል።'),
  ('1128ce14-c1af-54e9-ab97-92583a9f2f46', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 20, 20, 'ወንድሞቻችሁ ሁሉ ሰላምታ ያቀርቡላችኋል፤ በተቀደሰች ሰላምታ እርስ በርሳችሁ ሰላም ተባባሉ።'),
  ('193867d8-5fa1-5e10-a2d8-4ee12dfcc870', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 21, 21, 'እኔ ጳውሎስ ይህን ሰላምታ በእጄ ጻፍሁ።'),
  ('f33e8162-580e-5870-a979-333d371e2ec8', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 22, 22, 'ጌታችንን ኢየሱስ ክርስቶስን የማይወደው የተለየ ይሁን፤ ጌታችን ይመጣል።'),
  ('f92ae2bc-27bd-5990-a080-56dd19b09cca', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 23, 23, 'የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከእናንተ ጋራ ይሁን።'),
  ('b9a6fe54-34cb-55d2-ad03-64f58a95f231', '61f2d0be-eb87-50e0-a2c4-86a27b5f7543', 'e95a91a7-75e7-54ed-a757-a3709895bb28', 24, 24, 'የእኔም ፍቅር በኢየሱስ ክርስቶስ ከእናንተ ጋር ይሁን። አሜን።'),
  ('306aa494-9c6c-55a3-aa36-400ea5408d33', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 1, 1, 'በእግዚአብሔር ፈቃድ የኢየሱስ ክርስቶስ ሐዋርያ ከሆነ ጳውሎስና ከወንድማችን ጢሞቴዎስ በቆሮንቶስ ሀገር ላለችው የእግዚአሔር ቤተ ክርስቲያንና በአካይያ ሀገር ላሉ ቅዱሳን ሁሉ፥'),
  ('81a7ecdc-dba7-543c-ac48-8d015422cce5', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 2, 2, 'ከአባታችን ከእግዚአብሔርና ከጌታችን ከኢየሱስ ክርስቶስ ሰላምና ጸጋ ለእናንተ ይሁን።'),
  ('d3e87a87-5107-52be-aae6-7260b2735733', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 3, 3, 'የምሕረት አባት፥ የመጽናናትም ሁሉ አምላክ የጌታችን የኢየሱስ ክርስቶስ አባት እግዚአብሔር ይመስገን።'),
  ('008db53f-d4b5-59e1-a0db-bf16edeec5ab', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 4, 4, 'እግዚአብሔር በአጽናናን በዚያ መጽናናት በመከራ ያሉትን ሁሉ ማጽናናት እንችል ዘንድ ከመከራችን ሁሉ ያጽናናን እርሱ ይመስገን።'),
  ('0bec1cc7-1249-589d-acb7-c8f6487f9732', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 5, 5, 'የክርስቶስ መከራ በእኛ ላይ እንደ በዛ መጠን እንዲሁ መጽናናታችንም በክርስቶስ ይበዛልና።'),
  ('d7dc2752-ddd4-53dc-adb4-1d85005c0c43', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 6, 6, 'መከራ ብንቀበልም እናንተ እንድትድኑና እንድትጽናኑ ነው፤ ብንጽናናም እኛ የተቀበልነውን ያን መከራ በመታገሥ ስለሚደረግ መጽናናታችሁ ነው።'),
  ('6581546b-da67-516a-a267-c56c08cdd44c', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 7, 7, 'ስለ እናንተ ያለን ተስፋም የጸና ነው፤ መከራችንን እንደ ተካፈላችሁ መጠን፥ እንዲሁ በመጽናናታችንም እንደምትተባበሩ እናውቃለን።'),
  ('d7c72082-b3cc-5a45-a6cb-99f333db3c82', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 8, 8, 'ወንድሞቻችን ሆይ፥ በእስያ መከራ እንደ ተቀበልን ልታውቁ እወዳለሁ፤ ለሕይወታችን ተስፋ እስክንቈርጥ ድረስ ከዐቅማችን በላይ እጅግ መከራ ጸንቶብን ነበርና።'),
  ('a98d9c0b-3336-5eb4-a19c-06954ffe1009', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 9, 9, 'ሙታንን በሚያስነሣቸው በእግዚአብሔር እንጂ በራሳችን እንዳንታመን በውስጣችን ለመሞት ቈርጠን ነበር።'),
  ('64688ddb-010c-5764-afbd-42aa49b5d517', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 10, 10, 'እርሱም እንዲህ ካለ ሞት አዳነን፤ ያድነንማል፤ አሁንም እንደሚያድነን እርሱን እንታመናለን።'),
  ('d3c4a8e2-70f3-5170-ade3-a51aada74de5', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 11, 11, 'በብዙዎች ጸሎት ጸጋን እናገኝ ዘንድ፥ ብዙዎችም በእኛ ፋንታ ያመሰግኑ ዘንድ እናንተ በጸሎታችሁ ርዱን።'),
  ('56bc1d8b-6880-5030-aea4-0818e562fe29', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 12, 12, 'በእግዚአብሔር ቸርነትና ይቅርታ መመኪያችንና የነፃነታችን ምስክር ይህቺ ናትና፥ በሥጋዊ ጥበብ ሳይሆን፥ በእግዚአብሔር ጸጋ በዚህ ዓለም፥ ይልቁንም በእናንተ ዘንድ ተመላለስን።'),
  ('4bf9abe7-76ec-59c4-af25-e0e8a7567d28', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 13, 13, 'የምታነቡትንና የምታውቁትን ነው እንጂ፥ ሌላ የምንጽፍላችሁ የለምና፥ ይህንም እስከ ፍጻሜ እንደምታስተውሉት ተስፋ አደርጋለሁ።'),
  ('a1353f8f-0f21-589c-a026-d3f389c24e11', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 14, 14, 'እኛ መመኪያችሁ እንደሆን፥ እንዲሁ እናንተም በጌታችን በኢየሱስ ክርስቶስ ቀን መመኪያችን እንድትሆኑ በከፊል እንዳወቃችሁ ተስፋ እናደርጋለን።'),
  ('2eca5a23-28ef-574a-a22f-1fcc80d15fe3', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 15, 15, 'በዚህም ታምኜ ጸጋን በዕጥፍ እንድታገኙ በመጀመሪያ ወደ እናንተ እመጣ ዘንድ መከርሁ።'),
  ('030df19b-24bf-52a8-a507-71e41d441961', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 16, 16, 'በእናንተም በኩል ወደ መቄዶንያ እንዳልፍ፥ ዳግመኛም ከመቄዶንያ እንድመለስና እናንተም ደግሞ ወደ ይሁዳ ሀገር ትሸኙኝ ዘንድ መከርሁ።'),
  ('a273564b-ee73-5f9c-afa8-0dfa8b632b5c', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 17, 17, 'እንግዲህ ይህን የመከርሁ በውኑ የሠራሁት እንደ አላዋቂ ሰው ሆኜ ነውን? ወይስ በእኔ በኩል አዎን አዎን፥ አይደለም አይደለም ማለት እንዲሆን ያን የምመክረው ለሰው ይምሰል ነውን?'),
  ('2d3031be-9b67-5c1e-aad7-4d1bca605d7e', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 18, 18, 'እግዚአብሔር የታመነ ነው፤ ለእናንተም የሚነገረው ቃላችን እውነትና ሐሰት አልተቀላቀለበትም።'),
  ('dc915968-3c6a-57ac-af8f-ba3ba7d0c57c', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 19, 19, 'እኛ ማለት እኔ ጳውሎስ፥ ስልዋኖስና ጢሞቴዎስ የሰበክንላችሁ የእግዚአብሔር ልጅ ኢየሱስ ክርስቶስ እውነትና ሐሰት አይደለም፤ ነገር ግን ስለ እርሱ ያስተማርነው እውነት ነው።'),
  ('d1565004-8c1e-5b5b-a0f9-3b02d32a30e0', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 20, 20, 'እግዚአብሔር የሰጠው ተስፋ ሁሉ በክርስቶስ እውነት ሆኖአልና፤ ስለዚህም በእርሱ ለእግዚአብሔር ክብር አሜን እንላለን።'),
  ('adab1986-edf6-54db-a293-31080bb6a2a0', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 21, 21, 'ከእናንተ ጋር በክርስቶስ ስም የሚያጸናንና የቀባን እግዚአብሔር ነው።'),
  ('9c7da0cc-2469-5c3a-a47f-2ea9cb26c2c8', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 22, 22, 'ደግሞም ያተመንና የመንፈስ ቅዱስን ፈለማ በልቡናችን የሰጠን እርሱ ነው።'),
  ('0bfe8347-8fb1-55db-ae3e-82f11c13c20a', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 23, 23, 'እኔ ለእናንተ በመራራት ወደ ቆሮንቶስ እንዳልመጣሁ፥ ስለ ራሴ እግዚአብሔርን ምስክር አደርገዋለሁ።'),
  ('c8ea6c49-9359-55e7-a139-d8a3bc67c93f', '65366d62-7de5-5c6b-a13b-c56883d7900f', '041b667c-5360-5b85-adb0-bca155a655d0', 24, 24, 'ደስ የሚላችሁን እንድታደርጉ እንረዳችኋለን እንጂ እንድታምኑ ግድ የምንላችሁ አይደለም፤ በእምነት ቆማችኋልና።'),
  ('39709954-87ee-5335-a724-047b5deafb40', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 1, 1, 'እንግዲህ እያዘንሁ ወደ እናንተ እንዳልመጣ በልቤ ይህን ወሰንሁ።'),
  ('8a4799a5-e764-522c-af4f-82c93bc75395', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 2, 2, 'እኔ ካሳዘንኋችሁማ እኔ ካሳዘንሁት በቀር ማን ደስ ያሰኘኛል?'),
  ('0a4fad89-a762-5245-af40-5cdd14f8d6d7', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 3, 3, 'የእኔ ደስታ የሁላችሁ እንደ ሆነ በሁላችሁ አምኛለሁና በመጣሁ ጊዜ ደስ ሊያሰኙኝ ከሚገባቸው ኀዘን እንዳያገኘኝ ይህን ጻፍሁላችሁ።'),
  ('ecea1bef-1865-5c81-af9d-2f36e99317e4', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 4, 4, 'ከብዙ መከራና ከልብ ጭንቀት የተነሣ በብዙ እንባ ይህን ጽፌላችኋለሁ፤ ነገር ግን እጅግ እንደምወዳችሁ እንድታውቁ ነው እንጂ እንድታዝኑ አይደለም።'),
  ('5abbcdc9-20a2-5b99-a88b-df3c988aebe7', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 5, 5, 'ማንም ያሳዘነኝ ቢሆን፥ እኔን ብቻ ያሳዘነ አይደለም። ከእናንተ አንድ ሳይቀር ሁላችሁንም አሳዘነ እንጂ፤ አሁንም ሥርዐት አላጸናባችሁም።'),
  ('4209aa88-8619-5ec4-a4b3-797dbeba3144', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 6, 6, 'እንደዚህ ላለው ሰው ከእናንተ ከብዙዎች ያገኘችው ይህች ተግሣጽ ትበቃዋለች።'),
  ('174ce9dd-f00f-5e47-a4ee-6c584586ebf3', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 7, 7, 'ደግሞም እንዲህ ያለው ሰው ከኀዘን ብዛት የተነሣ እንዳይዋጥ ይቅር ልትሉትና ልታጽናኑት ይገባል።'),
  ('b280de7f-5228-5fac-ae89-67ba84c966e7', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 8, 8, 'ስለዚህም ከእርሱ ጋር ፍቅርን እንድታጸኑ እማልዳችኋለሁ።'),
  ('735c3c71-2757-51c3-aa8f-839d410af20f', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 9, 9, 'ስለዚህም በሁሉ ትታዘዙኝ እንደ ሆነ፥ ፈቃዳችሁን ዐውቅ ዘንድ ጻፍሁላችሁ።'),
  ('8c81534c-6073-56e8-a98d-bc1651b13be1', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 10, 10, 'ይቅር የምትሉት ቢኖር፥ እኔም ከእናንተ ጋር ይቅር እለዋለሁ፤ እኔም ይቅር ያልሁትን በክርስቶስ ፊት ስለ እናንተ ይቅር ብያለሁ።'),
  ('bfe453aa-8c62-5ffe-a2c7-048e43835c2f', '638a7e33-5722-532d-a2de-8bd62d037c72', '50a500e8-7bca-5ace-ac89-0e2cd4c30786', 11, 11, 'ሰይጣን እንዳያታልለን አሳቡን የምንስተው አይደለምና።'),
  ('b654c88e-442d-51db-a1f0-2dea0856fc8d', '638a7e33-5722-532d-a2de-8bd62d037c72', '3de616b6-4678-51fe-acdd-1f48d50f7280', 1, 12, 'ለክርስቶስም ወንጌል ጢሮአዳ በደረስሁ ጊዜ በእግዚአብሔር በሩ ተከፈተልኝ።'),
  ('773ca1f0-d7fb-53cd-a7a1-5c39f083287d', '638a7e33-5722-532d-a2de-8bd62d037c72', '3de616b6-4678-51fe-acdd-1f48d50f7280', 2, 13, 'ወንድሜን ቲቶን ስላላገኘሁት ለሰውነቴ ዕረፍት አላገኘሁም፤ ነገር ግን ከእርሱ ተለይች ወደ መቄዶንያ ሄድሁ።'),
  ('9a2f106d-bb2d-5e8b-ad02-813a982f1828', '638a7e33-5722-532d-a2de-8bd62d037c72', 'c26f73fd-9808-5228-afc4-8b17ad652914', 1, 14, 'በጌታችን በኢየሱስ ክርስቶስ ዘወትር ድል በመንሣቱ የሚጠብቀን፥ በየሀገሩም ሁሉ የዕውቀቱን መዓዛ በእኛ የሚገልጥ እግዚአብሔር ይመስገን።'),
  ('55f22ce1-f862-557c-a107-bdc527bb5832', '638a7e33-5722-532d-a2de-8bd62d037c72', 'c26f73fd-9808-5228-afc4-8b17ad652914', 2, 15, 'በሚድኑትና በሚጠፉት ዘንድ ለእግዚአብሔር የክርስቶስ መዓዛ እኛ ነንና።'),
  ('68fc18e3-76f4-5090-a21e-a6759fadbf81', '638a7e33-5722-532d-a2de-8bd62d037c72', 'c26f73fd-9808-5228-afc4-8b17ad652914', 3, 16, 'የሞት መዓዛ የሚገባቸው ለሞት፥ የሕይወት መዓዛ የሚገባቸውም ለሕይወት ናቸው፤ ነገር ግን ይህ የሚገባው ማነው?'),
  ('fdb13371-36e5-5d90-ad00-d664fa85ba2f', '638a7e33-5722-532d-a2de-8bd62d037c72', 'c26f73fd-9808-5228-afc4-8b17ad652914', 4, 17, 'የእግዚአብሔርን ቃል በሌላ ቀላቅለው እንደሚሸቅጡ እንደ ብዙዎች አይደለንምና፤ በቅንነት ግን ከእግዚአብሔር እንደ ተላከ በእግዚአብሔር ፊት በክርስቶስ እንናገራለን።'),
  ('7d61d75f-ad9c-5110-a5c3-72bb100be9ef', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'b581583c-2419-597e-abf4-01fdab37fc90', 1, 1, 'ወንድሞቻችን አሁን ደግሞ ራሳችንን እያመሰገን ልንነግራችሁ እንጀምራለንን? ወይስ እንደ ሌሎች ስለ እኛ ወደ እናንተ ደብዳቤ እንዲጽፉላችሁ፥ ወይስ እናንተ ትጽፉልን ዘንድ የምንሻው አለን?'),
  ('0998e8e0-8dd9-5ee5-ac21-48be0ed859b6', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'b581583c-2419-597e-abf4-01fdab37fc90', 2, 2, 'የእኛስ መጽሐፋችን እናንተ ናችሁ፤ በልባችን ውስጥም ተጽፋችኋል፤ ትታወቃላችሁም፤ ሰውም ሁሉ ያነብባችኋል።'),
  ('ccf85a8e-50e0-5807-a51c-850cefbb18ec', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'b581583c-2419-597e-abf4-01fdab37fc90', 3, 3, 'እናንተ ራሳችሁም በእኛ የተላከች የክርስቶስ መልእክት እንደ ሆናችሁ ያውቃሉ፤ ይህቺውም የተጻፈች በሕያው እግዚአብሔር መንፈስ ነው እንጂ በቀለም አይደለም፤ በሥጋ ልብ ሠሌዳነት ነው እንጂ በድንጋይ ሠሌዳም አይደለም።'),
  ('73c96916-a0c0-55a3-aa95-6baad920a186', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'b581583c-2419-597e-abf4-01fdab37fc90', 4, 4, 'ነገር ግን በክርስቶስ በኩል በእግዚአብሔር ዘንድ እንዲህ ያለ እምነት አለን።'),
  ('20bcf03d-fc51-5d60-af70-896770edc57d', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'b581583c-2419-597e-abf4-01fdab37fc90', 5, 5, 'ኀይላችን ከእግዚአብሔር ስለ ሆነ ከእኛ ከራሳችን እንደ ሆነ አድርገን ምንም ልናስብ አይገባንም።'),
  ('012d019c-7f3a-54fc-aa88-71c3297f8eb3', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'b581583c-2419-597e-abf4-01fdab37fc90', 6, 6, 'በመንፈስ እንጂ በፊደል ለማይሆን ለአዲስ ሕግ አገልጋዮች አደረገን፤ ፊደል ይገድላል፥ መንፈስ ግን ሕያው ያደርጋል።'),
  ('fdc1327e-78cc-5f02-a9c8-07642e3734cd', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 1, 7, 'ስለዚያ ስለ አለፈው የፊቱ ብርሃን የእስራኤል ልጆች የሙሴን ፊት መመልከት እስኪሳናቸው ድረስ በዚያች በድንጋይ ላይ በፊደል ለተቀረጸች ለሞት መልእክት ክብር ከተደረገላት፥'),
  ('78a4c355-1f3f-53ea-af80-c33c18870067', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 2, 8, 'ለመንፈስ ቅዱስ መልእክትማ ምንኛ እጅግ ክብር ሊደረግ ይገባ ይሆን?'),
  ('0a80ea29-9c47-5d80-a1af-5449e04e20a2', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 3, 9, 'ኵነኔን ለምታመጣ መልእክት ብዙ ክብር ከተደረገላት የጽድቅ መልእክትማ ምን ያህል ትከብርና ትመሰገን ይሆን?'),
  ('177ebb4d-c459-5be4-ab63-0022121f663e', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 4, 10, 'በዚህ ፍጹም ክብር ባነጻጸሯት ጊዜ የከበረችው እንዳልከበረች ትሆናለችና።'),
  ('2e7bbfee-dd91-5c33-a4c4-b4a8b98756a7', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 5, 11, 'ያ የሚያልፈው ክብር ካገኘ፥ ያ ጸንቶ የሚኖረውማ እንዴት እጅግ ክብር ያገኝ ይሆን?'),
  ('c3cb684b-4efd-5176-ab85-b75495bbd323', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 6, 12, 'እንግዲህ ይህን ያህል ተስፋ ካለን በግልጥ ፊት ለፊት ልንቀርብ እንችላለን።'),
  ('a9501b7c-c461-5da3-ac8c-fd215f1f5fb4', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 7, 13, 'የዚያን ይሻር የነበረውን መጨረሻ፥ የእስራኤል ልጆች እንዳያዩት ፊቱን ይሸፍን እንደ ነበረው እንደ ሙሴ አይደለም።'),
  ('afd0c86c-db39-57fc-a943-8a366bcc7cf7', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 8, 14, 'ነገር ግን እስከ ዛሬ ድረስ ልባቸው ተሸፍኖአል፤ ያም መጋረጃ ብሉይ ኪዳን በተነበበት ዘመን ሁሉ ጸንቶ ኖሮአል፤ ክርስቶስ እስኪያሳልፈው ድረስ አልተገለጠምና።'),
  ('62ac82cd-d184-5c45-a58c-77ba2147c2ec', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 9, 15, 'እስከ ዛሬም የሙሴን ሕግ ሲያነብቡ ያ መጋረጃ ልባቸውን ይሸፍናቸዋል።'),
  ('2f7e7987-fe43-5aa9-a683-1fe7086f98ec', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 10, 16, 'ወደ እግዚአብሔር በተመለሱ ጊዜ ግን ያ መጋረጃ ከእነርሱ ይርቃል።'),
  ('e470e109-ab7f-5427-a426-e9a8bcd60353', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 11, 17, 'እግዚአብሔር መንፈስ ነውና፥ የእግዚአብሔር መንፈስ ባለበትም በዚያ ነፃነት አለ።'),
  ('b5c5f183-20a9-58bd-aebb-485c8485f828', 'efbbafef-9f4b-574d-a38d-63a57e5e8b63', 'f40ec17e-b3d5-5567-af7b-541962a2e3c8', 12, 18, 'እኛስ ሁላችን ፊታችንን ገልጠን በመስተዋት እንደሚያይ የእግዚአብሔርን ክብር እናያለን፤ ከእግዚአብሔር መንፈስ እንደ ተሰጠን መጠን የእርሱን አርአያ እንመስል ዘንድ ከክብር ወደ ክብር እንገባለን።'),
  ('3b043587-e421-5fee-aa2b-768a289755af', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '04c5e25a-339d-5ac3-a1ec-62c30f6501ec', 1, 1, 'ስለዚህ እንደ ቸርነቱ የሰጠን ይህ መልእክት አለንና አንሰለችም።'),
  ('37e43dcc-ce53-527a-a3d0-322383ce039f', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '04c5e25a-339d-5ac3-a1ec-62c30f6501ec', 2, 2, 'ነገር ግን በስውር የሚሠራውን አሳፋሪ ሥራ እንተወው፤ በተንኰልም አንመላለስ፤ የእግዚአብሔርንም ቃል በውሸት አንቀላቅል፤ ለሰውም ሁሉ አርአያ ስለ መሆን እውነትን ገልጠን በእግዚአብሔር ፊት ራሳችንን እናጽና።'),
  ('cebb9a2c-f170-5576-aec2-f5608ab18ef5', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '04c5e25a-339d-5ac3-a1ec-62c30f6501ec', 3, 3, 'ወንጌላችን የተሰወረ ቢሆንም እንኳ፥ የተሰወረባቸው ለሚጠፉት ነው።'),
  ('baa43662-15e3-5b60-af5b-52845410129b', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '04c5e25a-339d-5ac3-a1ec-62c30f6501ec', 4, 4, 'እግዚአብሔርን የሚመስለው የክርስቶስ የክብሩ ወንጌል ብርሃን እንዳያበራላቸው የዚህ ዓለም አምላክ ልባቸውን አሳውሮአልና።'),
  ('7b8a7e0e-25f4-559f-aac2-e1d03c458e21', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '04c5e25a-339d-5ac3-a1ec-62c30f6501ec', 5, 5, 'ኢየሱስ ክርስቶስን ጌታ እንደ ሆነ እንሰብካለን እንጂ ራሳችንን የምንሰብክ አይደለም፤ ስለ ኢየሱስ ክርስቶስም ብለን ራሳችንን ለእናንተ አስገዛን።'),
  ('2eb15d7c-1797-5e85-a6e8-3e495e7bba9f', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '04c5e25a-339d-5ac3-a1ec-62c30f6501ec', 6, 6, 'በጨለማ ውስጥ “ብርሃን ይብራ” ያለ እግዚአብሔር በኢየሱስ ክርስቶስ ፊት የክብሩን ዕውቀት ብርሃን በልባችን አብርቶልናልና።'),
  ('f355af04-c529-5aef-a829-e90a307e4b40', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 1, 7, 'ነገር ግን ከእኛ ያይደለ ከእግዚአብሔር የተገኘ ታላቅ ኀይል ይሆን ዘንድ በሸክላ ዕቃ ውስጥ ይህ መዝገብ አለን።'),
  ('36ce6a0d-d5cd-5b35-af35-2ddb8fb484cc', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 2, 8, 'በሁሉ መከራን እንቀበላለን፤ ነገር ግን አንጨነቅም፤ እንናቃለን፥ ነገር ግን ተስፋ አንቈርጥም።'),
  ('7758ee33-4688-571c-a082-d052c44cb5c3', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 3, 9, 'እንሰደዳለን፤ ነገር ግን አንጣልም፤ እንወድቃለን፤ ነገር ግን አንጠፋም።'),
  ('a401b4d1-92d1-597f-a50d-e997b7e0abb3', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 4, 10, 'የክርስቶስ ሕይወቱ በዚህ በሟች ሰውነታችን ላይ ይገለጥ ዘንድ፥ ዘወትር የክርስቶስን ሞት በሥጋችን እንሸከማለን።'),
  ('719eca0b-547c-50f5-a52a-8b4f833c87b3', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 5, 11, 'በሕይወት የምንኖር እኛም በሟች ሰውነታችን ላይ የኢየሱስ ክርስቶስ ሕይወቱ ይገለጥ ዘንድ፥ ዘወትር ስለ ኢየሱስ ክስርቶስ ብለን ተላልፈን ለሞት እንሰጣለን።'),
  ('63c14571-029a-5a7c-a0e3-979631dd6d35', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 6, 12, 'ስለዚህም ሞት በእኛ ላይ፥ ሕይወትም በእናንተ ላይ ይሠራል።'),
  ('a7c1cf95-1286-5897-a90d-563527b98d08', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 7, 13, 'አንድ የእምነት መንፈስ አለን፤ መጽሐፍ፥ “አመንሁ፤ ስለዚህም ተናገርሁ” እንዳለ እኛም አመን፤ ስለዚህም ተናገርን።'),
  ('862b57d8-2b4c-583e-a038-4d3cf0e9bd08', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 8, 14, 'ጌታችን ኢየሱስ ክርስቶስን ያስነሣው እርሱ እኛንም እንደ እርሱ እንዲያስነሣን፥ ከእናንተም ጋር በፊቱ እንዲያቆመን እናውቃለን።'),
  ('c15e88b3-d8ff-589b-a303-5fc3c64130c9', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', 'c8dbb4fd-0f82-54c0-acfe-5bac802b68e1', 9, 15, 'ጸጋው በብዙዎች ላይ ትትረፈረፍ ዘንድ፥ የእግዚአብሔርም የክብሩ ምስጋና ይበዛ ዘንድ ሁሉ ስለ እናንተ ነውና።'),
  ('eae60658-a5d3-5917-ac1a-6d6b0b652367', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '6de5ac34-54e6-5af1-a01c-cec3a959c2ef', 1, 16, 'ስለዚህ አንሰልች፤ በውጭ ያለው ሰውነታችን ያረጃልና፤ በውስጥ ያለው ሰውነታችን ግን ዘወትር ይታደሳል።'),
  ('c58e4236-0947-5136-aaa1-ec18d88021bf', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '6de5ac34-54e6-5af1-a01c-cec3a959c2ef', 2, 17, 'ቀላል የሆነው የጊዜው መከራችን ክብርንና ጌትነትን ለዘለዓለም አብዝቶ ያደርግልናልና።'),
  ('fa3ecc38-d829-506e-a3aa-b818275e3b11', 'ccd367d6-7e77-599d-a763-d6eb90aaee1e', '6de5ac34-54e6-5af1-a01c-cec3a959c2ef', 3, 18, 'የማይታየውን እንጂ የሚታየውን ተስፋ አናደርግም፤ የሚታየው ኀላፊ ነውና፥ የማይታየው ግን ለዘለዓለም የሚኖር ነው።'),
  ('45ad0826-2222-549d-adb8-cbde9f69741f', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 1, 1, 'በምድር ያለው ማደሪያ ቤታችን ቢፈርስም፥ በሰማይ በእግዚአብሔር ዘንድ የሰው እጅ ያልሠራው ዘለዓለማዊ ቤት እንዳለን እናውቃለን።'),
  ('16a2e8d7-f95a-5508-a006-7ee7342b5836', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 2, 2, 'ስለ እርሱ የምንደክምለትን በሰማይ ያለውን ቤታችንን እንለብስ ዘንድ እርሱን ተስፋ እናደርጋለን።'),
  ('61e02abe-4806-5c67-a992-df45025fa7a2', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 3, 3, 'ከለበስነውም በኋላ ዕራቍታችንን የምንገኝ አይደለንም።'),
  ('a64247ce-aa7e-5931-a762-b88db73a3994', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 4, 4, 'በዚህ ቤት ውስጥ ሳለንም ከከባድነቱ የተነሣ እጅግ እናዝናለን፤ ነገር ግን ሟች በሕይወት ይዋጥ ዘንድ ሌላ ልንለብስ እንጂ ልንገፈፍ አንወድም።'),
  ('c9855108-cdd5-57f3-a2aa-09bf62e9a178', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 5, 5, 'ለዚህም ያዘጋጀን እግዚአብሔር ነው፤ እርሱም የመንፈስ ቅዱስን ፈለማ ሰጠን።'),
  ('e0da2c4a-6d7b-5795-af01-6483a6802ef5', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 6, 6, 'እንግዲህ ሁልጊዜ እመኑ፥ ጨክኑም፤ በዚህ ሥጋ ሳላችሁም እናንተ እንግዶች እንደ ሆናችሁ ታውቃላችሁ፤ ከሥጋችሁም ተለይታችሁ ወደ ጌታችን ትሄዳላችሁ።'),
  ('7ca6c2ff-8b3d-51a8-a1d4-7bc04ef95f19', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 7, 7, 'በእምነት እንኖራለን፤ በማየትም አይደለም።'),
  ('675df1c3-a2ef-504b-ac07-d49293711286', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 8, 8, 'ታምነናል፤ ይልቁንም ከሥጋችን ተለይተን ወደ ጌታችን እንሄዳለንና ደስ ይለናል።'),
  ('d773fe8d-bfb1-51f6-add5-cc55c4843215', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 9, 9, 'አሁንም ብንኖርም፥ ብንሞትም እርሱን ደስ ለማሰኘት እንጥራለን።'),
  ('a2e7052a-9193-5506-a9cc-6aedbd77cb85', '1103659c-a5c1-5a40-af36-888e753a2629', 'a033a36e-cfa0-527b-a27d-b960e1458255', 10, 10, 'መልካም ቢሆን፥ ክፉም ቢሆን በሥጋችን እንደ ሠራነው ዋጋችንን እንቀበል ዘንድ፥ ሁላችን በክርስቶስ የፍርድ ዙፋን ፊት እንቆማለንና።'),
  ('bd413c50-1d99-5231-af4c-f39f27cde3bc', '1103659c-a5c1-5a40-af36-888e753a2629', '09d168e1-6978-582a-a01a-39e8dd5f6771', 1, 11, 'እግዚአብሔርን መፍራት ዐውቀን ሰዎችን እናሳምናለን፤ ለእግዚአብሔር ግን እኛ የተገለጥን ነን፤ እንዲሁም በልቡናችሁ የተገለጥን እንደ ሆን እንታመናለን።'),
  ('3df8a9d4-b867-59d5-a7e0-e37c71571b91', '1103659c-a5c1-5a40-af36-888e753a2629', '09d168e1-6978-582a-a01a-39e8dd5f6771', 2, 12, 'በዚህ ደግሞ በእናንተ ዘንድ ራሳችንን የምናመሰግን አይደለም፤ ነገር ግን እኛ እንደምንመካባችሁ፥ እናንተም በእኛ እንድትመኩ፥ ከልብ ሳይሆን ለሰው ይምሰል በሚመኩ ሰዎች ዘንድ መልስ እንዲሆናችሁ ምክንያትን እንሰጣችኋለን።'),
  ('66924999-6abf-56c5-aa29-4af1f7427e74', '1103659c-a5c1-5a40-af36-888e753a2629', '09d168e1-6978-582a-a01a-39e8dd5f6771', 3, 13, 'እኛ ሰነፎች ብንሆንም፥ ስንፍናችን ለእግዚአብሔር ነው፤ ዐዋቂዎች ብንሆንም ዐዋቂነታችን ለእናንተ ነው።'),
  ('fb550e6f-02a2-514a-a86a-5a71f5d21254', '1103659c-a5c1-5a40-af36-888e753a2629', '09d168e1-6978-582a-a01a-39e8dd5f6771', 4, 14, 'የክርስቶስ ፍቅር በዚህ አሳብ እንድንጸና ያስገድደናል፤ ሁሉ ፈጽመው ስለ ሞቱ አንዱ ስለ ሁሉ ቤዛ ሆኖ ሞቶአልና።'),
  ('ffe659fa-4b54-54be-afd5-794bd5bd428e', '1103659c-a5c1-5a40-af36-888e753a2629', '09d168e1-6978-582a-a01a-39e8dd5f6771', 5, 15, 'በሕይወት የሚኖሩትም ስለ እነርሱ ቤዛ ሆኖ ለሞተውና ለተነሣውም እንጂ ወደፊት ለራሳቸው የሚኖሩ እንዳይሆኑ እርሱ ስለ ሁሉ ቤዛ ሆኖ ሞተ።'),
  ('56db3a73-5c45-5cb8-ab05-1bfa12c560c4', '1103659c-a5c1-5a40-af36-888e753a2629', '09d168e1-6978-582a-a01a-39e8dd5f6771', 6, 16, 'ስለዚህ ከአሁን ጀምሮ በሥጋ የምናውቀው የለም፤ ክርስቶስንም በሥጋ ብናውቀው አሁን ግን ከእንግዲህ ወዲህ የምናውቀው አይደለም።'),
  ('b1a9accc-0731-52b5-a76e-51a967cce467', '1103659c-a5c1-5a40-af36-888e753a2629', '09d168e1-6978-582a-a01a-39e8dd5f6771', 7, 17, 'አሁንም በክርስቶስ የሆነው ሁሉ አዲስ ፍጥረት ነው፤ የቀደመውም አለፈ፤ እነሆ ሁሉም አዲስ ሆነ።'),
  ('e18570a3-cde3-521a-a12a-0f34e1ca7b6f', '1103659c-a5c1-5a40-af36-888e753a2629', '86181655-e08d-58d7-a6eb-d7382bad1f49', 1, 18, 'ነገር ግን ሁሉ በክርስቶስ ከራሱ ጋር ከአስታረቀን፥ የማስታረቅ መልእክትንም ከሰጠን ከእግዚአብሔር ዘንድ ነው።'),
  ('5f98e566-30b4-5fda-a60a-651afb564ebd', '1103659c-a5c1-5a40-af36-888e753a2629', '86181655-e08d-58d7-a6eb-d7382bad1f49', 2, 19, 'ኀጢአታቸውን ይቅር ብሎ በደላቸውንም ሳያስብ እግዚአብሔር በክርስቶስ ዓለሙን ከራሱ ጋር አስታርቆአልና፤ የዕርቅ ቃሉንም በእኛ ላይ አደረገ፤ የይቅርታውንም መልእክት ሰጠን።'),
  ('afa328a0-0717-53f5-a5cf-73783f2711cd', '1103659c-a5c1-5a40-af36-888e753a2629', '86181655-e08d-58d7-a6eb-d7382bad1f49', 3, 20, 'እኛስ በክርስቶስ አምሳል እንለምናለን፤ እግዚአብሔርም በእኛ መጽናናትን ይሰጣችኋል፤ ከእግዚአብሔርም ጋር ትታረቁ ዘንድ በክርስቶስ እንለምናችኋለን።'),
  ('b152fd32-bebb-5f1d-ad21-b27ef891fa36', '1103659c-a5c1-5a40-af36-888e753a2629', '86181655-e08d-58d7-a6eb-d7382bad1f49', 4, 21, 'ኀጢአት የሌለበት እርሱ እኛን ለእግዚአብሔር ያጸድቀን ዘንድ ስለ እኛ ራሱን እንደ ኃጥእ አድርጓልና።'),
  ('f1d7f27f-0957-5a78-a159-1b6188bf025b', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 1, 1, 'ከእርሱም ጋር አብረን እየሠራን፥ የተቀበላችኋትን የእግዚአብሔር ጸጋ ለከንቱ እንዳታደርጓት እንማልዳችኋለን።'),
  ('9b79973d-894c-51dc-ac7b-065f4f86c4aa', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 2, 2, 'እንዲህ ብሎአልና፥ “በተመረጠችው ቀን ሰማሁህ፤ በመዳንም ቀን ረዳሁህ” እነሆ፥ የተመረጠችው ቀን ዛሬ ናት።'),
  ('385c44d8-9bf7-5bd1-a506-fa55ff525130', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 3, 3, 'አገልግሎታችንም እንዳይነቀፍ፥ በአንዳች ነገር ማሰናከያ እንዳንሰጥ እንጠንቀቅ።'),
  ('4284eebf-5c43-5775-a809-2f9397323eb1', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 4, 4, 'ነገር ግን በሁሉ ራሳችንን አቅንተን፥ የእግዚአብሔር አገልጋዮች እንሁን፤ በብዙ ትዕግሥትና በመከራ፥ በችግርና በጭንቀት ሁሉ፥'),
  ('8d952946-9db9-5f23-a64f-3c06afaca393', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 5, 5, 'በመገረፍና በመታሰር፥ በድካምና በመታወክ፥ በመትጋትና በመጾም፥'),
  ('40ba8795-f58d-5e50-a990-4b1a1e2a94c5', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 6, 6, 'በንጽሕናና በዕውቀት፥ በምክርና በመታገሥ፥ በቸርነትና በመንፈስ ቅዱስ፥ አድልዎ በሌለበት ፍቅር፥'),
  ('47c444e7-c3f9-5c7e-ac3d-d4de04ecbcb3', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 7, 7, 'በእውነት ቃል፥ በእግዚአብሔር ኀይል ለቀኝና ለግራ በሚሆን የጽድቅ የጦር ዕቃ፥'),
  ('70e15695-7eb3-50f9-af5f-410cdb94c962', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 8, 8, 'በክብርና በውርደት፥ በምርቃትና በርግማን፥ እንደ አሳቾች ስንታይ እውነተኞች ነን።'),
  ('5d003a45-bae8-5f98-a748-a5d682c8948a', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 9, 9, 'እንደማይታወቁ ስንታይ የታወቅን ነን፤ እንደ ሰነፎች ስንታይም ልባሞች ነን፤ እንደ ሙታን ስንታይ ሕያዋን ነን፤ የተቀጣን ስንሆንም አንገደልም።'),
  ('94619c45-6b29-5641-ac13-90447c53883b', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'a45871d4-1a9a-5ec0-ab40-63d456ee1d05', 10, 10, 'ኀዘንተኞች ስንሆን ዘወትር ደስተኞች ነን፤ እንደ ድሆች ስንሆን ብዙዎችን እናበለጽጋለን፤ ምንም የሌለን ስንሆን ሁሉ በእጃችን ነው።'),
  ('7f837ce2-9656-55c9-a264-76a6ce220f2b', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', '06d74f53-7905-56be-a783-76851d31afbe', 1, 11, 'የቆሮንቶስ ሰዎች ሆይ፥ ለእናንተ አፋችን የተከፈተ ነው፤ ልባችንም የሰፋ ነው።'),
  ('b8f19cd6-e8be-5cc6-ab73-ec6cfb5418ce', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', '06d74f53-7905-56be-a783-76851d31afbe', 2, 12, 'ከእናንተ የደረሰ ኀዘን በእኛ የለም፤ ከእኛም በእናንተ ላይ የደረሰ ኀዘን የለም፤ ነገር ግን በልባችሁ አዝናችኋል።'),
  ('71247b6b-8d88-5d8f-a5f2-ea829094b7ac', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', '06d74f53-7905-56be-a783-76851d31afbe', 3, 13, 'ልጆች እንደ መሆናችሁ፥ ይህን እላችኋለሁ፤ ከእናንተ ላይ ስለሚገባኝ ብድራቴ እናንተ ፍቅራችሁን አስፉልኝ።'),
  ('5e52c8d6-3f58-50be-afd1-fb41ace8a945', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'ed9f0ac4-0510-5a40-ab6e-4a75e3058cf5', 1, 14, 'ተጠራጣሪዎች አትሁኑ፤ ወደማያምኑ ሰዎች አንድነትም አትሂዱ፤ ጽድቅን ከኀጢአት ጋር አንድ የሚያደርጋት ማን ነው? ብርሃንንስ ከጨለማ ጋር የሚቀላቅል ማን ነው?'),
  ('23c9e8a7-3763-5b0c-a95b-7ebe4c964c9c', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'ed9f0ac4-0510-5a40-ab6e-4a75e3058cf5', 2, 15, 'ክርስቶስን ከቤልሆር ጋር አንድ የሚያደርገው ማን ነው? ወይስ ምእመናንን ከመናፍቃን ጋር አንድ ወገን የሚያደርጋቸው ማን ነው?'),
  ('037cc53e-6cae-5c14-a4f9-ced574009e1f', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'ed9f0ac4-0510-5a40-ab6e-4a75e3058cf5', 3, 16, 'የእግዚአብሔርን ታቦትስ በጣዖት ቤት ውስጥ የሚያኖር ማን ነው? የሕያው እግዚአብሔር ማደሪያዎች እኛ አይደለንምን? እግዚአብሔር እንዲህ ሲል ተናገረ፥ “እኔ በእነርሱ አድራለሁ፤ በመካከላቸውም እኖራለሁ፤ አምላካቸውም እሆናቸዋለሁ፤ እነርሱም ሕዝቤ ይሆኑኛል።”'),
  ('40a83301-aeb2-5a55-a567-62ff387c1bed', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'ed9f0ac4-0510-5a40-ab6e-4a75e3058cf5', 4, 17, 'ስለዚህም “ከመካከላቸው ተለይታችሁ ውጡ፤ ከእነርሱም ተለዩ፤ ወደ ርኩሳንም አትቅረቡ፥ እኔም እቀበላችኋለሁ።'),
  ('4a31eada-8a29-5630-a96a-8f5d45491fd6', 'e403595c-6c9c-5f08-ae31-0dbcbf58a4b9', 'ed9f0ac4-0510-5a40-ab6e-4a75e3058cf5', 5, 18, 'አባት እሆናችኋለሁ፤ እናንተም ወንዶችና ሴቶች ልጆች ትሆኑኛላችሁ አለ ሁሉን የሚገዛ እግዚአብሔር።”'),
  ('afa8eda3-afcb-5df1-a219-3a7479728bb9', '0f81e21f-3a40-5dd4-ad54-c57560b15986', 'a18fc219-3077-5424-a1a1-2a7879407b08', 1, 1, 'ወንድሞቻችን ሆይ፥ እንግዲህ ይህ ተስፋ ያለን ስለሆን ራሳችንን እናንጻ፤ ሥጋችንን አናርክስ፤ ነፍሳችንንም አናሳድፍ፤ እግዚአብሔርንም በመፍራት የምንቀደስበትን እንሥራ።'),
  ('2f39f3c9-02d6-5b23-ad22-21852f8a9cdc', '0f81e21f-3a40-5dd4-ad54-c57560b15986', 'a18fc219-3077-5424-a1a1-2a7879407b08', 2, 2, 'አሁንም ወንድሞቻችን ሆይ፥ ታገሡን፥ የበደልነው የለም፤ የገፋነውም የለም፤ ያጠፋነውም የለም፤ የቀማነውም የለም።'),
  ('f219aef7-0484-5aa0-a492-637025cbaf9f', '0f81e21f-3a40-5dd4-ad54-c57560b15986', 'a18fc219-3077-5424-a1a1-2a7879407b08', 3, 3, 'ይህንም የምለው በእናንተ ለመፍረድ አይደለም፤ ለሞትም፥ ለሕይወትም ቢሆን እናንተ በልባችን እንዳላችሁ ፈጽሜ ተናግሬአለሁና።'),
  ('12451082-7c56-5943-a057-0d66a6ac3957', '0f81e21f-3a40-5dd4-ad54-c57560b15986', 'a18fc219-3077-5424-a1a1-2a7879407b08', 4, 4, 'በእናንተ ዘንድ እንዲሁ ብዙ መወደድ አለኝ፤ ስለ እናንተም የምመካበት ብዙ ነው፤ መጽናናትንም አገኘሁ፤ ከመከራዬም ሁሉ ይልቅ ደስታዬ በዛልኝ።'),
  ('a5547626-b37f-5528-aea5-eb05133d7f99', '0f81e21f-3a40-5dd4-ad54-c57560b15986', 'a18fc219-3077-5424-a1a1-2a7879407b08', 5, 5, 'ወደ መቄዶንያም በደረስን ጊዜ ለሰውነታችን ጥቂት ስንኳን ዕረፍት አላገኘንም፤ በሁሉም መከራ አጸኑብን እንጂ፤ በውጭም መጋደል ነበር፤ በውስጥም ፍርሀት ነበር።'),
  ('8b0d76a6-f118-50aa-a016-630719a47fb3', '0f81e21f-3a40-5dd4-ad54-c57560b15986', 'a18fc219-3077-5424-a1a1-2a7879407b08', 6, 6, 'ነገር ግን ያዘኑትን የሚያጽናና እርሱ እግዚአብሔር በቲቶ መምጣት አጽናናን።'),
  ('13485efe-8699-5999-a12d-0d9b20854b2a', '0f81e21f-3a40-5dd4-ad54-c57560b15986', 'a18fc219-3077-5424-a1a1-2a7879407b08', 7, 7, 'በመምጣቱ ብቻ አይደለም፤ በአጽናናችሁት ማጽናናትም ነው እንጂ፤ ለእኛ እንደምታስቡና እንደምትቀኑ ፍቅራችሁን ነግሮናል፤ ይህንም ሰምቼ ደስታዬ በእናንተ በዛ።'),
  ('ba7dbf6b-5b97-5b42-a2f8-29192dee349c', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 1, 8, 'መጀመሪያ በጻፍሁት መልእክት ባሳዝናችሁም እንኳ አያጸጽተኝም፤ ብጸጸትም፥ እነሆ ያች መልእክት ለጥቂት ጊዜ ብቻ እንዳሳዘነቻችሁ አያለሁ።'),
  ('3d3acf52-a8cc-5189-a6f0-3c106892f34a', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 2, 9, 'አሁን ግን እኔ ስለ እርሷ በብዙ ደስ ይለኛል፤ ደስታዬም ስለ አዘናችሁ አይደለም፤ ንስሓ ልትገቡ ስለ አዘናችሁ እንጂ፤ ከእናንተ አንዱ ስንኳ እንዳይጠፋ፥ ስለ እግዚአብሔር ብላችሁ አዝናችኋልና።'),
  ('d1443f3c-bc5e-53cd-add4-a10f72710c85', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 3, 10, 'ስለ እግዚአብሔር ተብሎ የሚደረግ ኀዘን የዘለዓለም ሕይወትን የሚያሰጥ ንስሓ ነው። ስለ ዓለም የሚደረግ ኀዘን ግን ሞትን ያመጣል።'),
  ('885551c2-3318-5a20-a64f-b07ea5ac5d57', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 4, 11, 'እነሆ፥ ያ ስለ እግዚአብሔር ብላችሁ ያደረጋችሁት ኀዘን ምንም የማታውቁ እስከ መሆን ደርሳችሁ፥ ራሳችሁን በበጎ ሥራና በንጽሕና እስክታጸኑ ድረስ፥ ትጋትንና ክርክርን፥ ቍጣንና ፍርሀትን፥ ናፍቆትንና ቅንዐትን፥ በቀልንም አደረገላችሁ፤'),
  ('0a744292-d860-5709-a827-b8bfb628ebc0', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 5, 12, 'ይህን የጻፍሁላችሁ በእግዚአብሔር ፊት ስለ እኛ እንደ ተጋችሁ ይታወቅ ዘንድ ነው እንጂ ስለ በደለና ስለ ተበደለ ሰው አይደለም።'),
  ('8b303d9e-1598-55ad-a3e8-2d04c194aa49', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 6, 13, 'ስለዚህም ተጽናንተናል፤ በመጽናናታችንም ስለ ቲቶ ደስታ አብልጦ ደስ አለን፤ በሁላችሁ ዘንድ ሰውነቱን አሳርፋችኋታልና።'),
  ('965f2290-6d6b-57c6-ab7a-2fe52a60c685', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 7, 14, 'ስለ እናንተ ለእርሱ በተመካሁበት ሁሉ አላሳፈራችሁኝምና፤ ነገር ግን ሁሉን ለእናንተ በእውነት እንደ ተናገርን፥ እንደዚሁ ደግሞ በቲቶ ፊት ትምክህታችን እውነት ሆነ።'),
  ('41ea5b37-3731-559a-affe-9e6cb2d31c5c', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 8, 15, 'ስለዚህም እጅግ ያመሰግናችኋል፤ እንደ ታዘዛችሁለት፥ በመፍራትና በመደንገጥም እንደ ተቀበላችሁት ያስባችኋል።'),
  ('ac6f311d-d3ef-5c2d-ae09-1eb2f91f35a5', '0f81e21f-3a40-5dd4-ad54-c57560b15986', '2295663b-8fc1-5604-a9ec-b7ee32dc30e2', 9, 16, 'እኔም በሁሉ ነገር እተማመናችኋለሁና ደስ ይለኛል።'),
  ('f3b484e8-e0e8-5d98-a106-357dad76623c', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 1, 1, 'ወንድሞች ሆይ፥ ለመቄዶንያ አብያተ ክርስቲያናት የተሰጠውን የእግዚአብሔርን ጸጋ እነግራችኋለሁ።'),
  ('971cc7ae-62e1-5e60-a1a7-e6ce2775fd01', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 2, 2, 'በብዙ መከራ ከመፈተናቸው የተነሣ ደስታቸው በዝቶአልና፤ በድህነታቸው ጥልቅነትም የለጋስነታቸው ባለጠግነት በዝታለችና።'),
  ('b6f26169-9bfb-5395-acf1-15f521e61b98', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 3, 3, 'እነርሱ ሲቻላቸው፥ ሳይቻላቸውም እንስጥ በማለት ቈራጦች ለመሆናቸው ምስክራቸው እኔ ነኝና።'),
  ('da6aab62-0cc5-55bb-a976-b125e9899bb4', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 4, 4, 'ለቅዱሳን ስለሚሆነው አገልግሎት እንዲተባበሩ ይህን ቸርነት መላልሰው ማለዱን።'),
  ('27057187-1916-5eb7-a3a4-79c43dc36504', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 5, 5, 'እነርሱ አስቀድመው በፈቃዳቸው፥ እንደ እግዚአብሔር ፈቃድ ሰውነታቸውን ለእግዚአብሔርም፥ ለእኛም አሳልፈው ሰጥተዋልና እኛ እንደ አሰብነው አይደለም፤'),
  ('1d6f4caf-a89d-58a0-a718-fc256b34c374', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 6, 6, 'ይህንም የቸርነት ሥራ እንደ ጀመረ ይፈጽምላችሁ ዘንድ ቲቶን ማለድነው።'),
  ('88f76f72-e142-50e0-a3f2-3fb06af5d242', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 7, 7, 'በሁሉ ነገር በእምነትና በቃል፥ በዕውቀትም፥ በትጋትም በእናንተ ዘንድ በሆነው ሁሉ እኛን በመውደዳችሁ ፍጹማን እንደ ሆናችሁ፥ እንዲሁም ደግሞ ይህቺን ስጦታ አብዙ።'),
  ('c01bf614-8937-52a8-a0fc-55c9adf45d36', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 8, 8, 'በግድ የምላችሁ አይደለም፤ ነገር ግን ከእናንተ ለዚህ ሥራ የሚተጉለት አሉና የፍቅራችሁን እውነተኛነት አሁን መርምሬ ተረዳሁ።'),
  ('091f9d26-5ddb-5ab3-a407-36f7f6e48be6', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 9, 9, 'የጌታችን የኢየሱስ ክርስቶስን ቸርነቱን ታውቃላችሁ፤ በእርሱ ድህነት እናንተ ባለጸጎች ትሆኑ ዘንድ እርሱ ባለጸጋ ሲሆን፥ ስለ እናንተ ራሱን ድሃ አደረገ።'),
  ('a08521fb-1c1a-5686-af74-010b546f5ffd', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 10, 10, 'በዚህም የሚጠቅማችሁን እመክራችኋለሁ፤ ይህን ከማድረጋችሁ በፊት ፈቅዳችኋልና፤ ከአምና ጀምሮም ይህን ጀምራችኋል።'),
  ('f670f7b1-e95a-5290-a29a-e4fcd9596c3f', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 11, 11, 'አሁንም አድርጉ፤ ፈጽሙም፤ መፍቀድ ከመሻት ነውና፤ ማድረግም ከማግኘት ነውና።'),
  ('3cd7ede6-3351-5db2-ab65-5e43c28a1c4f', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 12, 12, 'ፈቃድ ካለም፥ ሰው በሚቻለው መጠን ቢሰጥ ይመሰገናል፤ በማይቻለውም መጠን አይደለም።'),
  ('dc71434e-0449-5a43-a9f8-8cc2e26ef1ca', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 13, 13, 'በዚህ ወራት ተካክላችሁ እንድትኖሩ ነው እንጂ ሌላው እንዲያርፍ እናንተን የምናስጨንቅ አይደለም።'),
  ('39753cf8-b14a-5a4d-a56b-8843f7ad2324', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 14, 14, 'ኑሮአችሁ በሁሉ የተካከለ ይሆን ዘንድ፥ የእናንተ ትርፍ የእነርሱን ጕድለት ይመላልና፥ የእነርሱም ትርፍ የእናንተን ጕድለት ይመላልና።'),
  ('f860cfd7-17f4-5455-a1ae-27cdefcda57d', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'dc9b117b-3560-56b7-a7e7-19ec5765bd1c', 15, 15, 'መጽሐፍ እንዳለ፥ “ብዙ ያለው አላተረፈም፤ ጥቂት ያለውም አላጐደለም።”'),
  ('f39047b5-3583-5b8c-a494-4a628d8992aa', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 1, 16, 'በቲቶ ልብ ስለ እናንተ ያን መትጋት የሰጠ እግዚአብሔር የተመሰገነ ነው።'),
  ('6a4e5d22-4df4-5af2-a86b-863cc0aa54de', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 2, 17, 'ልመናችንንም ተቀብሎ፥ ጨክኖ ወደ እናንተ ይመጣ ዘንድ ቸኵሏል።'),
  ('015730c2-b3a6-5e6a-af7b-2e6b20df3618', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 3, 18, 'ስለ ወንጌል ትምህርት አብያተ ክርስቲያናት ሁሉ ያመሰገኑትን ወንድማችንንም ከእርሱ ጋር ልከናል።'),
  ('8a2c97ed-0586-5ec3-a0d6-380b9a8b01ae', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 4, 19, 'ይህም ብቻ አይደለም፤ ነገር ግን የእግዚአብሔርን ክብርና የእኛን በጎ ፈቃድ ለማሳየት በምናገለግልባት በዚች ጸጋ ከእኛ ጋር አንድ ይሆን ዘንድ በአብያተ ክርስቲያናት ተሾመ።'),
  ('13d63ef4-149d-55ae-a9bc-1e9d78750e0a', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 5, 20, 'ስለምናገለግለው ስለዚህ ለጋስ ስጦታ ማንም እንዳይነቅፈን እንጠነቀቃለን።'),
  ('907c6572-4599-536c-af8c-cdbc3a89157c', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 6, 21, 'በእግዚአብሔር ፊት ብቻ ያይደለ፥ ነገር ግን በሰው ፊትም መልካሙን ነገር እናስባለንና።'),
  ('f7e5b291-2018-5428-a041-2e4bd74e097d', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 7, 22, 'በብዙ የፈተንነውንና በሁሉም ነገር ትጉህ ሆኖ ያገኘነውን አሁንም በእናንተ እጅግ ስለሚታመን ከፊት ይልቅ እጅግ ትጉ የሚሆነውን ወንድማችንን ከእነርሱ ጋር እንልካለን።'),
  ('6531eb4e-1d01-5ab0-adf9-525725610f69', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 8, 23, 'ቲቶም ቢሆን፥ ስለ እናንተ አብሮኝ የሚሠራ ጓደኛዬ ነው፥ ወንድሞቻችንም ቢሆኑ፥ ለእግዚአብሔር ክብር የአብያተ ክርስቲያናት ሐዋርያት ናቸው።'),
  ('b6771c33-3a20-5397-a7e0-72453e00f46f', 'e55383c5-87c5-58a2-a20c-22bc181a3913', 'b7246e87-fedf-5313-ab94-55d6b516beff', 9, 24, 'አሁንም መዋደዳችሁንና እኛም በእናንተ የምንመካበትን ሥራ በአብያተ ክርስቲያናት ፊት በግልጥ አሳዩአቸው።'),
  ('6cbc6281-451a-5e17-a7c1-da095fb5b2f2', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 1, 1, 'ለቅዱሳን ስለሚደረገው አገልግሎት የምጽፍላችሁ ብዙ አለኝ'),
  ('9e14fa3a-2c0b-524e-aabc-a5d367df4b54', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 2, 2, 'እናንተ እንደምትተጉ አውቃለሁና፤ ስለዚህም “የአካይያ ሰዎች እኮ ከአምና ጀምሮ አዘጋጅተዋል” ብዬ በመቄዶንያ ሰዎች ዘንድ አመሰገንኋችሁ፤ እነሆም የእናንተ መፎካከር ብዙዎችን ሰዎች አትግቶአቸዋል።'),
  ('8680dc29-54ba-57cd-af0e-51f8c0b4f9d2', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 3, 3, 'በዚህም ያመሰገንናችሁ ምስጋና በእነርሱ ዘንድ ሐሰት እንዳይሆንብን፥ እንደ ነገርናቸውም ተዘጋጅታችሁ እንዲያገኙአችሁ ወንድሞችን ወደ እናንተ ላክናቸው።'),
  ('caa05291-0201-5991-a172-078ac50179b3', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 4, 4, 'ምናልባት የመቄዶንያ ሰዎች ከእኔ ጋር ቢመጡና ሳታዘጋጁ ቢያገኙአችሁ እናንተ ታፍራላችሁ ባልልም እኛ ስለ እናንተ ከነገርናቸው የተነሣ እናፍራለን።'),
  ('f01cadfa-ffb9-524e-aad5-d846d5624c85', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 5, 5, 'ስለዚህም አስቀድመው ወደ እናንተ መጥተው በቅድሚያ የተናገራችኋትን በረከታችሁን እንዲያዘጋጁ ወንድሞችን ማለድሁ፤ እንደዚህም የተዘጋጀ ይሁን፤ በረከትን እንደምታገኙበት እንጂ በንጥቂያ እንደ ተወሰደባችሁ አይሁን።'),
  ('670264a0-4d75-5f1a-ad1f-134fc3520d6d', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 6, 6, 'አሳንሶ የሚዘራ ለእርሱ እንዲሁ መከሩ ያንስበታል፤ በብዙ የሚዘራ ግን በብዙ ያመርታል።'),
  ('7bae1eab-7de0-57c9-a2c7-03c4eb3cc73b', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 7, 7, 'ሁሉ ልቡ እንደ ወደደ ያድርግ፤ በደስታ ይስጡ እንጂ በግድ አይሆንም፤ እግዚአብሔር በደስታ የሚሰጠውን ይወዳልና።'),
  ('8f313853-2307-5019-a30c-04bf51f73d0c', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 8, 8, 'እግዚአብሔር መልካሙን ነገር ሁሉ ሊያበዛላችሁ ይችላል፤ ፍጹም በረከቱንም ለዘወትር ያበዛላችሁ ዘንድ፥ ለሁሉም ታተርፉታላችሁ፤ በጎ ሥራ መሥራትንም ታበዛላችሁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2e6cab2d-4813-5c40-a13a-59c5c6635dce', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 9, 9, '“በተነ፤ ለድሃም ሰጠ፤ ጽድቁም ለዘለዓለም ይኖራል” ብሎ መጽሐፍ እንደ ተናገረ።'),
  ('8c5ed858-f26b-50e1-a1e9-415d2b8980aa', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 10, 10, 'እርሱ ዘርን ለዘሪ ይሰጣል፤ እህልንም ለምግብ ይሰጣችኋል፤ ዘራችሁንም ያበዛላችኋል፤ የጽድቃችሁንም መከር ያበጃል።'),
  ('3cd1765c-7ea4-5d3e-a856-0ed5c3665259', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 11, 11, 'ለብዙ ሰዎች ስለ ሰጣችሁም የእግዚአብሔርን ምስጋና በምታደርግላችሁ ልግስና ሁሉ ባለጸጎች ትሆናላችሁ።'),
  ('900af0d7-5476-5953-a049-1fecc43467e5', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 12, 12, 'ይህቺ የዚህ ሥራ አገልግሎት ግዳጅ የምትፈጽመው ለዚህ ለቅዱሳን ችግር መሟላት ብቻ አይደለም፤ በቅዱሳን ዘንድም ደግሞ የእግዚአብሔርን ምስጋና ታበዛለች።'),
  ('ae9b2e84-670e-58d6-a0b3-5c9552da2f80', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 13, 13, 'ክርስቶስ ላስተማራት ትምህርት ታዝዛችኋልና፥ ሁላችሁም ደስ ብሎአችሁና ተባብራችሁ አወጣጥታችኋልና በዚች በሃይማኖታችሁ ፈተና ምክንያት እግዚአብሔርን ያመሰግኑታል፤'),
  ('129a20bd-d091-5eef-a8c1-873f62387b1c', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 14, 14, 'እነርሱም ስለ እናንተ ይጸልያሉ፤ ስለ አደረባችሁ ታላቅ የእግዚአብሔር ጸጋም ሊያዩአችሁ ይመኛሉ።'),
  ('c478e65e-988d-5d98-abc2-e605ecbf9d2d', 'b0a90b6f-660f-5a0c-a33e-a93e14e05656', '3f9a7d99-ae52-50d7-a137-5766f9100c4c', 15, 15, 'ስለማትመረመርና ባላሰቡአት ጊዜ ስለምትመጣው ጸጋው እግዚአብሔር ይመስገን።'),
  ('e6603707-f1af-57d4-a981-ec294ad4c92c', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 1, 1, 'ወንድሞቻችን ሆይ፥ እኔ ጳውሎስ በእናንተ ዘንድ ፊት ለፊት ሳለሁ ትሑት የሆንሁ፥ ከእናንተ ብርቅ ግን የምደፍራችሁ በክርስቶስ የዋህነትና ቸርነት እማልዳችኋለሁ፥ በፍቅራችሁ እታመናለሁና።'),
  ('ca70c863-4858-56c6-a91c-ec2deaeed6e4', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 2, 2, 'ወደ እናንተ በመጣሁ ጊዜ እሠራለሁ፤ በሥጋዊ ሥርዐትም እንደምንኖር አድርገው በሚጠረጥሩን ሰዎች ላይ በድፍረት ለመናገር አስባለሁ፤ እናንተ ግን በዚህ ዓይነት ድፍረት እንድናገር እንዳታደርጉኝ እለምናችኋለሁ።'),
  ('5b8cb752-8590-5c1f-a198-7d7cc44b9f93', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 3, 3, 'በሥጋችንስ እንሄዳለን፤ ነገር ግን በእርሱው ሥርዐት የምንሄድና የምንዋጋ አይደለም።'),
  ('ce814a56-6d6a-50ba-a968-124d21a877dd', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 4, 4, 'የጦር ዕቃችን ሥጋዊ አይደለምና፥ ጽኑ ምሽግን በሚያፈርስ በእግዚአብሔር ኀይል ነው እንጂ።'),
  ('71aa8e61-5ac8-508c-a367-39a087173541', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 5, 5, 'ልብ ሁሉ ይማረክ ዘንድ ኅሊናም ለክርስቶስ ይገዛ ዘንድ በእግዚአብሔር ላይ የሚታበየውንና ከፍ ከፍ የሚለውን እናፈርሳለን።'),
  ('0af40f9d-c3b2-5006-a38f-37c6ee5fa2ca', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 6, 6, 'እናንተ ትእዛዝን በፈጸማችሁ ጊዜ የማይገዛውን ሁሉ እኛ ልንበቀለው ዝግጁዎች ነን።'),
  ('ec690846-fa54-55a4-ac90-81491d65adf1', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 7, 7, 'በፊታችሁ ያለውን ተመልከቱ፤ ማንም በክርስቶስ ያመነ ቢሆን፥ ይህን እንደ ገና በራሱ ይቍጠረው፤ እርሱ የክርስቶስ እንደ ሆነ እኛም እንዲሁ ነንና።'),
  ('a1bf0ee1-6a9f-57e6-a128-b87279f6e99a', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 8, 8, 'እናንተን ለማነጽ እንጂ፥ እናንተን ለማፍረስ ያይደለ፥ እግዚአብሔር በእናንተ ላይ በሰጠን ሥልጣን እጅግ የተመካሁት መመካት ቢኖር አላፍርም።'),
  ('029095d6-1504-508f-a9a1-01c2795ccca0', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 9, 9, 'ነገር ግን በመልእክቶች የማስፈራራችሁ እንዳይመስላችሁ፥ ይህን ትምክሕቴን እተወዋለሁ።'),
  ('595bef14-270b-57ab-ac83-e014e4ee9d98', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 10, 10, 'ከሰዎች መካከል “መልእክቶቹ ከባዶችና አስጨናቂዎች ናቸው፤ ሰውነቱ ግን ደካማ ነው፤ ነገሩም ተርታ ነው” የሚሉ አሉና።'),
  ('67cb419f-eb51-5a84-a483-62628993afb5', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 11, 11, 'ነገር ግን ይህን ነገር የሚናገር ይህን ይወቅ፤ በሌለንበት ጊዜ በመልእክታችን እንደ ተገለጠው እንደ ቃላችን፥ ባለንበትም ጊዜ በሥራችን እንዲሁ ነን።'),
  ('92994017-5aa8-5032-a020-11b5b821226d', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 12, 12, 'እነርሱ ራሳቸውን በአሰቡትና በገመገሙት መጠን ራሳቸውን ከሚያመሰግኑት ሰዎች ጋር ራሳችንን ልንቈጥር፥ ወይም ራሳችንን ልናስተያይ አንደፍርም፤ እነርሱ ራሳቸውም የሚናገሩትን ትርጕሙን አያውቁትም።'),
  ('62c384e9-27f1-5ed4-a73e-47a6bf56db6b', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 13, 13, 'እኛስ ወደ እናንተ እስክንደርስ ድረስ እግዚአብሔር በወሰነልን ሕግና ሥርዐት እንጂ፥ ከዐቅማችን አልፈን እጅግ አንመካም።'),
  ('7840a1a0-c4d5-5d80-a995-04db4fd41a22', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 14, 14, 'ወደ እናንተ እንደማንደርስ አድርገን፥ ራሳችንን የምናመሰግን አይደለምና፤ ነገር ግን የክርስቶስን ሕግ በማስተማር ወደ እናንተ ደርሰናል።'),
  ('9b07b8a1-f67d-5095-a70b-1d7c1c435658', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 15, 15, 'እኛስ በማይገባ ሌላ በደከመበት አንመካም፤ ነገር ግን ሃይማኖታችሁ እንድትሰፋ፥ የተሠራችላችሁ ሕግም በእናንተ እንድትጸና ተስፋ እናደርጋለን።'),
  ('1e353982-e8a6-5c9c-a42f-ebe294127604', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 16, 16, 'አብዝተንም እናስተምራችኋለን፤ ያንጊዜም መጠናችን ከሥራችን ጋር ከፍ ከፍ ይላል፤ እኛስ ቀና ባልሆነውና በማይገባው አንመካም።'),
  ('0e09d61c-bbed-5f1c-a6cc-3cebd5dd53e2', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 17, 17, '“የሚመካ ግን በእግዚአብሔር ይመካ።”'),
  ('cc8c8880-3c30-5da3-ad9f-6f42a8c3725c', 'a7d42e50-3633-5c84-ae43-bbeddd0617c6', '7fade1e0-8117-5ffc-ac1f-f93e6b4c9f2a', 18, 18, 'እግዚአብሔር ያከበረው ብቻ ይከብራል እንጂ ራሱን የሚያከብር የተመረጠ አይደለም።'),
  ('087a0bc9-3902-5f28-ad5c-994cbcde405c', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', 'd6aa5920-702c-5a26-aefd-50f8f48d96e4', 1, 1, 'በስንፍናዬ እናገር ዘንድ ጥቂት ልትታገሡኝ ይገባ ነበር፤ ቢሆንም በርግጥ ታገሡኝ፤'),
  ('ded222e2-fdba-5b3d-a196-22f8b44512ee', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', 'd6aa5920-702c-5a26-aefd-50f8f48d96e4', 2, 2, 'ለእግዚአብሔር የሚገባ ቅንዐት እቀናላችኋለሁና፤ ወደ እርሱ አቀርባችሁ ዘንድ ለአንዱ ንጹሕ ድንግል ሙሽራ ለክርስቶስ አጭቻችኋለሁና።'),
  ('c4b3886e-b47f-5934-aad9-8676d7e7ac4f', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', 'd6aa5920-702c-5a26-aefd-50f8f48d96e4', 3, 3, 'ነገር ግን እባብ ሔዋንን በተንኰሉ እንዳሳታት፥ አሳባችሁ ከክርስቶስ የዋህነትና ንጽሕና ምናልባት እንዳይለወጥ ብዬ እፈራለሁ።'),
  ('e99fd74e-5057-55f6-a1e2-d70a2f94a827', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', 'd6aa5920-702c-5a26-aefd-50f8f48d96e4', 4, 4, 'ወደ እናንተ የመጣና እኛ ወደ አላስተማርናችሁ ወደ ሌላ ኢየሱስ የጠራችሁ ቢኖር፥ ወይም ያልተቀበላችሁት ሌላ መንፈስ ቢኖር፥ ወይም ያልተማራችሁት ሌላ ወንጌል ቢኖር ልትጠብቁን ይገባል።'),
  ('d62780e9-1fd2-5b09-aa48-0ce3a9dd83be', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', 'd6aa5920-702c-5a26-aefd-50f8f48d96e4', 5, 5, 'እኔ ግን ሌሎች ሐዋርያት ከአስተማሩት ያጐደልሁባችሁ የለም ይመስለኛል።'),
  ('fc987f3d-4986-5dda-ad10-97c8f12b4253', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 1, 6, 'እኔ በአነጋገሬ አላዋቂ ብሆንም በዕውቀት ግን እንዲሁ አይደለሁም፤ ነገር ግን ሁሉን በሁሉ እገልጥላችኋለሁ።'),
  ('8c82ef46-6102-52bd-a701-ed5fa2ee29bf', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 2, 7, 'ወይስ ራሴን በሁሉ ያዋረድሁ በደልሁ ይሆን? እናንተ ከፍ ከፍ ትሉ ዘንድ፥ የእግዚአብሔርን ወንጌል ያለ ዋጋ አስተምሬአችኋለሁና።'),
  ('cebf5cc3-5f1e-5070-a243-d6595ddf9ee6', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 3, 8, 'እናንተን አገለግል ዘንድ፥ ከሌሎች አብያተ ክርስቲያናት ተቀብዬ፥ ለምግቤ ያህል ወሰድሁ፤'),
  ('98ff7f5b-0295-57ef-ac7c-69c3203e3267', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 4, 9, 'ከእናንተ ዘንድ በነበርሁበት ጊዜም፥ ስቸገር ገንዘባችሁን አልተመኘሁም። ባልበቃኝም ጊዜ ወንድሞቻችን ከመቄዶንያ መጥተው አሙአሉልኝ፤ በእናንተም ላይ እንዳልከብድባችሁ በሁሉ ተጠነቀቅሁ፤ ወደ ፊትም እጠነቀቃለሁ።'),
  ('7fda3ef9-2e29-5726-a6a7-71c5307cd7f2', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 5, 10, 'የክርስቶስ ዕውነት አብሮኝ ይኖራልና፥ ይህቺ ደስታዬ በአካይያ አውራጃ አልተከለከለችብኝም።'),
  ('02cb7000-bf4a-5c19-a88e-eea187484b68', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 6, 11, 'ስለምን ነው? አልወዳችሁምና ነውን? እንደምወድዳችሁስ እግዚአብሔር ያውቃል።'),
  ('c92044a9-b8cd-563c-ad0f-386cc129bafa', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 7, 12, 'ነገር ግን ያደረግሁትም ቢሆን፥ የማደርገውም ቢሆን፥ እነርሱ እንደ እኛ የሚመኩበትን ያገኙ ዘንድ፥ ምክንያት የሚሹትን ምክንያት አሳጣቸው ዘንድ ነው።'),
  ('01e21c76-055b-5dd7-a3b4-1a91d0c91716', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 8, 13, 'የሚተነኰሉ፥ ራሳቸውን የክርስቶስን ሐዋርያት የሚያስመስሉ፥ ዐመፅንም የሚያደርጉ ሐሰተኞች ሐዋርያት አሉና።'),
  ('d3667819-768f-5b8d-a0b8-327af2be6962', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 9, 14, 'ይህም አያስደንቅም፤ ሰይጣን ራሱ ተለውጦ እንደ ብርሃን መልአክ ይመስላልና።'),
  ('5f0f1be0-299e-5c63-adf0-32169a1183a2', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '8d256e78-b549-52c8-a6e9-4366a3794a24', 10, 15, 'መልእክተኞቹም የጽድቅ መላእክትን ቢመስሉ፥ ይህ ታላቅ ነገር አይደለም፤ ፍጻሜያቸው ግን እንደ ሥራቸው ነው።'),
  ('2e604db7-bb0e-5970-a242-7a317cc930a3', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 1, 16, 'ደግሞም እንዲህ እላለሁ፦ ሰነፍ የሚያደርገኝ አይኑር፤ ያውም ብሆን እኔ ጥቂት እመካ ዘንድ እንደ ሰነፍ እንኳ ብሆን ተቀበሉኝ።'),
  ('324f9500-94db-5930-a70d-224d56222c68', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 2, 17, 'ይህም ቢሆን የምናገረው ለእግዚአብሔር የሚገባ አይደለም፤ ነገር ግን ስለዚህች ትምክሕቴ እንደ ሰነፍ እናገራለሁ።'),
  ('b502224c-66f8-5560-acd0-786847ca78d1', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 3, 18, 'በሥጋዊ ሥርዐት የሚመኩ ብዙዎች ናቸውና እኔ ደግሞ እመካለሁ።'),
  ('1caa2036-1b7a-5264-a968-81d18186c96e', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 4, 19, 'እናንተ ልባሞች ስትሆኑ ሰነፎችን መስማት ደስ ያሰኛችኋልና።'),
  ('7c85879a-5ec6-56d3-a0a4-de5c1b1397ad', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 5, 20, 'የሚገዙአችሁንና የሚቀሙአችሁን፥ መባያ የሚያደርጓችሁንና የሚታበዩባችሁን፥ ፊታችሁንም በጥፊ የሚመትዋችሁን ትታገሡአቸዋላችሁና።'),
  ('3147ada6-94be-506c-a7d3-7ea2f7db6c6c', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 6, 21, 'እኛ እንደ ደካሞች መስለን እንደ ነበርን፥ ይህን በውርደት እናገራለሁ፤ ነገር ግን ማንም በሚደፍርበት እኔ ደግሞ እደፍራለሁ።'),
  ('483b6e6c-d481-5d2a-acfd-29de3d2c26b5', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 7, 22, 'እነርሱ ዕብራውያን ቢሆኑ እኔም እንደ እነርሱ ነኝ፤ እነርሱ እስራኤላውያን ቢሆኑ እኔም እንደ እነርሱ ነኝ፤ እነርሱ የአብርሃም ልጆች ቢሆኑ እኔም እንደ እነርሱ ነኝ።'),
  ('98d4d568-2428-5f7c-a7d3-21fbf0c8f0bc', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 8, 23, 'እነርሱ የክርስቶስ አገልጋዮች ቢሆኑም እኔም እንደ ሰነፍ ለራሴ እናገራለሁ፤ እኔ እበልጣለሁ፤ እጅግም ደከምሁ፤ ብዙ ጊዜ ተገረፍሁ፤ ብዙ ጊዜም ታሰርሁ፤ ብዙ ጊዜም ለሞት ተዘጋጀሁ።'),
  ('84844369-9fd7-5d63-a398-831906b7f0c2', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 9, 24, 'አይሁድ አንዲት ስትቀር አምስት ጊዜ አርባ አርባ ገረፉኝ።'),
  ('224bac6b-8a42-5cbc-a15e-8090d5d68805', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 10, 25, 'ሦስት ጊዜ በበትር ደበደቡኝ፤ አንድ ጊዜ በድንጋይ መቱኝ፤ መርከቤ ሦስት ጊዜ ተሰበረች፤ በጥልቁ ባሕር ውስጥ ስዋኝ አድሬ፥ ስዋኝ ዋልሁ።'),
  ('8b2726a0-999b-5322-a609-1497676f98c9', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 11, 26, 'በመንገድ ዘወትር መከራ እቀበል ነበር፤ በወንዝም መከራ ተቀበልሁ፤ ወንበዴዎችም አሠቃዩኝ፤ ዘመዶችም አስጨነቁኝ፤ አሕዛብ መከራ አጸኑብኝ፤ በከተማ መከራ ተቀበልሁ፤ በበረሃም መከራ ተቀበልሁ፤ በባሕርም መከራ ተቀበልሁ፤ ሐሰተኞች መምህራን መከራ አጸኑብኝ።'),
  ('b615e73f-fd66-5f60-a8dd-6a76e76ab8b3', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 12, 27, 'በድካምና በጥረት፥ ብዙ ጊዜም ዕንቅልፍ በማጣት፥ በመራብና በመጠማት፥ አብዝቶም በመጾም፥ በብርድና በመራቆት ተቸገርሁ።'),
  ('8e4e8f0b-b85b-5556-a8e5-06f0a4908525', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 13, 28, 'የቀረውንም ነገር ሳልቈጥር ዕለት ዕለት የሚከብድብኝ የአብያተ ክርስቲያናት ሁሉ አሳብ ነው።'),
  ('aaa38ecb-8f60-5d2e-abfd-c7e8952abe6d', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 14, 29, 'ታሞ እኔ የማላዝንለት ማን ነው? በድሎስ እኔ የማልደነግጥለት ማን ነው?'),
  ('c1a71457-f9e6-5869-aaa2-05360abbcf9b', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 15, 30, 'መመካት የሚገባ ከሆነስ እኔም በመከራዬ እመካለሁ።'),
  ('a8b23f28-f426-5da2-af95-02fdc3bf9e8c', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 16, 31, 'ለዘለዓለም ቡሩክ አምላክ የሆነ የጌታችን የኢየሱስ ክርስቶስ አባት እግዚአብሔር ሐሰት እንደማልናገር ያውቃል።'),
  ('8aa01488-b29c-5844-a450-c57d9a0c67dd', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 17, 32, 'በደማስቆ ከተማ ከንጉሥ አርስጣስዮስ በታች የሆነ የአሕዛብ አለቃ ሊይዘኝ ወድዶ የደማስቆን ከተማ ያስጠብቅ ነበር።'),
  ('1b1505bd-dcbd-5668-a722-f9c66bbe2ffb', '2aa22663-4307-5f52-ae76-a4f1c602f3e3', '4e35b2c1-ab85-5900-aa54-9fe2bf062cf8', 18, 33, 'በቅርጫትም አድርገው በመስኮቱ በኩል በአጥሩ ላይ አወረዱኝ፤ ከእጁም አመለጥሁ።'),
  ('fa7a12a0-5d04-5352-ac7f-afd3b37c421a', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 1, 1, 'እነሆ መመካት ይቻለኛል፤ ነገር ግን አይጠቅምም፤ ደግሞም ወደ ጌታ ራእይና መገለጥ እሄዳለሁ።'),
  ('5bc7d0f8-8ee2-5330-a3f2-a6e19ad2f04a', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 2, 2, 'በክርስቶስ ያመነ አንድ ሰው አውቃለሁ፤ ዘመኑ ከዐሥራ አራት ዓመት በፊት ነው፤ ነገር ግን በሥጋው ይሁን በነፍሱ እንጃ፥ እግዚአብሔር ያውቃል፤ ያን ሰው እስከ ሦስተኛው ሰማይ ድረስ ነጥቀው ወሰዱት።'),
  ('1e8b2582-c5dc-5926-ae4e-55cc08bd9dd1', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 3, 3, 'ያን ሰው አውቀዋለሁ፤ በሥጋው ይሁን በነፍሱ እንጃ እግዚአብሔር ያውቃል።'),
  ('32b3396c-726c-5d78-aefd-84b7b652c618', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 4, 4, 'ወደ ገነትም ነጥቀው ወሰዱት፤ በዚያም ሰው ሊናገረው የማይችለውን የማይተረጐም ነገር ሰማ።'),
  ('21817e2e-898f-5473-a63c-2432ce0d581a', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 5, 5, 'ስለዚህም እንደዚህ ባለው እመካለሁ፤ በመከራዬ እንጂ በራሴስ አልመካም።'),
  ('9ce08010-f06e-5a64-ad6a-7f72df6726ed', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 6, 6, 'ልመካ ብሻም አላዋቂ አይደለሁም፤ እውነቱን እናገራለሁና፤ ነገር ግን ስላዩኝና ስለ ሰሙኝ እንደምበልጥ አድርገው እንዳይጠራጠሩኝ ትቸዋለሁ።'),
  ('a36b0bd2-1690-54d6-aac5-f643b556c418', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 7, 7, 'ስለዚህም ቢሆን በብዙ ራእይ እንዳልታበይ ሰውነቴን የሚወጋ እርሱም የሚጐስመኝ የሰይጣን መልእክተኛ ተሰጠኝ።'),
  ('e9eb868d-6a93-5867-a372-1679a9b28e86', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 8, 8, 'ስለዚህም ከእኔ ያርቀው ዘንድ ጌታዬን ሦስት ጊዜ ማለድሁት።'),
  ('c96102f0-6bfd-5d8a-a44f-e6dbaf18c86e', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 9, 9, 'እርሱም፥ “ጸጋዬ ይበቃሀል፤ ኀይልስ በደዌ ያልቃል” አለኝ፤ የክርስቶስም ኀይል በእኔ ላይ ያድር ዘንድ በመከራዬ ልመካ ወደድሁ።'),
  ('104ccb6e-e51e-5e03-a559-f2432eff6e5f', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '01682342-b4cd-5d43-a799-85fd52a9ce6a', 10, 10, 'ስለዚህም ስለ ክርስቶስ መከራ መቀበልን፥ መሰደብን፥ መጨነቅን፥ መሰደድን፥ መቸገርንም ወደድሁ፤ መከራ በተቀበልሁ ጊዜ ወዲያውኑ እበረታለሁና።'),
  ('8d3b7ab4-dc8c-5d9b-a6fa-e5c2aaca99ff', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 1, 11, 'እነሆ እናንተ ስላገበራችሁኝ በመመካቴ ሰነፍ ሆንሁ፤ ለእኔማ በእናንተ ዘንድ ልከብርና እናንተም ምስክሮች ልትሆኑኝ ይገባኝ ነበር፤ እኔ እንደ ኢምንት ብሆንም ዋናዎቹ ሐዋርያት ሁሉ ከሠሩት ሥራ ያጐደልሁባችሁ የለምና።'),
  ('dfd18a89-e138-5cf3-a78c-5b1f2a0242fc', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 2, 12, 'የሐዋርያት ምልክትስ በፍጹም ትዕግሥትና በተአምራት፥ ድንቅ ሥራ በመሥራትና በኀይላት ተደርጎላችኋል።'),
  ('ff907dda-4008-509f-a9e9-0e378f7ec18a', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 3, 13, 'እከብድባችሁ ዘንድ ወደ እናንተ ካለመምጣቴ በቀር፥ ከአብያተ ክርስቲያናት ሁሉ ያሳነስኋችሁ በምንድን ነው? ይህቺን በደሌን ይቅር በሉኝ።'),
  ('74d6d9f5-1585-56f7-aebb-edbc1c64a003', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 4, 14, 'እነሆ ወደ እናንተ ልመጣ ስዘጋጅ ይህ ሦስተኛዬ ነው፤ ነገር ግን አልተፋጠንሁም ገንዘባችሁን ያይደለ፥ እናንተን እሻለሁና፤ ልጆች ለወላጆቻቸው ያይደለ ወላጆች ለልጆቻቸው ሊያከማቹ ይገባልና፤'),
  ('da9bb403-1550-55f5-a8e6-9c577e508572', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 5, 15, 'እኔ ግን እጥፍ ድርብ አወጣለሁ፤ ስለ ሕይወታችሁም ሰውነቴን አሳልፌ እሰጣለሁ፤ እናንተንም እጅግ ብወዳችሁ ራሴን ወደድሁ።'),
  ('6e83d604-5694-5174-a937-9ecc291369d3', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 6, 16, 'እኔ አልከበድሁባችሁም፤ ነገር ግን ምክር ዐዋቂ ሆኜ በመጠበብ ወሰድኋችሁ።'),
  ('594111fc-297f-5490-a2d4-108c5bf97e4d', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 7, 17, 'በውኑ ይህን አድርጉልኝ ብዬ ወደ እናንተ የላክሁት መልእክት አለን? ወይስ የቀማኋችሁ ነገር አለን? እንጃ።'),
  ('58bc442c-72c6-5ff8-ad32-77976f1ba84b', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 8, 18, 'እነሆ ቲቶን ማለድሁት፤ ከእርሱም ጋር ሌላውን ወንድማችንን ላክሁት፤ በውኑ ቲቶ የበደላችሁ በደል አለን? በእርሱ በአደረው መንፈስ የምንመላለስ፥ እርሱም የሄደበትን ፍለጋ የምንከተል አይደለንምን?'),
  ('8180a55c-0a54-5026-a08d-62caad0e578a', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 9, 19, 'እኛስ ደግሞ ስለ ራሳችን የምንከራከራችሁ ይመስላችኋልን? በእግዚአብሔር ፊት በክርስቶስ ሆነን እንናገራለን፤ ወንድሞቻችን ሆይ፥ ይህ ሁሉ ግን እናንተ ትታነጹ ዘንድ ነው።'),
  ('bcbb615d-cd5c-5445-a4b9-dfb124337a0c', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 10, 20, 'ነገር ግን ወደ እናንተ በመጣሁ ጊዜ እንደምወደው ሆናችሁ ያላገኘኋችሁ እንደ ሆነ፤ እኔም እንደማትወዱት እሆንባችኋለሁ ብዬ እፈራለሁ፤ ወይም እኮ በመካከላችሁ ክርክር፥ ኵራት፥ መቀናናት፥ መበሳጨት፥ መዘባበት፥ ወይም መተማማት፥ መታወክ፥ ወይም ልብን ማስታበይ ይኖር ይሆናል።'),
  ('f2198d4a-4aea-50a7-a386-f56dcc863010', 'e0cd4365-76ab-5bb5-ac73-bfb2b838d6b2', '89115582-b1f2-54da-a1a9-fb4b7bfe2de9', 11, 21, 'ወይም እንደ ገና ወደ እናንተ በመጣሁ ጊዜ በእናንተ ምክንያት እግዚአብሔር ያሳዝነኝ ይሆናል፤ በድለው ንስሓ ላልገቡም ስለ ርኵስነታቸውና ስለ መዳራታቸው፥ ስለሚሠሩት ዝሙታቸውም ለብዙዎች አዝን ይሆናል።'),
  ('f99a18e9-6cdd-5549-a6fd-1e38e2c4b309', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 1, 1, 'ወደ እናንተ ስመጣ እነሆ ይህ ሦስተኛዬ ነው፤ ነገር ሁሉ፥ በሁለት ወይም በሦስት ምስክር አፍ የሚጸና አይደለምን?'),
  ('6eef1562-c8a3-52d7-a161-352fa6d66ab2', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 2, 2, 'ጥንቱን አስቀድሜ ተናግሬአለሁ፤ አሁንም አስቀድሜ እናገራለሁ፤ ቀድሞ ከእናንተ ጋር ሳለሁ እንደ ነገርሁአችሁ፥ አስቀድሞ ለበደሉ፥ ለሌሎችም ሁሉ እንደ ገና የመጣሁ እንደ ሆነ ርኅራኄ እንዳላደርግ፥ እንዲሁ ሳልኖር ለሦስተኛ ጊዜ እናገራለሁ፥'),
  ('3374f110-a633-5c6b-a386-1d0bc0f7a6d0', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 3, 3, 'ክርስቶስ በእኔ አድሮ እንደሚናገር ማስረጃ ትሻላችሁና፤ እርሱም ሁሉ የሚቻለው ነው እንጂ፥ በእናንተ ዘንድ የሚሳነው የለም።'),
  ('5dd57918-16c5-5659-a681-136d93726b8f', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 4, 4, 'በድካም ተሰቅሎአልና፤ በእግዚአብሔርም ኀይል ሕያው ነውና፤ እኛም ከእርሱ ጋር እንደክማለንና፤ ነገር ግን ስለ እናንተ በሚሆን በእግዚአብሔር ኀይል ከእርሱ ጋር በሕይወት እንኖራለን።'),
  ('c101f84d-9a02-5368-a4a1-9d4391d595c5', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 5, 5, 'በሃይማኖት ጸንታችሁ እንደ ሆነ ራሳችሁን መርምሩ፤ እናንተ ራሳችሁን ፈትኑ፤ ኢየሱስ ክርስቶስ ከእናንተ ጋር እንዳለ አታውቁምን? እንዲህ ካልሆነ ግን እናንተ የተናቃችሁ ናችሁ።'),
  ('b8e1f21d-997a-5bfe-aafb-4769203b7fee', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 6, 6, 'እኛም ብንሆን የተናቅን እንዳይደለን እንደምታውቁ እኔ አምናለሁ።'),
  ('96dd5d79-cbaf-51da-aa9a-65db626598fa', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 7, 7, 'ምንም ክፉ ሥራ እንዳትሠሩ ወደ እግዚአብሔር እንጸልያለን፤ መልካም ነገር እንድታደርጉ ብቻ ነው እንጂ እኛ ደጎች ልንባል አይደለም፤ እኛም እንደ ተናቁ ሰዎች እንሆናለን።'),
  ('8bcacd62-910d-56da-a1ae-03bc2c07372e', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 8, 8, 'ለዕውነት ጸንተን እንኖራለን እንጂ፤ ከዕውነት መውጣት አንችልምና።'),
  ('2c80398e-bb93-5efe-aa95-6912796b3c66', '9bc9c397-027b-5803-ae91-77f95d2e9e70', 'f958e24f-b046-55e0-a3fc-1fd096e03875', 9, 9, 'እናንተ ትበረቱ ዘንድ እኛ ስንደክም ደስ ይለናል። ጸሎታችንም እናንተ ፍጹማን ትሆኑ ዘንድ ነው።'),
  ('f4843a41-ff71-50f7-a72f-d808cad61729', '9bc9c397-027b-5803-ae91-77f95d2e9e70', '58ef6e3a-3e0b-5d53-aabf-3f0bb4865ca7', 1, 10, 'ስለዚህም እግዚአብሔር ለማፍረስ ያይደለ ለማነጽ በሰጠን ሥልጣን ወደ እናንተ በመጣሁ ጊዜ ቍርጥ ነገር እንዳላደርግባችሁ፥ ሥልጣን እንዳለው ሰው ከእናንተ ጋር ሳልኖር ይህን እጽፋለሁ።'),
  ('46f2560d-333e-5708-a2ea-4af557c289e1', '9bc9c397-027b-5803-ae91-77f95d2e9e70', '58ef6e3a-3e0b-5d53-aabf-3f0bb4865ca7', 2, 11, 'ወድሞቻችን ሆይ፥ እንግዲህ ደስ ይበላችሁ፤ ጽኑ፤ ታገሡ፤ በአንድ ልብም ሁኑ፤ በሰላም ኑሩ፤ የሰላምና የፍቅር አምላክም ከእናንተ ጋር ይሁን።'),
  ('4736e16f-5af8-5c45-ad35-0104a9576c0d', '9bc9c397-027b-5803-ae91-77f95d2e9e70', '58ef6e3a-3e0b-5d53-aabf-3f0bb4865ca7', 3, 12, 'በተቀደሰ ሰላምታ እርስ በርሳችሁ ሰላም ተባባሉ፤ ቅዱሳን ሁሉ እንዴት ናችሁ? ይሏችኋል።'),
  ('3d92b59b-f3e3-50d3-a829-2fb729e887e3', '9bc9c397-027b-5803-ae91-77f95d2e9e70', '58ef6e3a-3e0b-5d53-aabf-3f0bb4865ca7', 4, 13, 'የጌታችን የኢየሱስ ክርስቶስ ጸጋ፥ የእግዚአብሔር ፍቅር፥ የመንፈስ ቅዱስም አንድነት ከሁላችሁ ጋር ይሁን። አሜን።'),
  ('de4369d3-19fa-58b9-a792-1137709a4ee0', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 1, 1, 'በጌታችን በኢየሱስ ክርስቶስና ከሙታን ለይቶ በአስነሣው በእግዚአብሔር አብ ነው እንጂ ከሰዎች ወይም በሰው ሐዋርያ ካልሆነ ከጳውሎስ፥'),
  ('6ddaa06d-08e2-563a-ae44-3192e4d7e7eb', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 2, 2, 'አብረውኝ ካሉ ከወንድሞቻችንም፥ በገላትያ ላሉ አብያተ ክርስቲያን፤'),
  ('bb59df1b-fc13-502a-a6f4-3b219a5972c8', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 3, 3, 'ከአባታችን ከእግዚአብሔር፥ ከጌታችን ከኢየሱስ ክርስቶስም ሰላምና ጸጋ ለእናንተ ይሁን።'),
  ('8d753355-8ea4-584b-ac2f-78dd0865f1e3', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 4, 4, 'በክፉ ከሚቃወም ከዚህ ዓለም ያድነን ዘንድ በአባታችን በእግዚአብሔር ፈቃድ ስለ ኀጢአታችን ራሱን አሳልፎ ሰጠ።'),
  ('652d6fc4-ede2-5a51-aa4a-396a15aaeaa4', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 5, 5, 'ለእርሱ ክብር ይሁን፤ ከዘለዓለም እስከ ዘለዓለም አሜን።'),
  ('43ac6d7d-ab94-53a0-abb1-45de2b392276', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 6, 6, 'በጸጋዉ የጠራችሁን ክርስቶስን ከማመን ወደ ልዩ ወንጌል እንዴት ፈጥነው እንዳስወጧችሁ አደንቃለሁ።'),
  ('75a7344a-58a7-531c-ab3b-025129fdd46b', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 7, 7, 'እርሱ ግን ሌላ አይደለም፤ የሚያውኳችሁ ከክርስቶስም ወንጌል ሊያጣምሙ የሚወዱ አሉ እንጂ።'),
  ('01640631-261f-55bf-ae3c-73db3da5c6e2', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 8, 8, 'እናንተ ግን የእኛን ፍለጋ ተከተሉ፤ እናንተስ እኛም ብንሆን ወይም መልአክ ከሰማይ ወርዶ እኛ ካስተማርናችሁ ወንጌል ሌላ ቢሰብክላችሁ ውጉዝ ይሁን።'),
  ('ef945c7b-30f5-51af-a36c-ed06a568f6c0', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 9, 9, 'አስቀድሜ እንደ አልሁ አሁንም ደግሞ እላለሁ፦ ካስተማርናችሁ ሌላ ትምህርት ያስተማራችሁ ቢኖር ውጉዝ ይሁን።'),
  ('d3287624-e1c4-50c3-abef-14fe579ca594', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'ab1bcb41-8127-5cfe-a604-eb338d38a636', 10, 10, 'አሁንስ ለእግዚአብሔር ያይደለ ለሰው ብዬ አስተምራለሁን? ወይስ ሰውን ደስ አሰኛለሁን? ሰውን ደስ ላሰኝ ብወድስ የክርስቶስ ባሪያ አይደለሁም።'),
  ('fadc6822-ee33-5400-ac7c-b466c662a447', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'dab84a62-0c07-5443-aa81-613184373384', 1, 11, 'ወንድሞቻችን ሆይ፥ ያስተማርኋችሁ ወንጌል ስለ ሰው እንዳይደለ አስታውቃችኋለሁ።'),
  ('f649819d-5067-5566-a2e0-702b5e6d1ef9', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'dab84a62-0c07-5443-aa81-613184373384', 2, 12, 'ጌታ ኢየሱስ ክርስቶስ ገለጠልኝ እንጂ፥ እኔ ከሰው አልተቀበልሁትም፤ አልተማርሁትምም።'),
  ('76a945d3-ec96-51c3-a299-fd50755d4a31', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'dab84a62-0c07-5443-aa81-613184373384', 3, 13, 'በአይሁድ ሥርዐት ውስጥ በነበርሁ ጊዜ፥ የነበረውን የቀድሞ ሥራዬን ሰምታችኋል፤ የእግዚአብሔርን ቤተ ክርስቲያን እጅግ አሳድድና መከራ አጸናባቸው ነበር።'),
  ('9cc3aa59-d525-5ed9-a28b-4f91da30a257', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'dab84a62-0c07-5443-aa81-613184373384', 4, 14, 'ለአባቶች ሥርዐት እጅግ ቀናተኛ ነበርሁና በወገኖች ዘንድ ከጓደኞች ሁሉ በአይሁድ ዘንድ እጅግ ከበርሁ።'),
  ('6855522a-7e4c-5538-a0ae-40777ed81e73', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'dab84a62-0c07-5443-aa81-613184373384', 5, 15, 'ከእናቴ ማኅፀን ለይቶ ያወጣኝ እግዚአብሔር በወደደ ጊዜ በጸጋው ጠራኝ።'),
  ('2ca62e0c-e296-5761-a3e9-3deaa9bd598f', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'dab84a62-0c07-5443-aa81-613184373384', 6, 16, 'በስሙም ለአሕዛብ ወንጌልን አስተምር ዘንድ፥ በእጄም የልጁ ክብር ይታወቅ ዘንድ ልጁን ገለጠልኝ፤ ያንጊዜም ከሥጋዊና ከደማዊ ሰው ጋር አልተማከርሁም።'),
  ('ab53c3d6-6d5e-5002-a131-f9e4c50143bb', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'dab84a62-0c07-5443-aa81-613184373384', 7, 17, 'ከእኔ በፊት ወደ ነበሩት ወደ ሐዋርያትም ወደ ኢየሩሳሌም አልወጣሁም፤ ነገር ግን ወደ ዐረብ ሀገር ሄድሁ፤ ዳግመኛም ወደ ደማስቆ ተመለስሁ።'),
  ('41d6c897-b3ea-5888-aed8-4d2fa3aafaf2', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'd85115ba-0697-5e81-ac5a-88f747fa12d9', 1, 18, 'ከሦስት ዓመት በኋላ ግን ኬፋን ላየው ወደ ኢየሩሳሌም ወጣሁ፤ በእርሱ ዘንድም ዐሥራ አምስት ቀን ሰነበትሁ።'),
  ('4a506306-95c0-5b89-a353-1310176f984e', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'd85115ba-0697-5e81-ac5a-88f747fa12d9', 2, 19, 'ነገር ግን የጌታችን ወንድም ያዕቆብን እንጂ ከሐዋርያት ሌላ አላየሁም።'),
  ('9d4606bb-5845-512b-a656-5525f8ee5d04', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'd85115ba-0697-5e81-ac5a-88f747fa12d9', 3, 20, 'ስለምጽፍላችሁም ነገር እነሆ፥ በእግዚአብሔር ፊት ሐሰት አልናገርም።'),
  ('590c90e0-012d-518c-ab84-81fe72d1fa02', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'd85115ba-0697-5e81-ac5a-88f747fa12d9', 4, 21, 'ከዚህም በኋላ ወደ ሶርያና ወደ ቂልቅያ አውራጃ መጣሁ።'),
  ('cc1d60ac-4b17-5f7d-a098-06b7f3827ca7', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'd85115ba-0697-5e81-ac5a-88f747fa12d9', 5, 22, 'በክርስቶስም ያሉት የይሁዳ ሀገር ማኅበረ ክርስቲያን ፊቴን አያውቁም ነበር።'),
  ('a0de400e-97c2-5587-a1a0-de7c4abaad9a', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'd85115ba-0697-5e81-ac5a-88f747fa12d9', 6, 23, 'ነገር ግን “ቀድሞ ምእመናንን ያሳድድ የነበረው እርሱ በፊት ያጠፋው የነበረውን የሃይማኖት ትምህርት ዛሬ ይሰብካል” ሲባል ወሬዬን ይሰሙ ነበር።'),
  ('c538d176-4cb1-5e9f-ae97-728f5014cec2', '49a34cd1-113d-5da9-a620-71ec4551af4d', 'd85115ba-0697-5e81-ac5a-88f747fa12d9', 7, 24, 'ስለ እኔም እግዚአብሔርን ያመሰግኑት ነበር።'),
  ('5a9abf0d-df40-52ab-ad5c-bf3e8ffba8c4', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 1, 1, 'ከዐሥራ አራት ዓመትም በኋላ ከበርናባስ ጋር እንደ ገና ወደ ኢየሩሳሌም ወጣሁ፤ ቲቶንም ይዠው ሄድሁ።'),
  ('5cf39f09-fa07-5b57-a13f-c9af5ff0ecdd', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 2, 2, 'እንደ ተገለጠልኝም ወጣሁ፤ በከንቱ እንዳልሮጥ፥ ወይም በከንቱ ሮጬ እንዳልሆነ፥ በአሕዛብ መካከል የምሰብከውን ወንጌል አለቆች መስለው ለሚታዩት አስታወቅኋቸው።'),
  ('d470c745-7b92-538f-a100-ce58c420a862', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 3, 3, 'አብሮኝ የነበረው ቲቶም አረማዊ ሲሆን እንዲገዘር ግድ አላልሁትም።'),
  ('8514be1f-99cc-599c-a4a3-fffa18199b88', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 4, 4, 'ይኸውም ባሪያዎች ያደርጉን ዘንድ በኢየሱስ ክርስቶስ ያገኘናትን ነጻነት ሊሰልሉ በስውር ወደ እኛ የገቡ ሐሰተኞች መምህራንን ደስ አይበላቸው ብዬ ነው።'),
  ('7d753f65-6ba9-56a0-a00e-0e524e1dcab5', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 5, 5, 'ለምንም ይሆናሉ ብለን የማናስባቸው ናቸው፤ እውነተኛው ትምህርት በእናንተ ይጸና ዘንድ አንዲት ሰዓትም እንኳ አልተገዛንላቸውም።'),
  ('f586d190-0d7d-5a31-aae9-be03796b0a4a', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 6, 6, 'አለቆች የመሰሉት ግን ቀድሞ እነርሱ እንዴት እንደ ነበሩ ልናገር አያገደኝም፤ እግዚአብሔር ለሰው ፊት አያዳላምና፤ አለቆች የመሰሉትም ከራሳቸው ምንም ነገር የጨመሩልኝ የለምና።'),
  ('be32d748-be43-55a3-aae1-6e39c6f0a2d2', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 7, 7, 'የጴጥሮስ ትምህርት በተገዘሩ በአይሁድ ዘንድ እንደ ታመነለት፥ የእኔም ትምህርት ባልተገዘሩ በአሕዛብ ዘንድ እንደ ታመነ ዐውቀዋል እንጂ።'),
  ('4b4f8d86-8d65-5a73-a93b-065dbc06ba9c', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 8, 8, 'ወደ ተገዘሩ አይሁድ በተላከ ጊዜ ጴጥሮስን የረዳው እርሱ እኔንም ባልተገዘሩ አሕዛብ ዘንድ ረዳኝ።'),
  ('8a9d6b35-ef33-5065-a800-a7cc199eede6', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 9, 9, 'የሰጠኝንም ጸጋ ዐውቀው አዕማድ የሚሏቸው ያዕቆብና ኬፋ፥ ዮሐንስም እኛ ወደ አሕዛብ፥ እነርሱም ወደ አይሁድ እንድንሄድ ለእኔና ለበርናባስ ቀኝ እጃቸውን ሰጡን።'),
  ('ef897303-6328-581a-ae60-50bc17c38a33', 'b322de51-d2f5-5006-a6f6-6557f058d18b', '2af3fc39-f4c6-59b9-a42c-196cced622df', 10, 10, 'ይልቁንም ነዳያንን እንድናስባቸው ነው፤ ስለዚህም ይህን ነገር ልፈጽመው ተጋሁ።'),
  ('e8b8cc23-070a-5fee-a703-638e9f4339ee', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 1, 11, 'ነገር ግን ኬፋ ወደ አንጾኪያ በመጣ ጊዜ ፊት ለፊት ተቃወምሁት፤ ነቅፈውት ነበርና።'),
  ('ec1d8940-088a-5063-a3df-d92c61dbf91a', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 2, 12, 'ሰዎች ከያዕቆብ ዘንድ ከመምጣታቸው በፊት፥ ከአረማውያን ጋር ይበላ ነበርና፥ በመጡ ጊዜ ግን ተለያቸው፤ ከአይሁድ ወገን የሆኑትን ፈርቶአልና።'),
  ('1fa46f12-7276-50c7-a61b-3582ab3d0505', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 3, 13, 'ከአይሁድ ወገንም ወደዚህ ግብር የተመለሱ ብዙዎች ነበሩ፤ በርናባስም እንኳ በግብዝነታቸው ተባበረ።'),
  ('e2d5dd00-f624-5706-a58c-9a6e64b44650', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 4, 14, 'ነገር ግን ወደ እውነተኛው ወንጌል እግራቸውን እንዳላቀኑ ባየሁ ጊዜ፥ በሰው ሁሉ ፊት ኬፋን እንዲህ አልሁት፥ “አንተ አይሁዳዊ ስትሆን በአይሁድ ሥርዐት ያይደለ፥ በአረማውያን ሥርዐት የምትኖር ከሆነ እንግዲህ አይሁድ እንዲሆኑ አረማውያንን ለምን ታስገድዳቸዋለህ?”'),
  ('5be3cabc-fbc5-5e23-ad65-e86a6ae699cf', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 5, 15, 'እኛ በትውልዳችን አይሁድ ነን፤ ኀጢአተኞች የሆኑ አሕዛብም አይደለንም።'),
  ('ff7f1534-900b-5280-a49c-d128100ad52c', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 6, 16, 'ሰው በኢየሱስ ክርስቶስ በማመን እንጂ የኦሪትን ሥራ በመሥራት እንደማይጸድቅ እናውቃለንና፤ እኛም የኦሪትን ሥራ በመሥራት ሳይሆን በእርሱ በማመናችን እንጸድቅ ዘንድ በኢየሱስ ክርስቶስ አምነናል፤ ሰው ሁሉ በኦሪት ሥራ አይጸድቅምና።'),
  ('537a00e6-793a-521b-aea3-abd19ca10812', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 7, 17, 'በክርስቶስ ልንጸድቅ የምንሻ እኛ እንደ ኀጢአተኞች ከሆን እንግዲህ ክርስቶስ የኀጢአት አገልጋይ መሆኑ ነውን? አይደለም።'),
  ('df9d184a-1d6a-55ba-a064-e3179f46fe69', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 8, 18, 'ያን ያፈረስሁትን መልሼ የማንጽ ከሆነ ራሴን ሕግ አፍራሽ አደረግሁ።'),
  ('8d73a9c3-cba8-57b3-aace-462dadfa9b51', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 9, 19, 'እኔስ ለእግዚአብሔር ሕያው ሆኜ በሁለተኛው ሕግ እኖር ዘንድ ከቀደመው ሕግ ተለየሁ።'),
  ('460cf901-47ab-5243-aefa-7f09fcb73eeb', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 10, 20, 'ከክርስቶስ ጋርም ተሰቀልሁ፤ ሕይወቴም አለቀች፤ ነገር ግን በክርስቶስ ሕይወት አለሁ፤ ዛሬም በሥጋዬ የምኖረውን ኑሮ የወደደኝን ስለ እኔም ራሱን አሳልፎ የሰጠውን የእግዚአብሔርን ልጅ በማመን እኖራለሁ።'),
  ('80f73280-d0fc-5333-aecc-d4089d362356', 'b322de51-d2f5-5006-a6f6-6557f058d18b', 'a233ba77-cd69-5bab-a1df-a0cf1d7d5f0c', 11, 21, 'የእግዚአብሔርንም ጸጋ አልክድም፤ የኦሪትን ሥራ በመሥራት የሚጸድቁ ከሆነ እንኪያስ ክርስቶስ በከንቱ ሞተ።'),
  ('0fc3aac2-3e4a-5bed-abd2-da1a19a53ac3', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'df7bd578-8908-5100-a277-8c96376e0e5b', 1, 1, 'እናንተ ሰነፎች የገላትያ ሰዎች ሆይ፥ ለዐይን በሚታየው እውነት እንዳታምኑ ማን አታለላችሁ? እርሱም እንዲሰቀል አስቀድሞ የተጻፈለት ኢየሱስ ክርስቶስ ነው።'),
  ('c8acc661-5c93-5c2b-a3a2-e7a6f6d3e222', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'df7bd578-8908-5100-a277-8c96376e0e5b', 2, 2, 'በእናንተ ዘንድ ይህን ብቻ ላውቅ እወድዳለሁ፤ መንፈስ ቅዱስን የተቀበላችሁ የኦሪትን ሥራ በመሥራት ነውን? ወይስ ሃይማኖትን በመስማት?'),
  ('787aa49a-6eb7-57ce-a13c-4a41cf895a7f', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'df7bd578-8908-5100-a277-8c96376e0e5b', 3, 3, 'እንዲህን ሰነፎች ናችሁን? የመንፈስ ቅዱስን ሥራ ከጀመራችሁ በኋላ የሥጋን ሕግ ልትሠሩ ትመለሳላችሁን?'),
  ('6438bef9-5adf-5e9d-a700-6b2aee83f4c7', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'df7bd578-8908-5100-a277-8c96376e0e5b', 4, 4, 'ይህን ያህል መከራ ተቀብላችሁ፥ ለከንቱ አደረጋችሁት።'),
  ('dd9f8209-e1ce-54da-a262-99c2dc62df04', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'df7bd578-8908-5100-a277-8c96376e0e5b', 5, 5, 'እርሱ መንፈስ ቅዱስን የሚሰጣችሁ፥ ኀይልንም የሚያደርግላችሁ የኦሪትን ሥራ በመሥራት ነውን? ወይስ ሃይማኖትን በመስማት ነው?'),
  ('f2921c72-c9c9-5065-ae5e-7db3fb0b9b90', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 1, 6, 'አብርሃም በእግዚአብሔር እንደ አመነ፥ ጽድቅም ሆኖ እንደ ተቈጠረለት፥'),
  ('7039441d-e29d-5c8a-a363-71765e8896c5', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 2, 7, 'እንግዲህ ያመኑት የአብርሃም ልጆች እንደ ሆኑ ታውቃላችሁ።'),
  ('35aa3049-c736-5d1c-a8c8-3cc0abd0f350', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 3, 8, 'እግዚአብሔር አሕዛብን በእምነት እንደሚያጸድቃቸው መጽሐፍ አስቀድሞ ገልጦአልና፤ አሕዛብም ሁሉ በእርሱ እንዲባረኩ እግዚአብሔር አስቀድሞ ለአብርሃም ተስፋ ሰጠው።'),
  ('cd000fa8-ab93-5bb3-af85-dcdeaae5d392', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 4, 9, 'አሁንም የሚያምኑ ከአመነው ከአብርሃም ጋር ይባረካሉ።'),
  ('f471505b-00a6-5d58-a8cd-54471919fb0b', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 5, 10, 'በኦሪት ሕግ ያሉ ሁሉ በእርግማን ውስጥ ይኖራሉ፤ መጽሐፍ እንዲህ ብሎአልና፥ “በዚህ በኦሪት መጽሐፍ ውስጥ የተጻፈውን ሁሉ የማይፈጽምና የማይጠብቅ ርጉም ይሁን።”'),
  ('d824efaa-9977-543e-a2c0-d66371f27def', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 6, 11, 'የኦሪትን ሥራ በመሥራትስ በእግዚአብሔር ዘንድ እንደማይጸድቁ ይታወቃል፤ “ጻድቅ ግን በእምነት ይድናል” ተብሎ ተጽፎአል።'),
  ('944956ba-054b-547b-abed-ca5f3c95bfb6', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 7, 12, 'ኦሪትስ ሠርቶ የፈጸመ ይኖርበታል እንጂ በእምነት የሚያጸድቅ አይደለም።'),
  ('527d174d-cf41-5d8e-ab91-d6d11fe93f82', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 8, 13, 'እኛንስ ክርስቶስ ስለ እኛ የኦሪትን መርገም በመሸከሙ ከኦሪት መርገም ዋጅቶናል፤ መጽሐፍ እንዲህ ብሎአልና፥ “በእንጨት ላይ የተሰቀለ ሁሉ ርጉም ነው።”'),
  ('3fd01a54-c82a-5221-a85b-2888a5f4d0f4', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'ae257d18-68b1-5e83-adbe-aa3c7b1df3d6', 9, 14, 'እኛ በክርስቶስ አምነን የመንፈስ ቅዱስን ተስፋ እንድናገኝ የአብርሃም በረከት በኢየሱስ ክርስቶስ ወደ አሕዛብ ይመለስ ዘንድ።'),
  ('4d8ec7fa-a5d0-53d5-a73a-e7ae1bfdb89a', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 1, 15, 'ወንድሞች ሆይ፥ እንደ ሰው ልማድ እንናገራለን፤ ሰውም እንኳን የጸናውን ኪዳን አይንቅም አይጨምርበትምም።'),
  ('f6a80e9a-97c4-54c8-a6d6-fd0d60b7c4c9', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 2, 16, 'እግዚአብሔርም ለአብርሃም፥ “ለአንተና ለዘርህ” ብሎ ተስፋ ሰጠው፤ ለብዙዎች እንደሚናገር አድርጎ ለአንተና ለዘሮችህ አላለውም፤ ለአንድ እንደሚናገር አድርጎ፥ “ለዘርህ” አለው እንጂ ይኸውም ክርስቶስ ነው።'),
  ('c48da8e3-8aa7-5fa2-a3b4-707b39fd071f', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 3, 17, 'እንግዲህ እንዲህ እላለሁ፦ ከእግዚአብሔር የተሰጠ ይህ ኪዳን ጽኑዕ ነው፤ ከዚህም በኋላ በአራት መቶ ሠላሳ ዓመት ኦሪት መጣች፤ ነገር ግን እግዚአብሔር የሰጠውን ተስፋ ልትከለክል አይደለም።'),
  ('eaec339b-64e9-5356-acbe-12eb4d92caa0', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 4, 18, 'መውረስ የኦሪትን ሕግ በመሥራት ከሆነ እንግዲህ በሰጠው ተስፋ አይደለማ፤ እነሆ እግዚአብሔር አስቀድሞ ለአብርሃም ተስፋውን ሰጠው።'),
  ('3046ba73-db3f-55ce-ae38-bcbcf041de3a', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 5, 19, 'ታዲያ ኦሪት ለምን ተሠራች? ኦሪትስ ኀጢአትን ታበዛት ዘንድ፥ ተስፋ ያደረገለት ያ ዘር እስኪመጣ ድረስ፥ በመላእክት በኩል በመካከለኛው እጅ ወረደች።'),
  ('7ca184ea-fdb1-564b-ad89-1c76b1bfde60', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 6, 20, 'መካከለኛው ግን ማንም አይደለም፤ አንድ እግዚአብሔር ነው እንጂ።'),
  ('f638cdb1-b69d-596e-a425-9546ebe396c6', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 7, 21, 'እንግዲህ ኦሪት እግዚአብሔር የሰጠውን ተስፋ ልትከለክል መጣችን? አይደለም፤ ማዳን የሚቻለው ሕግ ተሠርቶ ቢሆንማ፥ በእውነት በዚያ ሕግ ጽድቅ በተገኘ ነበር።'),
  ('dcf44ece-4847-51b0-a717-2f37e7bb6063', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', '81538a6d-d273-5986-a6ad-0ea3f3ae913c', 8, 22, 'ነገር ግን ተስፋ በኢየሱስ ክርስቶስ በማመን ይሆን ዘንድ፥ ያመኑትም ያገኙት ዘንድ፥ መጽሐፍ ሁሉን በኀጢአት ዘግቶታል።'),
  ('1d051e9d-e1e1-513b-aa9b-b523023c3070', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'c722c0c7-d553-5139-a6a5-34dda9f56071', 1, 23, 'እምነት ሳይመጣ ኦሪት ጠበቀችን፤ ወደሚመጣውም እምነት መራችን።'),
  ('ec4b2f6a-2623-55ee-ae6f-184645a3eb1d', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'c722c0c7-d553-5139-a6a5-34dda9f56071', 2, 24, 'እንግዲህ ኦሪት በእርሱ በማመን እንጸድቅ ዘንድ ወደ ክርስቶስ መሪ ሆነችን።'),
  ('b82d11f6-3d70-5d16-a54a-7fa7e3d1002e', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'c722c0c7-d553-5139-a6a5-34dda9f56071', 3, 25, 'እንግዲህ እምነት ከመጣች መሪ አንሻም።'),
  ('c48ec8ac-1ea2-5bbe-a31e-671b6719a090', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'c722c0c7-d553-5139-a6a5-34dda9f56071', 4, 26, 'በኢየሱስ ክርስቶስ በማመን ሁላችን የእግዚአብሔር ልጆች ሆነናልና።'),
  ('5502ad0f-69e0-5b7a-a4d5-bd6e7be2f449', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'c722c0c7-d553-5139-a6a5-34dda9f56071', 5, 27, 'በክርስቶስ የተጠመቃችሁ እናንተማ ክርስቶስን ለብሳችኋል።'),
  ('a6a921f8-bf77-5950-ad32-fc4839b647e7', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'c722c0c7-d553-5139-a6a5-34dda9f56071', 6, 28, 'በዚህም አይሁዳዊ፥ ወይም አረማዊ የለም፤ ገዢ፥ ወይም ተገዢ የለም፤ ወንድ፥ ወይም ሴት የለም፤ ሁላችሁ በኢየሱስ ክርስቶስ አንድ ናችሁና።'),
  ('6b613cd4-22ae-56d5-ae39-c8ac5c60554f', 'bd26e719-723f-5ea5-a077-cf69ebdca7b0', 'c722c0c7-d553-5139-a6a5-34dda9f56071', 7, 29, 'ለኢየሱስ ክርስቶስ ከሆናችሁም እንግዲህ ተስፋውን የምትወርሱ የአብርሃም ዘር እናንተ ናችሁ።'),
  ('c22658fc-9df2-556c-a8a6-3255013df4c2', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1ca4a645-4c14-5c1f-a824-01b6b9127c94', 1, 1, 'ነገር ግን እላለሁ፤ ወራሹ ሕፃን ሳለ ለሁሉ ጌታ ሲሆን ከአገልጋይ የሚለይ አይደለም።'),
  ('486d0041-9ea2-5f65-ad0d-39b2928496f8', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1ca4a645-4c14-5c1f-a824-01b6b9127c94', 2, 2, 'ነገር ግን አባቱ እስከ ቀጠረለት ዕድሜ ድረስ በአያት ወይም በሞግዚት እጅ ይጠበቃል።'),
  ('462b9e77-b8da-5569-a6bc-953342095acd', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1ca4a645-4c14-5c1f-a824-01b6b9127c94', 3, 3, 'እንዲሁ እኛም ሕፃናት በነበርን ጊዜ፥ ለዚህ ዓለም ስሕተት ተገዝተን ነበር።'),
  ('b909ac42-9373-5cb5-a00e-17a47396f84c', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1ca4a645-4c14-5c1f-a824-01b6b9127c94', 4, 4, 'ነገር ግን ቀጠሮው በደረሰ ጊዜ እግዚአብሔር ልጁን ላከ፤ ከሴትም ተወለደ፤ የኦሪትንም ሕግ ፈጸመ።'),
  ('ad4cd262-e7f4-59d4-a11a-315c388ec398', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1ca4a645-4c14-5c1f-a824-01b6b9127c94', 5, 5, 'እኛ የልጅነትን ክብር እንድናገኝ በኦሪት የነበሩትን ይዋጅ ዘንድ።'),
  ('e6300194-585e-5483-a6f2-cc2b1d625d3a', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1ca4a645-4c14-5c1f-a824-01b6b9127c94', 6, 6, 'ልጆች እንደ መሆናችሁ መጠን እግዚአብሔር አባ አባቴ ብላችሁ የምትጠሩትን የልጁን መንፈስ በልባችሁ አሳደረ።'),
  ('aab3b1e2-e613-5dd9-ac94-cc21006efe6f', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1ca4a645-4c14-5c1f-a824-01b6b9127c94', 7, 7, 'እንኪያስ እናንተ ልጆች ናችሁ እንጂ ባሮች አይደላችሁም፤ ልጆች ከሆናችሁም በኢየሱስ ክርስቶስ የእግዚአብሔር ወራሾች ናችሁ።'),
  ('69ba41a9-78bc-5ed7-adb8-5f7c2c402c34', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 1, 8, 'ነገር ግን ቀድሞ እግዚአብሔርን ባለማወቃችሁ፥ በባሕርያቸው አማልክት ላልሆኑ ተገዝታችሁ ነበር።'),
  ('8d37576b-ed99-57b6-af21-32cdae5adec5', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 2, 9, 'ዛሬ ግን እግዚአብሔርን ዐወቃችሁት፤ ይልቁንም እርሱ ዐወቃችሁ፤ እንደ ገና ደግሞ ወደዚያ ወደ ደካማው፥ ወደ ድሀው ወደዚህ ዓለም ጣዖት ተመልሳችሁ፥ ትገዙላቸው ዘንድ እንዴት ፈጠራን ትሻላችሁ?'),
  ('7b2ec320-9b2e-5914-a373-07ffb4473af9', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 3, 10, 'ዕለትንና ወርን፥ ጊዜንና ዓመታትን ትጠብቃላችሁ።'),
  ('41b13485-e771-5801-ac89-917cfe8f4fa5', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 4, 11, 'ስለ እናንተ በከንቱ ደክሜ እንደ ሆነ ብዬ እፈራችኋለሁ።'),
  ('8f51c03f-648b-5e5e-ae6e-a244d484168f', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 5, 12, 'ወንድሞቻችን ሆይ፥ እኔ ደግሞ እንደ እናንተ ሁኛለሁ፤ እንደ እኔ ሁኑ ብዬ እማልዳችኋለሁ፤ አንዳች አልበደላችሁኝምና።'),
  ('3ce5081b-0acc-5b2e-a2af-875f7dc75061', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 6, 13, 'መጀመሪያ ወንጌልን በሰበክሁላችሁ ጊዜ፥ ከሥጋ ድካም የተነሣ እንደ ነበር ታውቃላችሁ።'),
  ('b5f3868a-a19c-54f2-a226-21528bb4190e', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 7, 14, 'መከራ እቀበል በነበረበት ጊዜ አልሰለቻችሁኝም፤ እንደ እግዚአብሔር መልአክ፥ እንደ ኢየሱስ ክርስቶስም ተቀበላችሁኝ እንጂ በሰውነቴ አልናቃችሁኝም።'),
  ('50953b0d-65d8-551b-a3e1-4953b67244c7', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 8, 15, 'አሁንስ ደስ ማሰኘታችሁ ወዴት አለ? ቢቻላችሁስ ዐይናችሁንም እንኳ ቢሆን አውጥታችሁ ትሰጡኝ እንደ ነበረ፥ እኔ ምስክራችሁ ነኝ።'),
  ('2869bbdf-aa7e-5d87-a767-b7244c77d5d9', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 9, 16, 'እውነቱን ስለ ነገርኋችሁ ባላጋራ ሆንኋችሁን?'),
  ('994fde53-0b04-599e-a390-e014ee1c794a', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 10, 17, 'እነዚያማ ይቀኑባችኋል፤ ነገር ግን በእነርሱ ላይ እንድትቀኑ ሊዘጉአችሁ ይወዳሉ እንጂ ለመልካም አይደለም።'),
  ('a4875c3b-80be-5a4f-a74c-600d36dcbd3e', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 11, 18, 'መቅናትስ ዘወትር ለመልካም ሥራ ልትቀኑ ይገባል፤ ነገር ግን እኔ ከእናንተ ዘንድ ባለሁበት ጊዜ ብቻ አይደለም።'),
  ('5bd27592-9ac2-5762-ae35-ba994b2d5eed', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 12, 19, 'ልጆች፥ እንደ ገና የምጨነቅላችሁ ክርስቶስ በልባችሁ እስኪሣልባችሁ ድረስ ነው።'),
  ('4a644167-f198-566a-ace0-5559838d81ed', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 13, 20, 'ቃሌን ለውጬ አሁን በእናንተ ዘንድ ልገኝ እሻለሁ፤ ስለ እናንተ የምናገረውን አጣለሁና።'),
  ('e473ee9b-f679-5a6b-a9d4-4dfaf8bb4a51', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 14, 21, 'በኦሪት ሕግ እንኑር ትላላችሁን? ኦሪትን አትሰሙአትምን?'),
  ('d533e7c6-8b17-5c82-acb9-c786efcef3ad', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 15, 22, 'አብርሃም ሁለት ልጆችን አንዱን ከባሪያዪቱ፥ አንዱንም ከእመቤቲቱ እንደ ወለደ ተጽፎአልና።'),
  ('e7ba9916-6b72-52f7-a872-24952b0a6ce3', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 16, 23, 'ነገር ግን ከባሪያዪቱ የተወለደው ልደቱ ልዩ ነው፤ በሰው ልማድ ተወለደ፤ ከእመቤቲቱ የተወለደው ግን እግዚአብሔር በሰጠው ተስፋ ተወለደ።'),
  ('f228506b-2aa3-5d51-aae0-85976045ede6', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 17, 24, 'ይህም የሁለቱ ሥርዐት ምሳሌ ነው፤ አንዲቱ ከደብረ ሲና ለባርነት ትወልዳለች፤ እርስዋም አጋር ናት።'),
  ('19cd03c2-8830-5733-a014-1e6805ede918', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 18, 25, 'አጋርም በዐረብ ሀገር ያለች ደብረ ሲና ናት፤ ከዛሬዪቱ ኢየሩሳሌም ጋር ትነጻጸራለች፤ ከልጆችዋ ጋርም ትገዛለች።'),
  ('d709b8ac-3069-5c86-ab0a-5c3e005084ce', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 19, 26, 'የላይኛዪቱ ኢየሩሳሌም ግን በነፃነት የምትኖር ናት፤ እርስዋም እናታችን ናት።'),
  ('3edb3a5a-1b92-503a-a1b4-53d9e1f5edb4', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 20, 27, '“የማትወልድ መካን ደስ ይላታል፤ ምጥ የማታውቀውም ደስ ብሎአት እልል ትላለች፤ ባል ካላት ይልቅ የፈቲቱ ልጆች ብዙዎች ናቸውና” ተብሎ ተጽፎአል።'),
  ('0de46f86-8ffa-508b-a6ed-fd84793e300a', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 21, 28, 'ወንድሞቻችን ሆይ፥ እኛስ እንደ ይስሐቅ የተስፋ ልጆች ነን።'),
  ('695aaa52-6572-57fb-af0b-ec426524dff5', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 22, 29, 'ነገር ግን በሥጋ ልማድ የተወለደው በመንፈሳዊ ግብር የተወለደውን በዚያ ጊዜ እንዳሳደደው ዛሬም እንዲሁ ነው።'),
  ('a745a528-a79e-59d4-a8a4-9dcf6d99efef', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 23, 30, 'ነገር ግን መጽሐፍ ምን ይላል? “የባሪያዪቱ ልጅ ከእመቤቲቱ ልጅ ጋር አይወርስምና ባሪያዪቱን ከልጅዋ ጋር አስወጥተህ ስደዳት”'),
  ('81c2a915-c4eb-59bf-a294-a36401234c9f', '1903b331-dfe1-5a38-aadc-1b2d9beab496', '1af7d6a3-186d-5abc-a016-03fd99150e2b', 24, 31, 'ወንድሞቻችን ሆይ፥ አሁንም እኛ የእመቤቲቱ ነን እንጂ የባሪያዪቱ ልጆች አይደለንም፤ ክርስቶስ ነጻ አውጥቶናልና።'),
  ('6f423177-6a11-5172-aeea-c8f607e8d572', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 1, 1, 'እንግዲህ ጸንታችሁ ቁሙ፤ እንደ ገናም በባርነት ቀንበር አትኑሩ።'),
  ('0e18fa29-a7ed-5610-ad81-2dbde1b00686', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 2, 2, 'እነሆ፥ እኔ ጳውሎስ እላችኋለሁ፤ “ብትገዘሩም በክርስቶስ ዘንድ ምንም አይጠቅማችሁም።”'),
  ('4557ba04-cefb-56bb-a3c3-6958f654012e', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 3, 3, 'ደግሞም ለተገዘረ ሰው ሁሉ የኦሪትን ሕግ መፈጸም እንደሚገባው እመሰክራለሁ።'),
  ('dd446858-b314-5c50-aad7-93b3f7cc0c56', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 4, 4, 'በኦሪት ልትጸድቁ የምትፈልጉ እናንተ ከክርስቶስ ተለይታችሁ ከጸጋዉ ወድቃችኋል።'),
  ('d791f058-ed22-508f-a39c-781de49551ce', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 5, 5, 'እኛ ግን በመንፈስ ቅዱስ፥ በእምነትም ልንጸድቅ ተስፋ እናደርጋለን።'),
  ('e0d45d7c-9c25-5561-a617-07249800b845', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 6, 6, 'በጌታችን በኢየሱስ ክርስቶስ ዘንድ በፍቅር የምትሠራ እምነት እንጂ መገዘር አይጠቅምምና፤ አለመገዘርም ግዳጅ አይፈጽምምና።'),
  ('7f6c4d13-0b37-52ee-a4a0-9d3a3ef0abbc', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 7, 7, 'ቀድሞስ በመልካም ተፋጥናችሁ ነበር፤ በእውነት እንዳታምኑ ማን አሰናከላችሁ?'),
  ('8ea3bcd4-7cf5-5ebb-a82e-7b6814d641b5', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 8, 8, 'ይህ መፋጠናችሁ ከሚጠራችሁ አይደለምና።'),
  ('46fc236f-f93d-5e22-a714-f885dd3e03fd', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 9, 9, 'ጥቂት እርሾ ብዙውን ዱቄት መጻጻ ያደርገው የለምን?'),
  ('7262a230-c879-53ca-aaee-300c85c75cef', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 10, 10, 'እኔ ሌላ እንዳታስቡ በጌታችን በኢየሱስ ክርስቶስ አምኛችሁ ነበር፤ የሚያውካችሁ ግን የሆነው ቢሆን ፍዳውን ይሸከማል።'),
  ('73964278-1085-5882-a7a2-a2376f33660a', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 11, 11, 'ወንድሞች ሆይ፥ እኔ ግዝረትን ገና የምሰብክ ከሆነ፥ እንግዲህ ለምን ያሳድዱኛል? እንግዲህ የክርስቶስ የመስቀሉ ተግዳሮት እንዲያው ቀርቶአል።'),
  ('03b8c775-b21f-5deb-ae6a-1795cdf43e3a', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'd032681f-906b-51f5-a017-8b02aeec1a06', 12, 12, 'የሚያውኩአችሁም ሊለዩ ይገባል።'),
  ('c4817e2a-d170-5cc7-a37c-295fe2185169', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 1, 13, 'ወንድሞች ሆይ፥ እናንተስ ለነጻነት ተጠርታችኋል፤ ነገር ግን በሥጋችሁ ፈቃድ ለነጻነታችሁ ምክንያት አታድርጉላት፤ ለወንድሞቻችሁም በፍቅር ተገዙ።'),
  ('5704fad8-c521-5f34-a9c4-b5d504835d08', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 2, 14, '“ወንድምህን እንደ ራስህ ውደድ” የሚለው አንድ ቃል ሕግን ሁሉ ይፈጽማልና።'),
  ('0a5831e6-1747-51db-a817-49f0eeba9d65', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 3, 15, 'እርስ በርሳችሁ የምትበላሉና የምትነካከሱ ከሆነ ግን፥ እርስ በርሳችሁ እንዳትተላለቁ ተጠንቀቁ።'),
  ('19f9ed3d-c68c-5b83-a13a-9a37938c238c', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 4, 16, 'እላችኋለሁ፤ በመንፈስ ኑሩ እንጂ የሥጋችሁን ፈቃድ አታድርጉ።'),
  ('dab65ff7-a17b-5260-a517-a74dd9f8b352', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 5, 17, 'ሥጋ መንፈስ የማይሻውን ይሻልና፥ መንፈስም ሥጋ የማይሻውን ይሻልና፥ የምትሹትንም እንዳታደርጉ እርስ በርሳቸው ይጣላሉ።'),
  ('fa21891a-0383-5a52-a67f-61471e2b3e98', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 6, 18, 'የመንፈስን ፈቃድ የምትከተሉ ከሆናችሁ፥ ከኦሪት ወጥታችኋል።'),
  ('a4919299-0097-5802-aa05-9111e448d254', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 7, 19, 'የሥጋም ሥራው ይታወቃል፤ እርሱም ዝሙት፥ ርኵሰት፥ መዳራት፥'),
  ('a586a5e6-9486-5edc-af57-9675aa4a1b5e', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 8, 20, 'ጣዖት ማምለክ፥ ሥራይ ማድረግ፥ መጣላት፥ ኵራት፥ የምንዝር ጌጥ፥ ቅናት፥ ቍጣ፥ ጥርጥር፥ ፉክክር፥ ምቀኝነት፥ መጋደል፥ ስካር ይህንም የመሰለ ሁሉ ነው።'),
  ('5ab42e60-09f6-521d-af3a-be1c0c521459', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 9, 21, 'አስቀድሜ እንደ ነገርኋችሁ ይህን የሚያደርግ የእግዚአብሔርን መንግሥት አያይም።'),
  ('f95cb8ad-c519-574b-aca7-be6ca1d1e8f0', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 10, 22, 'የመንፈስ ፍሬ ግን ፍቅር፥ ደስታ፥ ሰላም፥ ትዕግሥት፥ ምጽዋት፥ ቸርነት፥ እምነት፥ ገርነት፥ ንጽሕና ነው።'),
  ('1ffcf801-5100-5c82-af34-b7e7a96f40d1', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 11, 23, 'ከዚህ ሕግ የሚበልጥ የለም።'),
  ('1419da9c-cbe3-5e38-a89e-6a7fbb58bcb6', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 12, 24, 'በኢየሱስ ክርስቶስ ያመኑ ግን ሰውነታቸውን ከምኞትና ከኀጢአት ለዩ።'),
  ('517f7dc8-2431-5ec9-a38b-4a6efe693dcb', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 13, 25, 'አሁንም በመንፈስ እንኑር፤ በመንፈስም እንመላለስ።'),
  ('288f0c2b-8018-5209-a229-4cc4bef9c448', '4bdd9607-7c72-5b00-aa86-dff4cbde544f', 'c91e1b74-7428-5778-a642-566ffdc32c52', 14, 26, 'ኩሩዎች አንሁን፤ እርስ በርሳችን አንተማማ፤ እርስ በርሳችንም አንቀናና።'),
  ('6d4fddcf-29ed-58c3-a9e5-89e44dbf75b5', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 1, 1, 'ወንድሞቻችን ሆይ፥ ከእናንተ ወገን የተሳሳተ ሰው ቢኖር በመንፈስ ቅዱስ የጸናችሁ እናንት እንዳትሳሳቱ ለራሳችሁ እየተጠበቃችሁ፥ እንደዚህ ያለውን ሰው ቅንነት ባለው ልቡና አጽኑት።'),
  ('75d1c2a2-9b9f-53ed-aed2-753dbb6456ae', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 2, 2, 'ከእናንተ እያንዳንዱ የባልንጀራውን ሸክም ይሸከም፤ በዚህም የክርስቶስን ሕግ ትፈጽማላችሁ።'),
  ('5561fbb5-061d-53d5-a74f-bfca88b34835', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 3, 3, 'አንዱም ምንም ሳይሆን ምንም የሆነ ቢመስለው ራሱን ያታልላልና።'),
  ('7f7ef4c8-e0a7-5017-a724-25e570749736', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 4, 4, 'ለሌላ ያይደለ ለራሱ መመኪያ እንዲሆነው ሁሉም ሥራዉን ይመርምር።'),
  ('dd78ce5c-aad1-5d3b-a5af-6ac6c7cd9380', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 5, 5, 'ሁሉም ሸክሙን ይሸከማልና።'),
  ('a30c8366-ed25-510d-ac52-b2792332718a', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 6, 6, 'ይህንም ነገር ንኡሰ ክርስቲያን ይስማው፤ መልካሙንም ነገር ሁሉ ከሚያስተምረው ይማር።'),
  ('72c39c83-ec48-59a4-ab37-d4fdf71422e6', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 7, 7, 'አያስቱአችሁ፤ በእግዚአብሔርም የሚዘብት አይኑር፤ ሰውም የሚዘራውን ያጭዳል።'),
  ('790632a1-af24-5d76-ad0d-32b2d356a8c8', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 8, 8, 'በሥጋው የሚዘራ ሞትን ያጭዳል፤ በመንፈሱም የሚዘራ የዘለዓለም ሕይወትን ያጭዳል።'),
  ('fde14699-3c23-5d63-a1e1-84e66d106976', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 9, 9, 'በጎ ሥራ መሥራትን ቸል አንበል፥ በጊዜው እናገኘዋለንና።'),
  ('c4201a62-49ea-567a-a367-c691ca8e362b', 'a035d3a1-0642-5db5-a27e-b25875a64672', '1f789312-7dea-5b56-a2f7-43bbc00d8936', 10, 10, 'እንግዲህ ጊዜ ሳለን ለሁሉ መልካም ሥራ እናድርግ፤ ይልቁንም ለሃይማኖት ሰዎች።'),
  ('a8f085f1-f6fa-5778-a6ca-528e13fed42b', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 1, 11, 'በእጄ እንደ ጻፍሁላችሁ እዩ።'),
  ('62411817-ac4c-51b0-ade6-254e99341fd0', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 2, 12, 'ለሰው ፊት ሊያደሉ የሚወዱ እነዚያ እንድትገዘሩ ያስገድዱአችኋል፤ ነገር ግን የክርስቶስን መስቀል እንዳትከተሉ ነው።'),
  ('d24c5e10-eda4-5110-affc-58bda854745d', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 3, 13, 'የተገዘሩትም ቢሆኑ በሰውነታችሁ እንደምትመኩ ልትገዘሩ ይወዳሉ እንጂ ኦሪትን አልጠበቁም።'),
  ('b4407712-e328-5c6d-afe4-441cb111d7dc', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 4, 14, 'እኔ ግን በጌታችን በኢየሱስ ክርስቶስ መስቀል እንጂ በሌላ አልመካም፤ በእኔ ዘንድ ዓለሙ የሞተ ነው፥ እኔም በዓለሙ ዘንድ የሞትሁ ነኝ።'),
  ('914c0dee-00ef-5f08-a114-800160e187ad', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 5, 15, 'በኢየሱስ ክርስቶስ ዘንድ አዲስ ፍጥረት መሆን ነው እንጂ መገዘር አይጠቅምም፤ አለመገዘርም ግዳጅ አይፈጽምም።'),
  ('89504b85-49eb-5207-a2d3-747470e3fde6', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 6, 16, 'ይህን ሕግ ለሚፈጽሙ ሰዎች ሰላምና ይቅርታ ይሁን፤ የእግዚአብሔር ወገኖች በሆኑ በእስራኤል ላይም ይሁን።'),
  ('0de1246c-c686-5313-a332-0c86e23046f1', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 7, 17, 'እንግዲህ ወዲህስ የሚያደክመኝ አይኑር፤ እኔ የኢየሱስ ክርስቶስን መከራ በሥጋዬ እሸከማለሁ።'),
  ('66555dcb-551b-5e82-af62-960cbdab65b3', 'a035d3a1-0642-5db5-a27e-b25875a64672', '88d7ed3c-099a-58fa-aa71-5611be081d83', 8, 18, 'ወንድሞች ሆይ፥ የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከእናንተ ጋር ይሁን፤ አሜን።'),
  ('10847bf9-ac64-57c5-a358-d91bc8660c5d', '572b93b2-6d80-5feb-a6e6-736de45dad95', '4d5d9e08-e0ff-510f-ad1e-122bfe6935ed', 1, 1, 'በእግዚአብሔር ፈቃድ የጌታችን የኢየሱስ ክርስቶስ ሐዋርያ ከሆነ ከጳውሎስ በኢየሱስ ክርስቶስ ላመኑ በኤፌሶን ላሉ ቅዱሳን፥'),
  ('e61cc18d-98d2-5cde-a9d1-b7526b2e396c', '572b93b2-6d80-5feb-a6e6-736de45dad95', '4d5d9e08-e0ff-510f-ad1e-122bfe6935ed', 2, 2, 'ከአባታችን ከእግዚአብሔር፥ ከጌታችን ከኢየሱስ ክርስቶስም ሰላምና ጸጋ ለእናንተ ይሁን።'),
  ('e4a2cf7c-d428-532d-a992-9fdd0822c534', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 1, 3, 'በክርስቶስ ኢየሱስ በሰማያዊ ስፍራ በመንፈሳዊ በረከት ሁሉ የባረከን የጌታችን የኢየሱስ ክርስቶስ አባት እግዚአብሔር ይመስገን።'),
  ('f60330c9-49ee-5267-ac56-0142237d8b59', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 2, 4, 'ዓለም ሳይፈጠር በፊቱ ቅዱሳን፥ ንጹሓንና ያለ ነውር በፍቅር ያደርገን ዘንድ ለእርሱ መረጠን።'),
  ('95992280-c2ff-5281-a01a-da481e102afe', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 3, 5, 'በኢየሱስ ክርስቶስም እንደ ውድ ፈቃዱ ለእርሱ ልጆች ልንሆን አስቀድሞ ወሰነን።'),
  ('3de5039e-efb3-511c-a0c9-9f2406530545', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 4, 6, 'በሚወደው ልጁ የሰጠን የጸጋው ክብር ይመሰገን ዘንድ።'),
  ('8c3a6fcd-821e-5aa3-a9f9-6542f275f41c', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 5, 7, 'በእርሱም እንደ ቸርነቱ ብዛት በደሙ ድኅነትን አገኘን፤ ኀጢአታችንም ተሰረየልን።'),
  ('be80a7be-9cc3-5e63-a606-b44ba60888a2', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 6, 8, 'ይኸውም በፍጹም ጥበብና ምክር ለእኛ አብዝቶ ያደረገው ነው።'),
  ('b8a1e8df-c092-5afa-a820-b34a5c8b737c', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 7, 9, 'እንደ ወደደም በእርሱ የወሰነውን፥ የፈቃዱን ምሥጢር ገለጠልን።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ee8cc401-7a72-5d25-a242-88252963da05', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 8, 10, 'የሚደርስበትንም ጊዜውን ወሰነ፤ በሰማይና በምድር ያለውም ሁሉ ይታደስ ዘንድ ክርስቶስን በሁሉ ላይ አላቀው።'),
  ('629ba8a9-a626-5d4b-a95d-c54082956ea2', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 9, 11, 'እንደ ፈቃዱ ምክር ሁሉን የሚሠራ እንደ እርሱ አሳብ አስቀድመን የተወሰን በእርሱ ርስትን ተቀበልን።'),
  ('2a80c767-d88f-537c-a6a5-0859438e0ee4', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 10, 12, 'ይኸውም አስቀድመን በክርስቶስ ኢየሱስ ተስፋ ያደረግን እኛ ለክብሩ ምስጋና እንሆን ዘንድ ነው።'),
  ('484a9713-c40c-5fe7-ae89-ea1bb5cd8db4', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 11, 13, 'እናንተም ልትድኑበት የተማራችሁትን የእውነት ቃል ሰምታችሁና አምናችሁ፤ ተስፋ ባደረገላችሁ በመንፈስ ቅዱስ ታተማችሁ።'),
  ('b16956ed-f8f4-577a-a91e-bafb53ed5890', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'a9650856-0735-58ab-a1f3-11c913bb33b0', 12, 14, 'ይኸውም ለጌትነቱ ክብር የርስታችን መያዣ፥ የሕይወታችንም ቤዛነት ነው።'),
  ('eca96348-d753-588f-a640-59796565c7c6', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 1, 15, 'ስለዚህም እኔ በጌታችን በኢየሱስ ክርስቶስ ማመናችሁን፥ ቅዱሳንንም ሁሉ መውደዳችሁን ሰምቼ፥'),
  ('246d7e5b-191c-57fa-a227-204842674de6', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 2, 16, 'ስለ እናንተ እግዚአብሔርን ማመስገንንና በጸሎቴም እናንተን ማሰብን አላቋረጥሁም።'),
  ('88fd0316-ec2f-5afd-a499-10322b3f90e5', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 3, 17, 'ይኸውም የክብር ባለቤት የጌታችን የኢየሱስ ክርስቶስ አባቱ እግዚአብሔር የጥበብን መንፈስ ይሰጣችሁ ዘንድ፥ ዕውቀቱንም ይገልጽላችሁ ዘንድ፥'),
  ('d72540eb-0152-578f-a797-2a1f98b2323a', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 4, 18, 'ዐይነ ልቡናችሁንም ያበራላችሁ ዘንድ፥ የተጠራችሁበት ተስፋም ምን እንደ ሆነ፥ በቅዱሳንም የርስቱ ክብር ባለጸግነት ምን እንደ ሆነ ታውቁ ዘንድ፥'),
  ('167878b7-3bbf-5266-a7b2-6b56b7dace81', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 5, 19, 'በክርስቶስ እንደ አደረገው እንደ ከሃሊነቱ ታላቅነት በምናምን በእኛ ላይ የሚያደርገው የከሃሊነቱ ጽናት ብዛት ምን እንደ ሆነ ታውቁ ዘንድ ነው።'),
  ('40c8ff6c-7d87-58e8-a4b9-72e7a2424126', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 6, 20, 'ከሙታን ለይቶ ባስነሣው፥ በሰማይም በቀኙ ባስቀመጠው፥'),
  ('52d29259-356c-5a39-a153-bff5ebfe7e3f', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 7, 21, 'ከመላእክት ሁሉ በላይ ከመኳንንትና ከኀይላት፥ ከአጋእዝትና ከሚጠራውም ስም ሁሉ በላይ፥ በዚህ ዓለም ብቻ አይደለም፤ በሚመጣውም ዓለም እንጂ።'),
  ('91d5b6ab-c518-59b4-a18a-2ab2d3fd737c', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 8, 22, 'ሁሉንም ከእግሩ በታች አድርጎ አስገዛለት፤ ከሁሉ በላይ የሆነ እርሱን ለቤተ ክርስቲያን ራስ አደረገው።'),
  ('58026bdc-141d-5b99-a7fb-cb36e0795e6a', '572b93b2-6d80-5feb-a6e6-736de45dad95', 'b754c4f4-f0f0-5a6f-a474-a6b2e8f233e4', 9, 23, 'ይህችውም አካሉ ናት፤ የሁሉም ፍጻሜው እርሱ ነው፤ ሁሉንም በሁሉ ይፈጽማል።'),
  ('0722a017-a2da-5b00-ac77-db354d9a551f', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 1, 1, 'እናንተም በኀጢአታችሁ ምውታን ሆናችሁ ነበር።'),
  ('1678b9ff-70e6-59eb-a1c2-ee99eb9d8697', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 2, 2, 'ይኸውም ቀድሞ በዚህ ዓለም ሥርዐት፥ አሁን በከሓድያን ልጆች የሚበረታታባቸውና፥ በነፋስ አምሳል የሚገዛቸው አለቃ እንደ ነበረው ፈቃድ ጸንታችሁ የነበራችሁበት ነው።'),
  ('c624a9e2-0ff0-5d59-ac4a-bbc322a56ca3', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 3, 3, 'እኛ ሁላችን ቀድሞ እንደ ሥጋችን ምኞት ኖርን፤ የሥጋችንንም ፈቃድና ያሰብነውን አደረግን፤ እንደ ሌሎች ኃጥአንም ሁሉ የጥፋት ልጆች ሆንን።'),
  ('bbdf5fa4-567b-521d-a9e7-4ea034112e99', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 4, 4, 'እግዚአብሔር ግን በምሕረቱ ባለጸግነትና በወደደን በፍቅሩ ብዛት፥'),
  ('c54ce5ef-87f9-5485-a9da-79cbda3d05bb', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 5, 5, 'በኃጢአታችን የሞትን ሳለን በክርስቶስ ሕይወትን ሰጠን፤ በጸጋውም ዳንን።'),
  ('3ccb9b6f-92bb-5fe3-a2f7-28ad95e4e045', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 6, 6, 'በኢየሱስ ክርስቶስም አስነሥቶ በሰማያት ከእርሱ ጋር አኖረን።'),
  ('5f74876f-ff84-598b-a829-5b033a6f3406', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 7, 7, 'በኢየሱስ ክርስቶስ ይቅር ስላለን የጸጋውን ባለጠግነት ብዛት በሚመጣው ዓለም ይገልጥ ዘንድ፥'),
  ('0b58b165-b61d-50fd-ad18-e5047aa161bf', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 8, 8, 'አምነን በጸጋው ድነናልና፤ ይህም የእግዚአብሔር ጸጋ ነው እንጂ የእናንተ ሥራ አይደለም።'),
  ('2d03e7ac-2d64-5bc9-a81f-de2c9879b090', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 9, 9, 'የሚመካም እንዳይኖር በምግባራችን አይደለም።'),
  ('ee5d11dc-610d-54b7-abff-78de326a7fa0', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', 'c0eb3903-7991-5d24-a019-f0d222863175', 10, 10, 'እንመላለስበት ዘንድ እግዚአብሔር አስቀድሞ ላዘጋጀው በጎ ሥራ በኢየሱስ ክርስቶስ የፈጠረን ፍጥረቱ ነንና።'),
  ('11a441a7-cdf3-5d7d-a4bd-18cd9a235126', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 1, 11, 'እናንተ አሕዛብ አስቡ፤ ቀድሞ በሥጋ ሥርዐት ነበራችሁ፤ ያልተገዘሩም ይሉአችሁ ነበር፤ እንዲህ የሚሉአችሁም የተገዘሩ ሰዎች ናቸው፤ ግዝረት ግን በሥጋ ላይ የሚደረግ የሰው እጅ ሥራ ነው።'),
  ('42aa3c6b-c9b8-5326-ab0d-aef31526ecea', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 2, 12, 'ያንጊዜ ክርስቶስን አታውቁትም ነበር፤ ከእስራኤል ሕግ የተለያችሁ ነበራችሁ፤ ከተስፋው ሥርዐትም እንግዶች ነበራችሁ፤ ተስፋም አልነበራችሁም፤ በዚህም ዓለም እግዚአብሔርን አታውቁትም ነበር።'),
  ('1b6888ec-b3e8-5719-a7f7-a2100daada65', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 3, 13, 'አሁን ግን ቀድሞ ርቃችሁ የነበራችሁ እናንተ በኢየሱስ ክርስቶስ ሆናችሁ በክርስቶስ ደም ቀረባችሁ።'),
  ('f82e21c4-9f6f-583d-aa31-15aff5e8360e', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 4, 14, 'ሁለቱን አንድ ያደረገ ሰላማችን እርሱ ነውና፥ በሥጋውም በመካከል የነበረውን የጥል ግድግዳ አፍርሶ ጥልን ሻረ።'),
  ('57739799-a83d-56b7-a070-ae44799812e1', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 5, 15, 'ሁለቱንም አድሶ አንድ ያደርጋቸው ዘንድ በሥርዐቱ የትእዛዝን ሕግ አጠፋ፤ ዕርቅንም አደረገ።'),
  ('cd4ea31b-bab2-5d8e-a9f9-c2138b8275a1', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 6, 16, 'በመስቀሉም በአንድ ሥጋው ሁለቱን ወደ እግዚአብሔር አቀረባቸው፤ በእርሱም ጥልን አጠፋ።'),
  ('45c4b99c-b4a7-5a8d-afb6-5106e2f47446', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 7, 17, 'መጥቶም፤ ቀርበን ለነበርነው ሰላምን፥ ርቃችሁ ለነበራችሁት ለእናንተም ሰላምን ሰጠን።'),
  ('55148e34-c4f4-5c99-a3c6-479549660540', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 8, 18, 'እርሱ መርቶናልና፤ ሁለታችንንም በመንፈስ ቅዱስ ወደ አባቱ አቅርቦናልና።'),
  ('aafcd99e-e6f0-5a17-a761-4fc04eaec253', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 9, 19, 'እንግዲህስ ወዲህ እናንተ ከቅዱሳን ጋር ባላገሮችና የእግዚአብሔር ቤተ ሰቦች እንጂ እንግዶችና መጻተኞች አይደላችሁም።'),
  ('0cc7b5b7-b8d4-5a06-a786-1d11f84fa82d', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 10, 20, 'በነቢያትና በሐዋርያት መሠረት ላይ ታንጻችኋልና የሕንጻው የማዕዘን ራስ ድንጋይም ኢየሱስ ክርስቶስ ነው፤'),
  ('99a5efda-3518-578b-adbc-02f163786c3d', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 11, 21, 'እርሱም ሕንጻ ሁሉ የሚያያዝበት፥ የእግዚአብሔርም ቤተ መቅደስ ግንብ የሚያድግበት ነው።'),
  ('4d5e2d4d-fccc-5110-a83f-a83f112bd271', 'f4af7eb7-f4d4-5f57-a481-9dd8a7e92cbe', '35e93396-6eaa-5fdc-afcb-b0dd696ec382', 12, 22, 'እናንተ በመንፈስ ቅዱስ የእግዚአብሔር ማደሪያ ልትሆኑ በእርሱ ታነጻችሁ።'),
  ('861a910f-d693-5db5-a98c-739082cd3c3c', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 1, 1, 'ስለዚህ አሕዛብ ሆይ ስለ እናንተ እኔ ጳውሎስ የክርስቶስ እስረኛው ነኝ።'),
  ('9d4fc819-90d1-505d-a2b7-9e60b4fb2589', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 2, 2, 'ስለ እናንተ የሰጠኝን የእግዚአብሔርን የጸጋውን ስጦታ ሰምታችኋል።'),
  ('ab45f7ea-0fa9-5495-a4ea-d33f7c9fb81f', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 3, 3, 'አስቀድሞ በጥቂቱ እንደ ጻፍሁላችሁ ይህን ምሥጢር ገልጦ አሳይቶኛልና።'),
  ('06af2c4d-4963-543a-ac09-dd1d4d494b38', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 4, 4, 'ይህንም በምታነቡበት ጊዜ፥ የክርስቶስን ምሥጢር ማስተዋሌን ለማወቅ ትችላላችሁ።'),
  ('1d96f3b3-657e-56eb-a9e2-6d565a9c44a3', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 5, 5, 'በሌላ ዘመን ለሰው ልጆች ያልተገለጠ ዛሬ ለቅዱሳን ሐዋርያቱና ለነቢያቱ በመንፈስ ቅዱስ እንደ ተገለጠ፥'),
  ('56ade6c0-bcb9-5b93-af0e-c78b8e31506e', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 6, 6, 'አሕዛብን ወራሾቹና አካሉ ያደርጋቸው ዘንድ፥ በወንጌልም ትምህርት በኢየሱስ ክርስቶስ በሆነው ተስፋ አንድ ይሆኑ ዘንድ።'),
  ('7c522a95-f5d0-54e8-ae18-3ab733168755', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 7, 7, 'በኀይሉ አጋዥነት እንደ ሰጠኝ እንደ ጸጋው ስጦታ መጠን እኔ መልእክተኛና አዋጅ ነጋሪ የሆንሁለት፥'),
  ('eebdc869-9207-5d1a-a6fa-5bdd8832fce8', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 8, 8, 'ከቅዱሳን ሁሉ ለማንስ ለእኔ የማይመረመረውን የክርስቶስን ባለጸግነት ለአሕዛብ አስተምር ዘንድ ይህን ጸጋ ሰጠኝ።'),
  ('497ab407-89b3-5de6-aceb-121ca01ae4f9', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 9, 9, 'ሁሉን በፈጠረ በእግዚአብሔር ከዘለዓለም የተሰወረ የዚህ ምሥጢር ሥርዐትንም ለሁሉ እገልጥ ዘንድ፤'),
  ('19a8c4be-dac1-521a-af10-bad6eb35e706', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 10, 10, 'ብዙ ልዩ ልዩ የሆነች የእግዚአብሔር ጥበብ አሁን በቤተ ክርስቲያን በኩል በሰማያዊ ስፍራ ውስጥ ላሉት አለቆችና ሥልጣናት ትታወቅ ዘንድ፤'),
  ('55bbb427-f6f4-5422-a611-b5497dced4fe', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 11, 11, 'ዓለም ሳይፈጠር የወሰናት፥ በጌታችን በኢየሱስ ክርስቶስም የፈጸማት፥'),
  ('43c3ef15-87cc-57c2-a2a8-eea5b7f51a1e', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 12, 12, 'እኛ ጸጋንና ባለሟልነትን ያገኘንበት፥ በሃይማኖት ወደሚገኘው ተስፋም ያደረሰበት፤'),
  ('621ff89f-2e4c-55d9-a75f-251e3c85da00', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', 'de8c583a-6635-5f90-aa70-8618c3f1cb03', 13, 13, 'ስለዚህም ስለ እናንተ ለክብራችሁ የምታገኘኝን መከራዬን ቸል እንዳይላት እግዚአብሔርን እማልደዋለሁ።'),
  ('e12796dd-5966-501c-a2de-1f10b2dcd328', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 1, 14, 'ስለዚህም በልቡናዬ ተንበርክኬ ለአብ እሰግዳለሁ።'),
  ('836143e0-acbe-5148-aa07-993c6224de64', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 2, 15, 'በሰማይና በምድር ያሉ ነገዶች ሁሉ ለሚጠሩት ለእርሱ፤'),
  ('1d3bf2f9-2693-5c54-a949-797027b699bc', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 3, 16, 'እንደ ጌትነቱ ምላት ይሰጣችሁ ዘንድ፥ በመንፈስ ቅዱስም ኀይል ያጸናችሁ ዘንድ።'),
  ('b3865219-f051-5c85-ab88-104d53a5ee2d', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 4, 17, 'በልባችሁ ውስጥ በፍቅር ሥር መሠረታችሁ የጸና ሲሆን ክርስቶስ በሃይማኖት በሰው ውስጥ ያድራልና።'),
  ('f2620cc7-ad75-5fcf-a2e7-497718d60005', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 5, 18, 'ስፋቱና ርዝመቱ፥ ምጥቀቱና ጥልቀቱ ምን ያህል እንደ ሆነ ከቅዱሳን ሁሉ ጋር ለማስተዋል ትችሉ ዘንድ፥'),
  ('594a385e-2cb6-58c7-a1c2-046a0b9ca3b1', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 6, 19, 'የክርስቶስን ፍቅር ለመረዳት፥ በእግዚአብሔር ፍጹምነት በሁሉ ፍጹማን ትሆኑ ዘንድ።'),
  ('1c661dec-5617-50f4-a81c-35aa2eb2517e', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 7, 20, 'በከሃሊነቱ እንደ ረዳን መጠን፥ የምናስበውንና የምንለምነውን ሁሉ ትሠሩ ዘንድ፥ ታበዙም ዘንድ ሊያጸናችሁ ለሚችል፥'),
  ('80944725-9e31-5044-a381-66804be56325', 'bf2faf38-f18e-563f-a781-a4ea4d21cd2e', '01b1fe25-0761-5e24-a036-0e3da4f4efe5', 8, 21, 'ለእርሱ በቤተ ክርስቲያን በኢየሱስ ክርስቶስ፥ በትውልድ ሁሉ ምስጋና ይሁን ለዘለዓለሙ አሜን።'),
  ('52140bb0-fc4c-53c5-a5be-0cb318baa66e', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 1, 1, 'ወንድሞቻችን ሆይ፥ ለተጠራሁላት አጠራር በሚገባ ትኖሩ ዘንድ በክርስቶስ እስረኛ የሆንሁ እኔ ጳውሎስ እማልዳችኋለሁ።'),
  ('9b46d7d4-606d-52c1-a900-dc7b3a691324', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 2, 2, 'በፍጹም የዋህነት ራሳችሁን ዝቅ አድርጋችሁ እየታገሣችሁ፥ ለወንድሞቻችሁም እሺ እያላችሁ፥ በፍቅር እየተጋችሁና እየተባበራችሁ፥'),
  ('c932b02d-8ae3-5d6b-a68f-27f19cb215ba', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 3, 3, 'በአንድ መንፈስና በሰላም ማሰሪያነት እየተጠበቃችሁ፥'),
  ('6dbd37c6-4a60-57ac-a875-f62565112597', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 4, 4, 'ለአንዱ ተስፋችሁ እንደ መጠራታችሁ መጠን፥ አንድ አካልና አንድ መንፈስ ትሆኑ ዘንድ እማልዳችኋለሁ።'),
  ('3b9d5829-bada-5233-aea6-188c79bb6cf2', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 5, 5, 'ጌታ አንድ ነው፤ ሃይማኖትም አንዲት ናት፤ ጥምቀትም አንዲት ናት።'),
  ('8495ebc7-07e9-50ed-a991-a213268b16cb', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 6, 6, 'በሁሉ ሙሉ የሚሆን ሁሉም ከእርሱ የተገኘ ከሁሉም በላይ ያለ የሁሉ አባት እግዚአብሔር አንድ ነው።'),
  ('5dddc609-7c67-5250-a5f7-bf5571469633', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 7, 7, 'ከእኛ ለእያንዳንዱ በክርስቶስ ስጦታ መጠን ጸጋው ተሰጥቶናል።'),
  ('6b3ab5a8-2666-5603-ac36-bb00c499c49c', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 8, 8, '“ምርኮን ማርከህ ወደ ሰማይ ወጣህ፤ ጸጋህንም ለሰው ልጅ ሰጠህ” ይላልና።'),
  ('41bdab8d-5c1b-5ed7-ab7c-9c450ab12fad', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 9, 9, 'ከምድር በታች ካልወረደ መውጣቱ ምንድን ነው?'),
  ('0e8db1c3-2689-5df0-a1b9-6360f5e046d5', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 10, 10, 'የወረደው እርሱ ነው፤ ሁሉንም ይመላ ዘንድ ከሰማያት ሁሉ በላይ የወጣው ደግሞ እርሱ ነው።'),
  ('0ac5ae64-db62-575c-a1fd-07a1718c2097', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 11, 11, 'እርሱም ጸጋን ሰጠ፤ ከቤተ ሰቦቹም ሐዋርያትን፥ ከእነርሱም ነቢያትንና የወንጌል ሰባኪዎችን፥ ጠባቂዎችንና መምህራንን ሾመ።'),
  ('82793557-ec31-5495-a044-e357d47fb7dc', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 12, 12, 'ቅዱሳን ለአገልግሎቱ ሥራና ለክርስቶስ አካል ሕንጻ እንዲጸኑ፤'),
  ('89b361af-6334-5c37-af12-883114ed69b8', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 13, 13, 'ሁላችን የእግዚአብሔርን ልጅ በማመንና በማወቅ አንድ እስክንሆን ድረስ በክርስቶስ ምልዐት መጠን፥ አካለ መጠን እንደ አደረሰ እንደ አንድ ሙሉ ሰው እስክንሆን ድረስ፥'),
  ('2c922d54-035c-5615-ac1e-e7d8c367ce8b', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 14, 14, 'እንግዲህ በሽንገላቸው ያስቱ ዘንድ በሚተናኰሉ ሰዎች ተንኰል ምክንያት በትምህርት ነፋስ ሁሉ ወዲያና ወዲህ እየተፍገመገምንና እየተንሳፈፍን ሕፃናት አንሁን።'),
  ('b432bc82-3794-5b9d-aed1-be4a9a236480', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 15, 15, 'ነገር ግን በፍቅር እውነተኞች እንሆን ዘንድ ራስ ወደ ሆነው ወደ እርሱ ወደ ክርስቶስ እንደግ።'),
  ('e68c638a-5cea-52b4-acf0-bfbbc07a3ba1', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'f5563b99-2075-56da-a676-d71d15ef7ea6', 16, 16, 'ከእርሱ የተነሣ አካል ሁሉ እያንዳንዱ ክፍል በልክ እንደሚሠራ፥ በተሰጠው በሥር ሁሉ እየተጋጠመና እየተያያዘ፥ ራሱን በፍቅር ለማነጽ አካሉን ያሳድጋል።'),
  ('433ddb78-1058-5179-acec-39fdb69a089f', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 1, 17, 'እንግዲህ በልባቸው ከንቱ አሳብ እንደሚኖሩ እንደ አሕዛብ እንዳትኖሩ ይህን እላለሁ፤ በእግዚአብሔርም እመሰክራለሁ።'),
  ('29afe38b-b90f-5400-a8b3-497748d1c855', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 2, 18, 'ልቡናቸው የተጨፈነ ነው፤ በስንፍናቸውና በድንቍርናቸው እግዚአብሔር ከሚሰጣቸው ሕይወት የተለዩ ናቸው።'),
  ('73a4171b-e6d2-592f-a7e5-23e3f1c5b52e', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 3, 19, 'ተስፋ የቈረጡ ናቸው፤ ራሳቸውንም ለጕስቍልና፥ ለርኵሰትና ለመዳራት አሳልፈው ሰጡ።'),
  ('8a3e45ad-73c1-533a-abe1-6710c2c15398', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 4, 20, 'እናንተ ግን ክርስቶስን የተማራችሁት እንደዚህ አይደለም።'),
  ('ed7c3d95-65c4-5f71-a034-1c2142b14f7f', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 5, 21, 'በርግጥ ከሰማችሁት፥ እውነት በኢየሱስ ክርስቶስ ነውና እውነትን በእርሱ ዘንድ ትማራላችሁ፤'),
  ('d3617873-9aa9-544a-aaa0-002243cfa754', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 6, 22, 'የቀድሞ ጠባያችሁን ከእናንተ አርቁ፤ ይህንም ስሕተት በሚያመጣው ምኞት ስለሚጠፋው ስለ አሮጌው ሰውነት እላለሁ።'),
  ('933ad5c3-a044-58ad-ade2-0c90eb83e232', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 7, 23, 'የልቡናችሁን ዕውቀት አድሱ።'),
  ('e44c3eee-8159-5f7e-a441-66ed807bbf13', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 8, 24, 'እግዚአብሔርም በእውነት፥ በቅንነትና በንጽሕና ያደሰውን አዲሱን ሰውነት ልበሱት።'),
  ('c6fd8d61-67c4-52ad-ad8e-b9e24d3e8b1f', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 9, 25, 'ስለዚህም ሐሰትን ተዉአት፤ ሁላችሁም ከወንድሞቻችሁ ጋር እውነትን ተነጋገሩ፤ እኛ አንድ አካል ነንና።'),
  ('88961d02-1b33-533e-a1ab-b054c429e9c1', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 10, 26, 'ተቈጡ፤ አትበድሉም፤ ፀሐይ ሳይጠልቅም ቍጣችሁን አብርዱ።'),
  ('8146f313-52b8-5ad4-a25e-e06b9b084fea', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 11, 27, 'ለሰይጣንም መንገድን አትስጡት።'),
  ('d4843792-8357-575e-a91f-b2c7d3879bcc', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 12, 28, 'የሚሰርቅም እንግዲህ አይስረቅ፤ ነገር ግን ድሃውን ይረዳ ዘንድ በእጆቹ መልካም እየሠራ ይድከም።'),
  ('df854957-ae40-558d-ad3c-5c05f2e0db71', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 13, 29, 'የሚሰሙአችሁ ሞገስን ያገኙ ዘንድ፥ ግዳጃችሁ እንዲፈጸም መልካም ነገር እንጂ ክፉ ነገር ሁሉ ከአፋችሁ አይውጣ።'),
  ('8c7001de-49f3-51af-a9ad-c6c5f22752d4', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 14, 30, 'በዳናችሁ ጊዜ የታተማችሁበትን የእግዚአብሔርን ቅዱስ መንፈስ አታሳዝኑት።'),
  ('e3a4ee25-29cb-52a3-aa92-c9147a5b45c6', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 15, 31, 'መራራነትንና ቍጣን፥ ብስጭትንና ርግማንን፥ ጥፋትንና ስድብን ሁሉ ከክፉ ነገር ሁሉ ጋር ከእናንተ አርቁ።'),
  ('d329b61f-5d73-5174-a8ae-773181c380d8', 'bdadd3a8-d1ef-5ea6-a6c9-6da49a6b63b7', 'a52e9e6b-4db0-5abe-a612-4e5df5745834', 16, 32, 'እርስ በርሳችሁም ቸሮችና ርኅሩኆች ሁኑ፤ እግዚአብሔርም በክርስቶስ ይቅር እንዳላችሁ ይቅር ተባባሉ።'),
  ('ad154823-b936-5ac2-affc-72694f0d2809', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 1, 1, 'እንግዲህ እንደ ተወደዱ ልጆች እግዚአብሔርን ምሰሉ።'),
  ('dad4c151-c56f-5a18-a4d6-2ca312ce56d5', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 2, 2, 'ክርስቶስ እንደ ወደዳችሁ፥ ራሱንም ለእግዚአብሔር በጎ መዓዛ የሚሆን መሥዋዕትና ቍርባን አድርጎ እንደ ሰጠላችሁ በፍቅር ተመላለሱ።'),
  ('ba1303cd-acdf-51d1-a60d-54dd59d36ef8', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 3, 3, 'ነገር ግን ለቅዱሳን እንደሚገባቸው፥ ዝሙትና ርኵሰት ሁሉ ወይም ቅሚያ አይሰማባችሁ።'),
  ('db06c4e0-4f2d-54c5-a91e-0d2204ea07ef', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 4, 4, 'የሚያሳፍር ነገርም፥ የስንፍና ነገርም፥ ወይም የማይገባ የዋዛ ነገር በእናንተ ዘንድ አይሁን፤ ማመስገን ይሁን እንጂ።'),
  ('55bb928a-48cb-5df5-a6a5-a15b9b286e38', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 5, 5, 'ሴሰኛ፥ ወይም ኀጢአተኛ፥ ወይም ቀማኛ፥ ወይም ጣዖትን የሚያመልክ ሁሉ በእግዚአብሔር ልጅ በክርስቶስ መንግሥት ዕድል ፋንታ እንደሌለው ይህን ዕወቁ።'),
  ('ae71b874-8ca3-5edc-a8b6-179b4caff078', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 6, 6, 'በከንቱ ነገርም የሚያስታችሁ አይኑር፤ በእርሱ ምክንያት በከሓዲዎች ልጆች ላይ የእግዚአብሔር መዓት ይመጣልና።'),
  ('eea251fa-8be7-56a4-ad2a-7824cd6b28d4', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 7, 7, 'እንግዲህ አትምሰሉአቸው።'),
  ('a504783e-aff0-5bd8-a716-80c5cf33a521', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 8, 8, 'ቀድሞ ጨለማ ነበራችሁና፥ ዛሬ ግን በጌታችን ብርሃን ሆናችኋል። እንግዲህስ እንደ ብርሃን ልጆች ተመላለሱ።'),
  ('01876ce6-db1d-50e9-a5af-f41eb02d83b1', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 9, 9, 'የብርሃን ፍሬው በጎ ሥራና እውነት፥ ቅንነትም ሁሉ ነውና።'),
  ('5f4cd2e3-e178-5bf2-acdc-1c227d5453ca', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 10, 10, 'እግዚአብሔርንም ደስ የሚያሰኘውን መርምሩ።'),
  ('700d5f79-66f3-5cab-a48f-67dcb1a04b2d', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 11, 11, 'የሥራ ፍሬ ከሌላቸው፥ ሁለንተናቸውም ጨለማ ከሆነ ሰዎች ጋር አትተባበሩ፤ ገሥጹአቸው እንጂ።'),
  ('65153bc0-c3a4-5e20-af58-9c635af3b4a7', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 12, 12, 'በስውር የሚሠሩት ሥራ ለመናገር የሚያሳፍር ነውና።'),
  ('e5db867d-5eb2-5e32-a000-ee8f6c845c20', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 13, 13, 'ነገር ግን በብርሃን የተገለጠ ሁሉ ይታወቃል፤ የሚታየው ሁሉ ብርሃን ነውና።'),
  ('6fc36237-9eca-5d2c-ab5f-7154376d6032', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 14, 14, '“የተኛህ ንቃ ከሙታንም ተለይተህ ተነሥ፤ ክርስቶስም ያበራልሃል” ብሎአልና።'),
  ('e789f257-b319-59dc-a98c-2c9b9b0c6660', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 15, 15, 'እንግዲህ እንደ ዐዋቂዎች እንጂ እንደ አላዋቂዎች ሳይሆን እንዴት እንደምትመላለሱ በጥንቃቄ ዕወቁ።'),
  ('f67ffe8b-672e-53c6-a5de-63c4718963a1', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 16, 16, 'ቀኖች ክፉዎች ናቸውና ዘመኑን ዋጁት።'),
  ('48edb51f-2850-575a-a07f-f00423df0273', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 17, 17, 'ስለዚህም ሰነፎች አትሁኑ፤ የእግዚአብሔርን ፈቃድ አስተውሉ እንጂ።'),
  ('5bcb0db6-8626-53c2-af89-2d4c61bf9ebc', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 18, 18, 'መዳራት ነውና ወይን በመጠጣት አትስከሩ፤ መንፈስ ቅዱስን ተመሉ እንጂ።'),
  ('a89cc688-c3cf-573d-a2c5-5eebdfaaea57', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 19, 19, 'መዝሙርንና ምስጋናን፥ የተቀደሰ ማሕሌትንም አንብቡ፤ በልባችሁም ለእግዚአብሔር ተቀኙ፤ ዘምሩም።'),
  ('2675163f-9def-5f81-afb2-da3c22f56a0a', '84880523-3309-5788-a7ef-ef319d835413', 'e03167b8-3dce-586c-ae55-71072ffdb974', 20, 20, 'ዘወትርም ስለ ሁሉ በጌታችን በኢየሱስ ክርስቶስ ስም ለእግዚአብሔር አብ ምስጋና አቅርቡ።'),
  ('6ee07c9b-6aa6-57e8-af3c-6766ec709d8e', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 1, 21, 'እግዚአብሔርን በመፍራት ለባልንጀሮቻችሁ ራሳችሁን ዝቅ አድርጉ።'),
  ('55408aae-012d-5b65-a987-a4a32e70931d', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 2, 22, 'ሴቶችም ለጌታችን እንደሚታዘዙ ለባሎቻቸው ይታዘዙ።'),
  ('5db274d2-4041-54df-aeed-2a2136716978', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 3, 23, 'ክርስቶስ አካሉ ለሆነችው ቤተ ክርስቲያን ራስዋ አዳኝዋም እንደ ሆነ ወንድ ለሴት ራስዋ ነውና።'),
  ('a6260376-8b0c-522c-abe4-c3efb90e991e', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 4, 24, 'ቤተ ክርስቲያን ለክርስቶስ እንደምትታዘዝ፥ እንዲሁም ሴቶች ለባሎቻቸው በሁሉ ይታዘዙ።'),
  ('bd8b9c04-2460-56b1-a60c-25c87a874648', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 5, 25, 'ወንዶችም ክርስቶስ ቤተ ክርስቲያንን እንደ ወደዳት፥ ራሱንም ስለ እርስዋ ቤዛ አድርጎ እንደ ሰጠላት ሚስቶቻቸውን ይውደዱ።'),
  ('4e352561-9b71-56b1-a6ed-e23040922cfa', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 6, 26, 'በውኃ ጥምቀትና በቃሉ ይቀድሳትና ያነጻት ዘንድ፥'),
  ('4fc429ea-f878-52cb-a3e5-d5b2049ab9c4', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 7, 27, 'የነጻችና የተቀደሰች ትሆን ዘንድ እንጂ በላይዋ እድፈት ወይም ርኵሰት እንዳያገኝባት፥ ቤተ ክርስቲያኑን ለእርሱ የከበረች ያደርጋት ዘንድ፤'),
  ('c3d4524a-e443-5019-ad91-ae8699118d66', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 8, 28, 'እንዲሁም ወንዶች ሚስቶቻቸውን እንደ ራሳቸው አድርገው ይውደዱ፤ ሚስቱንም የወደደ ራሱን ወደደ።'),
  ('de136df0-3aee-5040-aa23-e2e38ce00407', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 9, 29, 'ከቶ ሥጋውን መጥላት የሚቻለው የለም፤ ክርስቶስ ቤተ ክርስቲያንን እንደ መገባት መግቡ፤ ጠብቁም።'),
  ('57d2130b-2a3a-5675-a1a0-e1fa92d86981', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 10, 30, 'እኛ የአካሉ ሕዋሳት ነንና።'),
  ('da73b6eb-bceb-53f2-af50-d0d883233118', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 11, 31, '“ስለዚህም ወንድ አባቱንና እናቱን ይተዋል፤ ከሚስቱም ጋር አንድ ይሆናል፤ ሁለቱም አንድ አካል ይሆናሉ።”'),
  ('db521cfa-edbd-5883-a210-523e32160ede', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 12, 32, 'ይህም ምሥጢር ታላቅ ነው፤ እኔም ይህንኑ ስለ ክርስቶስና ስለ ቤተ ክርስቲያኑ እናገረዋለሁ።'),
  ('fd5d7dc1-33d8-5511-a633-59aabf780a99', '84880523-3309-5788-a7ef-ef319d835413', '049a6b6b-51ba-5a5f-a5d4-bdec3dc59e18', 13, 33, 'እንግዲያስ እናንተም ሁላችሁ እንዲሁ ሚስቶቻችሁን እንደ ራሳችሁ ውደዱ፥ ሴትም ባልዋን ትፍራው።'),
  ('c1b47795-f377-53ec-a1da-54a9c26a1434', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '5885174c-7000-53d4-af39-46bb96ada7a6', 1, 1, 'ልጆች ሆይ፥ ለወላጆቻችሁ በጌታችን ታዘዙ፤ ይህ የሚገባ ነውና።'),
  ('dd0dfebd-51ce-5191-a5f9-27defd97dba7', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '5885174c-7000-53d4-af39-46bb96ada7a6', 2, 2, 'በሕግም ተስፋ ያለው የመጀመሪያው ትእዛዝ ይህ ነው፥ “አባትህንና እናትህን አክብር፤'),
  ('052a89ce-9b37-50e0-af11-da329a893774', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '5885174c-7000-53d4-af39-46bb96ada7a6', 3, 3, 'መልካም ይሆንልህ ዘንድ፥ በምድር ላይም ዕድሜህ ይረዝም ዘንድ።”'),
  ('cd432ebf-e10f-5402-a994-1bd4aed0ecc5', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '5885174c-7000-53d4-af39-46bb96ada7a6', 4, 4, 'እናንተም አባቶች ሆይ፥ ልጆቻችሁን በእግዚአብሔር ተግሣጽና ምክር አሳድጉአቸው እንጂ አታስቈጡአቸው።'),
  ('65681b9e-ffff-5086-ac17-a9d5f0c19714', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '02f1e2d6-3056-5d1b-a06b-57a5e88c9603', 1, 5, 'አገልጋዮችም በሥጋችሁ ለሚገዙአችሁ ጌቶቻችሁ በፍርሀትና በመደንገጥ፥ በሰፊ ልብም ለክርስቶስ እንደምትገዙ ታዘዙ።'),
  ('08c903a4-be67-525e-ace2-fc57e8197902', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '02f1e2d6-3056-5d1b-a06b-57a5e88c9603', 2, 6, 'የእግዚአብሔርን ፈቃድ እንደሚያደርጉ እንደ ክርስቶስ ባሮች እንጂ ለሰው ደስ እንደሚያሰኝ ለታይታ አይደለም።'),
  ('e5a285c6-5279-53cc-a4cb-ecc9f5262572', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '02f1e2d6-3056-5d1b-a06b-57a5e88c9603', 3, 7, 'ለሰው ሳይሆን ለእግዚአብሔር እንደምትገዙ በፍጹም ሰውነታችሁ በፍቅርና በበጎ ፈቃድ ተገዙላቸው።'),
  ('6bce34a9-bc93-5dbb-a1e2-dc1406f61e45', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '02f1e2d6-3056-5d1b-a06b-57a5e88c9603', 4, 8, 'ጌታም ቢሆን፥ አገልጋይም ቢሆን መልካም ያደረገ ሁሉ በእግዚአብሔር ዘንድ ዋጋ እንደሚያገኝ ታውቃላችሁና።'),
  ('b263ffcb-f4a2-554e-a963-6bad18999893', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '02f1e2d6-3056-5d1b-a06b-57a5e88c9603', 5, 9, 'እናንተም ጌቶች ሆይ፥ ቍጣችሁን እያበረዳችሁ፥ በደላቸውንም ይቅር እያላችሁ፥ ትክክለኛውን አድርጉላቸው፤ ፊት አይቶ የማያዳላ ጌታ በእነርሱና በእናንተ ላይ በሰማይ እንደ አለ ታውቃላችሁና።'),
  ('a399d46d-2e9c-5d6f-a46d-75e125ca56e4', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 1, 10, 'እንግዲህስ ወዲህ በእግዚአብሔርና በኀይሉ ጽናት በርቱ።'),
  ('748e148e-14ea-5b9b-a80c-cca529a28dd2', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 2, 11, 'የሰይጣንን ተንኰል መቋቋም እንድትችሉ የእግዚአብሔርን ጋሻ ልበሱ።'),
  ('86115382-e610-51a6-ada5-74649500e23d', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 3, 12, 'ሰልፋችሁ፦ ከጨለማ ገዦች ጋርና ከሰማይ በታች ካሉ ከክፉዎች አጋንንት ጋር ነው እንጂ ከሥጋዊና ከደማዊ ጋር አይደለምና።'),
  ('8d250e24-8638-533d-a0ef-f35c84af925c', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 4, 13, 'ስለዚህም በክፉ ቀን መቃወም እንድትችሉ የእግዚአብሔርን ጋሻ ያዙ፤ እንድትጸኑም በሁሉ የተዘጋጃችሁ ሁኑ።'),
  ('c6eed104-c1b3-582a-a53d-18c141a65cfa', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 5, 14, 'እንግዲህ ወገባችሁን በእውነት ታጥቃችሁ ቁሙ፤ የጽድቅንም ጥሩር ልበሱ።'),
  ('109c5532-2b1e-56eb-a563-3a6c9a8f00ef', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 6, 15, 'የሰላም ወንጌል ኀይልንም ተጫምታችሁ ቁሙ።'),
  ('2274f3bf-846c-5dbb-a9d4-80c456f75875', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 7, 16, 'ከዚህም ሁሉ ጋር የሚንበለበሉ የክፉን ፍላፃዎች ሁሉ ማጥፋት እንድትችሉ የእምነትን ጋሻ አንሡ።'),
  ('3e2d85dc-83e2-536f-a214-aea55a428261', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 8, 17, 'የመዳንንም የራስ ቍር በራሳችሁ ላይ ጫኑ፤ የመንፈስ ቅዱስንም ሰይፍ ያዙ፤ ይኸውም የእግዚአብሔር ቃል ነው።'),
  ('3533ac38-b878-5016-a95a-1dc1eeda3d67', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 9, 18, 'በጸሎትና በምልጃ ሁሉ ዘወትር በመንፈስ ጸልዩ፤ ከዚህም ጋር ስለ ቅዱሳን ሁሉ ለመጸለይ ሁልጊዜ ትጉ፤'),
  ('a55ebe05-3e54-5769-a82f-7aa7abbfcc2e', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 10, 19, 'ለእኔም፦ ቃልን እንዲሰጠኝ፥ አፌንም ከፍቼ የወንጌልን ምሥጢር በግልጥ እንድናገር ጸልዩልኝ።'),
  ('27991417-447f-5880-aca8-737fb4d15556', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 11, 20, 'ስለ ወንጌልም በእስራት መልእክተኛ የሆንሁ፦ መናገር እንደሚገባኝ ስለ እርሱ በግልጥ እናገር ዘንድ ጸልዩ።'),
  ('94aefa09-dd34-59cc-ac66-cff2e9760919', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 12, 21, 'እናንተም ዜናዬን እንድታውቁ የምንወደው ወንድማችን የታመነ የእግዚአብሔር አገልጋይ ቲኪቆስ የምሠራውን ሁሉ ያስረዳችኋል።'),
  ('19b32332-a3fd-5d36-aac1-57074d07c98f', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 13, 22, 'ዜናዬን ታውቁ ዘንድ፥ ልባችሁም ይጽናና ዘንድ፥ ስለዚህ ወደ እናንተ ላክሁት።'),
  ('7afc8a4c-6da7-57f2-a7b5-7af338ad1ac8', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 14, 23, 'ከአባታችን ከእግዚአብሔር አብ፥ ከጌታችን ከኢየሱስ ክርስቶስም ከእምነት ጋር ሰላምና ፍቅር ለወንድሞቻችን ይሁን።'),
  ('38db59b6-2c12-59d5-adbc-6a2abb426580', 'e73d8766-1eb9-5a8c-a064-5ab6163cfdff', '16c497ca-5cb8-5366-a094-1140543e4b7f', 15, 24, 'ጌታችን ኢየሱስ ክርስቶስን ባለ መጥፋት ከሚወዱት ሁሉ ጋር ጸጋ ይሁን። አሜን።'),
  ('375b3574-e761-50c8-aecc-fdccee1edfe4', '3330438e-1576-56b9-a804-f4f28b5d515d', '83a06025-1286-5525-a434-a7a71eb0e265', 1, 1, 'ከኢየሱስ ክርስቶስ ባርያዎች ከጳውሎስና ከጢሞቴዎስ፥ በፊልጵስዩስ ለሚኖሩ፤ ከቀሳውስትና ከዲያቆናት ጋር በኢየሱስ ክርስቶስ ላሉ ቅዱሳን ሁሉ፤'),
  ('8d2b97ae-d940-5574-a0f0-55261b1a140c', '3330438e-1576-56b9-a804-f4f28b5d515d', '83a06025-1286-5525-a434-a7a71eb0e265', 2, 2, 'ከአባታችን ከእግዚአብሔር፥ ከጌታችን ከኢየሱስ ክርስቶስም ሰላምና ጸጋ ለእናንተ ይሁን።'),
  ('a5107320-0499-5f36-a30f-a64516187677', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 1, 3, 'እናንተን በማስብበት ጊዜ ሁሉ ዘወትር አምላኬን አመሰግነዋለሁ።'),
  ('15206cc5-8c05-5fe7-ac9b-6fa73140a8c2', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 2, 4, 'ስለ እናንተም ሁልጊዜ እጸልያለሁ፤ የደስታ ጸሎትም አደርጋለሁ።'),
  ('7498ed06-ce5d-5d20-af2a-a2c538a6f0c0', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 3, 5, 'ከመጀመሪያዪቱ ቀን ጀምሮ እስከ ዛሬ በወንጌል ትምህርት ከእኔ ጋር አንድ በመሆናችሁ፥'),
  ('7f50c99a-c5d3-59e8-afc9-d8e2a47a0065', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 4, 6, 'እርሱ የጀመረላችሁን በጎውን ሥራ ጌታችን ኢየሱስ ክርስቶስ እስከሚመጣበት ቀን ድረስ እርሱ እንደሚፈጽምላችሁ አምናለሁ።'),
  ('ababa27c-f518-5cde-aee2-cb99873bf8b9', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 5, 7, 'ስለ እናንተ ይህን ላስብ ይገባኛል፤ በምታሰርበትና በምከራከርበት፥ ወንጌልንም በማስተምርበት ጊዜ ከእኔ ጋራ በጸጋ ስለ ተባበራችሁ በልቤ ውስጥ ናችሁና።'),
  ('57d6261f-0c09-53f1-a144-15a32df02d23', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 6, 8, 'በክርስቶስ ፍቅር ሁላችሁን እንደምወዳችሁ እግዚአብሔር ምስክሬ ነው።'),
  ('7b34ccd7-c4ca-5d31-afd9-98fa57af8428', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 7, 9, 'ስለዚህም በአእምሮና በልብ ጥበብ ሁሉ ፍቅራችሁ እንዲበዛ፥ እንዲጨምርም እጸልያለሁ፤'),
  ('94b09b09-315b-5a68-ae00-bbb5022e0227', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 8, 10, 'የሚሻለውን ሥራ እንድትመረምሩና እንድትፈትኑ፥ ክርስቶስ በሚመጣበት ቀን ያለ ዕንቅፋት ቅዱሳን ትሆኑ ዘንድ፦'),
  ('f4af1102-306b-5575-a33d-e49db6bee52f', '3330438e-1576-56b9-a804-f4f28b5d515d', '87ac6850-3fcc-5040-a88b-a23680f86152', 9, 11, 'ለእግዚአብሔር ምስጋናና ክብርም በኢየሱስ ክርስቶስ የጽድቅን ፍሬ ትሞሉ ዘንድ እጸልያለሁ፤'),
  ('6a4cbe3b-2885-5877-ac7c-17ad162849f6', '3330438e-1576-56b9-a804-f4f28b5d515d', 'a39dea30-9488-5f4d-a88e-a29a2ad294f2', 1, 12, 'ወንድሞች ሆይ፥ ይህ የደረሰብኝ በእውነት ወንጌልን ለማስፋፋት እንደ ሆነ ታውቁ ዘንድ እወድዳለሁ።'),
  ('0c552296-f4f9-524b-a27d-272d78d91ae5', '3330438e-1576-56b9-a804-f4f28b5d515d', 'a39dea30-9488-5f4d-a88e-a29a2ad294f2', 2, 13, 'ስለ ክርስቶስ ስም መታሰሬም በአደባባዩ ሁሉና በሰው ሁሉ ዘንድ ታውቆአል።'),
  ('b81890ed-a654-5c44-afb7-faa574be4424', '3330438e-1576-56b9-a804-f4f28b5d515d', 'a39dea30-9488-5f4d-a88e-a29a2ad294f2', 3, 14, 'ከወንድሞቻችንም ብዙዎቹ በእስራቴ ምክንያት በጌታ ታመኑ፤ የእግዚአብሔርንም ቃል ያለ ፍርሀት ጨክነው ያስተምሩ ዘንድ እጅግ ተደፋፈሩ።'),
  ('190205c3-f20d-56e0-a269-5cc9b2370345', '3330438e-1576-56b9-a804-f4f28b5d515d', 'a39dea30-9488-5f4d-a88e-a29a2ad294f2', 4, 15, 'ከእነርሱ አንዳንዶች በቅናታቸውና በክርክራቸው፥ ሌሎችም በበጎ ፈቃድ ስለ ክርስቶስ ሊሰብኩና ሊያስተምሩ የወደዱ አሉ።'),
  ('a4844173-357c-5e28-add5-bc80b7566204', '3330438e-1576-56b9-a804-f4f28b5d515d', 'a39dea30-9488-5f4d-a88e-a29a2ad294f2', 5, 16, 'በፍቅር የሚያስተምሩም አሉ፤ ወንጌልን ለማስተማር እንደ ተሾምሁ ያውቃሉና።'),
  ('fef5576d-b6fb-5fb9-aff0-8cc55d574951', '3330438e-1576-56b9-a804-f4f28b5d515d', 'a39dea30-9488-5f4d-a88e-a29a2ad294f2', 6, 17, 'በኵራት ስለ ክርስቶስ የሚያስተምሩ ግን፥ ይህን አድርገው በእስራቴ ላይ መከራ ሊጨምሩብኝ መስሎአቸው ነው እንጂ በእውነት አይደለም፤ በቅንነትም አይደለም።'),
  ('75c34886-b333-5c14-a7ac-084b58dc26f7', '3330438e-1576-56b9-a804-f4f28b5d515d', 'a39dea30-9488-5f4d-a88e-a29a2ad294f2', 7, 18, 'ነገር ግን ምን አለ? በየምክንያቱ በእውነትም ቢሆን፥ በሐሰትም ቢሆን፥ ስለ ክርስቶስ ይናገራሉ፤ ሰውንም ሁሉ ወደ እርሱ ይጠራሉ፤ በዚህም ደስ ብሎኛል፤ ወደፊትም ደስ ይለኛል።'),
  ('e342340f-23b0-5b29-a742-81040a512c1e', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 1, 19, 'እኔም ይህቺ ሥራ በጸሎታችሁና በኢየሱስ ክርስቶስ መንፈስ ወደ ሕይወት እንደምታደርሰኝ አውቃለሁ።'),
  ('ad2ad3cc-8b4d-5417-a40b-a95f79c27e3e', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 2, 20, 'በምንም እንደማላፍር ተስፋ እንደ አደረግሁና እንደታመንሁ እንደ ወትሮው በልብ ደስታ በግልጥነት፥ አሁንም የክርስቶስ ክብር በሕይወቴም ቢሆን፥ በሞቴም ቢሆን በሰውነቴ ይገለጣል።'),
  ('9d688a46-c057-5610-a9e2-cded9de02b63', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 3, 21, 'እኔ በሕይወት ብኖርም ክርስቶስን ለማገልገል ነው፤ ብሞትም ዋጋ አለኝ።'),
  ('0c246b1c-9fc7-5807-a738-a7633b6fb584', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 4, 22, 'ነገር ግን በሥጋ መኖር ለእኔ የሥራ ፍሬ ቢሆንም ምን እንደምመርጥ አላውቅም።'),
  ('0ba1f4c2-29e1-5176-a8cc-a8f4c252a338', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 5, 23, 'በእነዚህ በሁለቱ እጨነቃለሁ፤ እኔስ ከዚህ ዓለም ልለይ፥ በከክርስቶስም ዘንድ ልኖር እወዳለሁ፤ ይልቁንም ለእኔ ይህ ይሻለኛል፤ ይበልጥብኛልም።'),
  ('36a609b2-504f-57b7-ab8b-ee2f98f5d84e', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 6, 24, 'ደግሞም ስለ እናንተ በሕይወተ ሥጋ ብኖር ይሻላል።'),
  ('f7854cf2-1147-5fe8-a494-be134f868034', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 7, 25, 'ይህንም ዐውቄ ለማደጋችሁና በሃይማኖትም ለምታገኙት ደስታ እንደምኖር አምናለሁ።'),
  ('ca91665d-8ed5-58d8-aa0b-96c2750bdb03', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 8, 26, 'ዳግመኛ ወደ እናንተ በመምጣቴ በእኔ ምክንያት በኢየሱስ ክርስቶስ የምታገኙት ክብር ይበዛላችሁ ዘንድ።'),
  ('7b3b9cd0-7040-5c9d-ab9c-a1bdfa8e6b8a', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 9, 27, 'ነገር ግን ምናልባት የመጣሁ እንደ ሆነ፥ ሳልኖርም ቢሆን በወንጌል ሃይማኖት እየተጋደላችሁ በአንድ መንፈስና በአንድ አካል ጸንታችሁ እንደምትኖሩ አይና እሰማ ዘንድ ሥራችሁ ለክርስቶስ ትምህርት እንደሚገባ ይሁን።'),
  ('72912deb-4a72-54be-a9d6-d732de7244b5', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 10, 28, 'የእነርሱ ጥፋት፥ የእናንተም ሕይወት ይታወቅ ዘንድ የሚቃወሙን ሰዎች በማናቸውም አያስደንግጧችሁ።'),
  ('a88d597e-db83-58d7-af1b-b9127049f71b', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 11, 29, 'ይህንም ጸጋ እግዚአብሔር ሰጥቶአችኋል፤ ነገር ግን ስለ እርሱ መከራ ልትቀበሉም ነው እንጂ ልታምኑበት ብቻ አይደለም።'),
  ('55667bff-96ec-5fdf-a0e2-bf69cd9a51b0', '3330438e-1576-56b9-a804-f4f28b5d515d', 'b9f59c95-040c-55df-a678-db526a8d4df3', 12, 30, 'እንዲሁም እኔን እንዳያችሁኝ፥ የእኔንም ነገር እንደ ሰማችሁ ምንጊዜም ተጋደሉ።'),
  ('3cbf4064-9953-5ccd-a234-44b4cd769b3c', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 1, 1, 'አሁንም በክርስቶስ ደስታ፥ ወይም በፍቅር የልብ መጽናናት፥ ወይም የመንፈስ አንድነት፥ ወይም ማዘንና መራራትም በእናንተ ዘንድ ካለ፦'),
  ('aad36b7b-7c3f-5a90-ac83-6ebaa1dea0c7', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 2, 2, 'እርሱን ብቻ ታስቡ ዘንድ፥ አንድ ልብና አንድ ምክርም ሆናችሁ፥ በፍቅር ትኖሩ ዘንድ ደስታዬን ፈጽሙልኝ።'),
  ('e4e80b53-1e81-5623-a9c1-6c5e6b8ea90c', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 3, 3, 'በክርክርና ከንቱ ውዳሴን በመውደድ አትሥሩ፤ ትሕትናን በያዘ ልቡና ከራሳችሁ ይልቅ ባልንጀራችሁን አክብሩ እንጂ አትታበዩ።'),
  ('4478602d-525a-55d9-aa78-e3e11898a2bc', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 4, 4, 'ለባልንጀራችሁም እንጂ ለየራሳችሁ ብቻ አታስቡ።'),
  ('30a26773-68db-5005-a28b-7e8b50b40b06', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 5, 5, 'ፍጹማን የሆናችሁ ሁላችሁ ኢየሱስ ክርስቶስ ለእኛ እንደ አደረገልን ይህን አስቡ።'),
  ('cea6a891-74f0-5ec7-a91e-9fb00c50809c', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 6, 6, 'ይኸውም የእግዚአብሔር መልኩ ነው፤ ቀምቶ እግዚአብሔር የሆነ አይደለም።'),
  ('06594d49-8579-52ce-ad56-a7b90ed83b55', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 7, 7, 'ነገር ግን የባርያን መልክ ይዞ፥ በሰውም ምሳሌ ሆኖ ራሱን ዝቅ አደረገ።'),
  ('8e06fcbe-9fce-52bf-ab40-811edb4b4059', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 8, 8, 'እንደ ሰውም ሆኖ ራሱን አዋረደ፤ ለሞት እስከ መድረስም ታዘዘ፤ ሞቱም በመስቀል የሆነው ነው።'),
  ('7647abf7-f1f4-5174-a745-0a318cfdba51', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 9, 9, 'ስለዚህም እግዚአብሔር እጅግ ከፍ ከፍ አደረገው፤ ከስም ሁሉ የሚበልጥ ስምንም ሰጠው።'),
  ('ad0ae675-6117-57ed-ab54-50eeaea21ba2', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 10, 10, 'ይህም በሰማይና በምድር በቀላያትና ከምድር በታች ያለ ጕልበት ሁሉ ለኢየሱስ ክርስቶስ ስም ይሰግድ ዘንድ ነው።'),
  ('287987cc-72f5-5d15-afdb-0c8cefea4eac', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 11, 11, 'አንደበትም ሁሉ ኢየሱስ ክርስቶስ በእግዚአብሔር አብ ክብር ጌታ እንደ ሆነ ያምን ዘንድ ነው።'),
  ('03c479ef-5e71-5782-a9d5-2c62fe57d336', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 12, 12, 'አሁንም ወንድሞች ሆይ፥ ዘወትር እንደምትሰሙኝ ሳለሁ ብቻ ሳይሆን፥ ሳልኖርም በፍርሀትና በመንቀጥቀጥ ሆናችሁ ለድኅነታችሁ ሥሩ።'),
  ('e7af0a72-53eb-5675-adb0-fda03d73b74e', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 13, 13, 'ለሚወደው ሥራ የሚረዳችሁ እርሱ እግዚአብሔር ይቅርታውን ይፈጽምላችሁ።'),
  ('febe7df3-7fd4-5c70-a45d-5caff265b48e', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 14, 14, 'የምትሠሩትን ሁሉ ያለ ማንጐራጐርና ያለ መጠራጠር በፍቅርና በስምምነት ሥሩ።'),
  ('f6f284a6-391b-5c74-a125-41bc1e2f62a4', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 15, 15, 'እንደ እግዚአብሔር ልጆች ንጹሓንና የዋሃን ትሆኑ ዘንድ፥ በማያምኑና በጠማሞች ልጆች መካከል ነውር ሳይኖርባችሁ በዓለም እንደ ብርሃን ትታያላችሁ፤'),
  ('810dbac0-3ae3-5455-aac0-854215f76a24', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 16, 16, 'የሕይወትን ቃል እያስተማራችሁ፤ ክርስቶስ በሚመጣበት ቀን እኔ እንድመካ፤ የሮጥሁ በከንቱ አይደለምና፤ የደከምሁም በከንቱ አይደለምና።'),
  ('989074b6-d698-571e-a0bd-7b36acbd2cd3', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 17, 17, 'ስለ ሃይማኖታችሁም የአምልኮ መሥዋዕትን እሠዋለሁ። እነሆም እኔ በእናንተ ደስ ይለኛል፤'),
  ('c865cff8-03e9-504e-a54a-6f6d9646a17e', '8c819b4f-d056-52b3-a730-628402c869de', 'a0b2531d-a224-5c6d-a370-b4f3705ba028', 18, 18, 'እናንተም በእኔ ደስ ይበላችሁ። ከእኔም ጋር ሐሤት አድርጉ።'),
  ('bdea4f44-900c-5b34-afc3-eb412e8001cf', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 1, 19, 'ጢሞቴዎስን እንድልክላችሁ፥ እኔም ዜናችሁን ሰምቼ ደስ እንዲለኝ በጌታችን በኢየሱስ ክርስቶስ ተስፋ አደርጋለሁ።'),
  ('e41dd40e-a191-5e3d-aa8f-3887feee4fc7', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 2, 20, 'ከእርሱ በቀር፥ እንደ እኔ ሆኖ በማስተዋል ግዳጃችሁን የሚፈጽም የለኝምና።'),
  ('8834d186-1c58-59d0-a614-4634937269a7', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 3, 21, 'የክርስቶስን ያይደለ፥ ሁሉም የራሱን ጉዳይ ያስባልና።'),
  ('f3f6bf0c-4dc1-5f99-a1e0-cbd2ef452bfe', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 4, 22, 'ልጅ አባቱን እንደሚያገለግል፥ በወንጌል ትምህርት እንደ አገለገለኝ፥ የዚህን ሰው ጠባዩን ታውቃላችሁ።'),
  ('bb009464-74e6-5028-a849-9a4d46935852', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 5, 23, 'እንግዲህ እንዴት እንደ አለሁ በዐወቅሁ ጊዜ፥ እርሱን በቶሎ እንደምልከው ተስፋ አደርጋለሁ፤'),
  ('00e3f061-9f74-5668-a6c8-b5f4ee53df85', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 6, 24, 'እኔም ፈጥኜ እንደምመጣ በጌታችን አምናለሁ።'),
  ('492add6a-ea5d-5421-a664-8eecd48e499b', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 7, 25, 'አሁንም አብሮኝ የሚሠራውን ወንድማችንን አፍሮዲጡን ወደ እናንተ ልልከው አስቤአለሁ፤ እርሱም የክርስቶስ ሎሌ ነው፤ ለእናንተም መምህራችሁ ነው፤ ለእኔም ለችግሬ ጊዜ መልእክተኛዬ ነው።'),
  ('33a84460-51ae-5f93-a9ea-6a042f0927ad', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 8, 26, 'እንደ ታመመ፥ ለሞትም እንደ ደረሰ መስማታችሁን ዐውቆ ሊያያችሁ ይሻልና።'),
  ('5a9d07bf-938a-53b0-af41-9341b283a0bd', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 9, 27, 'ነገር ግን እግዚአብሔር ማረው፤ በኀዘን ላይ ኀዘን እንዳይጨመርብኝ ለእኔም እንጂ ለእሱ ብቻ አይደለም።'),
  ('60fe4e9e-5c75-58bb-a529-88bd5c4954ef', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 10, 28, 'እንድታዩትና ደስ እንዲላችሁ፥ እኔም እንዳላዝን በቶሎ እልከዋለሁ።'),
  ('22aaf816-d3fb-5d75-adfb-c7af4eaa36b7', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 11, 29, 'እንግዲህ በጌታችን በፍጹም ደስታ ተቀበሉት፤ እንደዚህ ያሉትንም ሁሉ አክብሩአቸው።'),
  ('2e8d98a2-0f39-5f2a-ad49-3221daaad6f7', '8c819b4f-d056-52b3-a730-628402c869de', '0d9bdd3d-eb9b-5374-a678-c85e333e62ff', 12, 30, 'የእግዚአብሔርን ሥራ ስለ መሥራት እስከ ሞት ደርሶአልና፥ ከእኔ መልእክትም እናንተ ያጐደላችሁትን ይፈጽም ዘንድ ሰውነቱን አሳልፎ ሰጥቶአልና።'),
  ('da0f71a0-a9fb-5951-a153-659b527fe5b3', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 1, 1, 'አሁንም ወንድሞች ሆይ፥ በጌታችን ደስ ይበላችሁ፤ እኔም ስጽፍላችሁ ቸል አልልም፤ ያበረታችኋልና።'),
  ('0e7a4a8e-8bab-5708-a743-abb3d1e4aff4', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 2, 2, 'ከውሾች ተጠበቁ፤ ከክፉ አድራጊዎችም ተጠበቁ፤ ሥጋቸውን ብቻ በመቍረጥ ተገዝረናል ከሚሉም ተጠበቁ።'),
  ('0de881de-694d-59c5-aa7a-8f39805d75d1', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 3, 3, 'ግዙራንስ እግዚአብሔርን በመንፈስ የምናገለግለውና የምናመልከው እኛ ነን፤ እኛም በኢየሱስ ክርስቶስ እንመካለን እንጂ በሥጋችን የምንመካ አይደለም።'),
  ('44f07759-a933-50d9-ac9b-2ac3f8a96959', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 4, 4, 'እኔም ግዝረት ሳለኝ በግዝረት አልመካም፤ በግዝረት መመካትን የሚያስብ ካለም እኔ እርሱን እበልጠዋለሁ።'),
  ('8c8433c2-1a7e-5e54-a80a-d0b0f3e08150', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 5, 5, 'በስምንተኛው ቀን የተገዘርሁ፥ ከእስራኤል ሕዝብ ከብንያም ነገድ ከዕብራውያን ዕብራዊ ነኝ፤ በኦሪትም ፈሪሳዊ ነበርሁ።'),
  ('8a96c098-5279-5367-a2c9-836be9604e36', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 6, 6, 'በኦሪት ጽድቅም ያለ ነውር ሆኜ በቅንዐት ምእመናንን አሳድድ ነበር።'),
  ('58d781f8-f62e-5d90-a521-7b1edb79ff41', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 7, 7, 'ነገር ግን ስለ ክርስቶስ ያን ጥቅሜን ላጣው ወደድሁ።'),
  ('82f5718e-6c5c-551c-a5c4-1bb249c43ad3', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 8, 8, 'ክርስቶስን አገለግለው ዘንድ፥ ሁሉን የተውሁለት፥ እንደ ጕድፍም ያደረግሁለት የጌታዬን የኢየሱስ ክርስቶስን ኀይልና ገናናነት ስለማውቅ ሁሉን እንደ ኢምንት ቈጠርሁት።'),
  ('29493540-a0db-50da-acea-55ec52362584', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 9, 9, 'በእርሱም እጸና ዘንድ፥ ዛሬ የኦሪት ጽድቅ ሳይኖረኝ ክርስቶስን በማመን ከእግዚአብሔር የሚገኝ ጽድቅ አለኝ እንጂ።'),
  ('d4d9a363-55b8-5cad-af17-e232fff6f7ed', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 10, 10, 'በእርሱም ኢየሱስ ክርስቶስን አውቀዋለሁ፤ የመነሣቱንም ኀይል በሕማሙ እሳተፈዋለሁ፤ በሞቱም እመስለዋለሁ።'),
  ('1b631c11-8994-5f8c-a01f-86e19c01be4f', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '19d57537-1fda-58d6-a979-64866bd640f8', 11, 11, 'ይኸውም ሙታን በሚነሡ ጊዜ ምናልባት በዚህ አገኘው እንደ ሆነ ብዬ ነው።'),
  ('1ab30ef4-23ba-5cdc-abb9-2686b2b32e9b', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '23730391-6f87-5f14-ad22-ff6df2786c72', 1, 12, 'ነገር ግን ይህን ፈጽሜ የተቀበልሁ አይደለም፤ ኢየሱስ ክርስቶስ ስለ እርሱ እኔን የመረጠበትን አገኝ ዘንድ እሮጣለሁ እንጂ።'),
  ('16a51690-a5a6-5989-a899-a9796032c22f', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '23730391-6f87-5f14-ad22-ff6df2786c72', 2, 13, 'ወንድሞች ሆይ፥ እኔ ግን ፍጻሜዬን ገና ያገኘሁ አይመስለኝም።'),
  ('fbf1a3e6-982b-5b80-a065-1e2ea1b57520', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '23730391-6f87-5f14-ad22-ff6df2786c72', 3, 14, 'የኋላዬን እረሳለሁና፥ ወደ ፊቴም ፈጥኜ እገሠግሣለሁና፤ በኢየሱስ ክርስቶስም ከፍ ከፍ ያለውን የእግዚአብሔርን የጥሪ ዋጋ ለማግኘት ወደ ግቡ እፈጥናለሁ።'),
  ('0e4f9695-3027-5c60-a155-c3bccee05fdb', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '30b9bcb8-387e-5f88-a4b5-70f69afdd190', 1, 15, 'ፍጹማን የሆናችሁ ሁላችሁ ይህን አስቡ፤ ሌላ የምታስቡት ቢኖርም፥ እርሱን እግዚአብሔር ይገልጥላችኋል።'),
  ('0051111e-ff4c-5733-a8b5-0434446cffde', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '30b9bcb8-387e-5f88-a4b5-70f69afdd190', 2, 16, 'ነገር ግን በደረስንበት ሥራ በአንድነት እንበርታ።'),
  ('eb13474a-46c2-5b85-aa7d-7eac3f210fab', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '30b9bcb8-387e-5f88-a4b5-70f69afdd190', 3, 17, 'ወንድሞች ሆይ፥ እኔን ምሰሉ፤ እንዲህ ባለ መንገድ የሚሄዱትንም እኛን ታዩ እንደ ነበረበት ጊዜ ተጠባበቋቸው።'),
  ('397c5231-686c-51db-a2d3-060d897b966c', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '30b9bcb8-387e-5f88-a4b5-70f69afdd190', 4, 18, 'ዘወትር እንደምነግራችሁ፥ ልዩ አካሄድ የሚሄዱ ብዙዎች አሉና፤ አሁንም እነርሱ የክርስቶስ የመስቀሉ ጠላቶች እንደ ሆኑ በግልጥ እያለቀስሁ እነግራችኋለሁ።'),
  ('b350ec37-c97f-52c0-af91-5d83ac1f228e', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '30b9bcb8-387e-5f88-a4b5-70f69afdd190', 5, 19, 'እነዚህም ፍጻሜያቸው ለጥፋት የሆነ፥ ሆዳቸውን የሚያመልኩ፥ ክብራቸውም ውርደት የሆነባቸው፥ ምድራዊዉንም የሚያስቡ ናቸው።'),
  ('16e3c4b6-11b6-5d05-a7e3-fb4e01031d15', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '30b9bcb8-387e-5f88-a4b5-70f69afdd190', 6, 20, 'እኛስ ሀገራችን በሰማይ ያለችው ናት፤ ከዚያም እርሱን ጌታችን መድኀኒታችን ኢየሱስ ክርስቶስን እንጠባበቃለን።'),
  ('0b5f8cfd-acbc-5861-a561-a23b4c04b2b4', '25b0ac10-bf58-54c2-aaae-edfe5957351a', '30b9bcb8-387e-5f88-a4b5-70f69afdd190', 7, 21, 'እርሱም እንደ ከሃሊነቱ ረዳትነት መጠን የተዋረደውን ሥጋችንን የሚያድሰው፥ ክቡር ሥጋዉንም እንዲመስል የሚያደርገው፥ የሚያስመስለውም፥ ሁሉም የሚገዛለት ነው።'),
  ('9a7ff5b9-241b-5d69-a5c7-6a8cb7cc29b0', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 1, 1, 'አሁንም የተወደዳችሁና የምናፍቃችሁ ወንድሞቻችን ሆይ፥ ደስታችንና አክሊላችን ናችሁ፤ ወዳጆቻችን ሆይ፥ እንዲህ ቁሙ፤ በጌታችንም ጽኑ።'),
  ('0b7da588-fc99-56d0-a541-ffa08dce71af', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 2, 2, 'ኤዎድያና ስንጣክን ሆይ፥ በአንድ ልብ ጌታችንን ለማገልገል ታስቡ ዘንድ እማልዳችኋለሁ።'),
  ('a0358965-6cb4-575d-a8a4-e37c30fcc1cb', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 3, 3, 'ወንድሜና አጋዤ ስትሪካ ሆይ፥ እንድትረዳቸው አንተንም እለምንሃለሁ፤ ወንጌልን በማስተማር ከቀሌምንጦስና ሥራቸው ከተባበረ፥ ስማቸውም በሕይወት መጽሐፍ ከተጻፈላቸው ከወንድሞቻችንም ሁሉ ጋር ከእኔም ጋር ደክመዋልና።'),
  ('444ff9db-3401-5736-a147-66fcc32b6c3b', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 4, 4, 'ዘወትር በጌታችን ደስ ይበላችሁ፤ ደግሜ እላችኋለሁ፦ ደስ ይበላችሁ።'),
  ('ab137344-7476-5f05-abbc-67f7b6fbff31', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 5, 5, 'ፍጹምነታችሁም በሰው ሁሉ ዘንድ ይታወቅ። እግዚአብሔር ቅርብ ነው፤'),
  ('ae3ec087-91f7-5f16-ad1d-c98da91417b3', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 6, 6, 'በምንም አትጨነቁ፤ ነገር ግን በሁሉ ነገር ጸልዩ ማልዱም፤ እያመሰገናችሁም ልመናችሁን ለእግዚአብሔር ግለጡ።'),
  ('f69ea52e-b602-5702-a65e-c10c7abfe20c', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 7, 7, 'ሁሉ የሚገኝባት፥ ከልቡናና ከአሳብ ሁሉ በላይ የምትሆን የእግዚአብሔር ሰላም በኢየሱስ ክርስቶስ ልባችሁንና አሳባችሁን ታጽናው።'),
  ('f8804611-e6ae-546a-a61d-110261e00dab', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 8, 8, 'አሁንም ወንድሞቻችን ሆይ፥ እውነትን ሁሉ፥ ቅንነትንም ሁሉ፥ ጽድቅንም ሁሉ፥ ንጽሕናንም ሁሉ፥ ፍቅርንና ስምምነትንም ሁሉ፥ በጎነትም ቢሆን፥ ምስጋናም ቢሆን፥ እነዚህን ሁሉ አስቡ።'),
  ('fbce7dcc-895c-5779-a58a-00529b8ec404', '49fba4ee-aae0-59da-aae6-5e359b697e94', '72db646a-9bfb-5732-a983-f29e930a0833', 9, 9, 'ከእኔ የተማራችሁትንና የተቀበላችሁትን፥ የሰማችሁትንና ያያችሁትንም እነዚህን አድርጉ፤ የሰላም አምላክም ከሁላችሁ ጋር ይሆናል።'),
  ('68236f52-771e-5075-a473-b57298944bf2', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 1, 10, 'በጌታችን እጅግ ደስ አለኝ፤ ቢሳናችሁ እንኳ አሁንም እንደምታስቡልኝ፥ ከዱሮ ጀምሮ ለእኔ ችግር ታስቡ፥ ትተጉም ነበርና።'),
  ('f9b78084-bf8e-57da-adbc-22bbc5bf4a79', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 2, 11, 'ይህንም የምል ስለ አጣሁ አይደለም፤ ያለኝ እንደሚበቃኝ አውቃለሁና።'),
  ('5f4060ba-2b2a-5889-a3d7-883e0c4876b8', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 3, 12, 'እኔ ችግሩንም፥ ምቾቱንም እችላለሁ፤ ራቡንም፥ ጥጋቡንም፥ ማዘኑንም፥ ደስታውንም፥ ሁሉን በሁሉ ለምጀዋለሁ፤'),
  ('8d206081-e849-5cdd-aa83-930fa5841bd4', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 4, 13, 'በሚያስችለኝ በክርስቶስ ሁሉን እችላለሁ።'),
  ('4eafeb0e-2fd4-5c90-ac6b-9df5e1c0e509', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 5, 14, 'ነገር ግን በመከራዬ ጊዜ ተባባሪዎች መሆናችሁ መልካም አደረጋችሁ።'),
  ('baf486e8-346f-51b3-aa28-4764418df77a', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 6, 15, 'እናንተ የፊልጵስዩስ ሰዎች፤ በመጀመሪያው ትምህርት ከመቄዶንያ ወደ እናንተ በመጣሁ ጊዜ፥ ከእናንተ ብቻ በቀር ሌላ ቤተ ክርስቲያን በመስጠትም ቢሆን፥ በመቀበል ከእኔ ጋር እንዳልተባበሩ እናንተ ታውቃላችሁ።'),
  ('5eeadbc8-a451-5306-a428-3cfe62fb18e5', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 7, 16, 'በተሰሎንቄም ሳለሁ ደግሞ፥ አንድ ጊዜና ሁለት ጊዜ ለችግሬ ላካችሁልኝ።'),
  ('7a29f373-373e-56ff-ace5-bba2bf2cee5e', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 8, 17, 'ይህንም የማነሣሣው ስጦታችሁን ፈልጌ አይደለም፤ በእናንተ ላይ የጽድቅ ፍሬ ይበዛ ዘንድ ፈልጌ ነው እንጂ።'),
  ('6401fa1f-9939-59c9-a2dd-00c6bfd771ee', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 9, 18, 'ነገር ግን ሁሉ አለኝ፤ ይበዛልኝማል፤ የመዓዛ ሽታና የተወደደ መሥዋዕት የሚሆነውን፥ ለእግዚአብሔርም ደስ የሚያሰኘውን ስጦታችሁን ከአፍሮዲጡ ተቀብዬ አሟልቻለሁ።'),
  ('0586e17b-dc2e-5f8c-a76d-6914b07cc4d4', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 10, 19, 'ፈጣሪዬ እንደ ባለጸግነቱ መጠን፥ በክብር በኢየሱስ ክርስቶስ የምትሹትን ሁሉ ይፈጽምላችኋል።'),
  ('a317c1e6-b9a7-5030-a7ca-05b07dfe4c92', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 11, 20, 'ለአባታችን ለእግዚአብሔር ለዘለዓለሙ ምስጋና ይሁን አሜን።'),
  ('d9140a7d-acf6-5534-a9c5-77c428b8b94c', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 12, 21, 'በኢየሱስ ክርስቶስ ቅዱሳንን ሁሉ ሰላም በሉ፤ በእኔ ዘንድ ያሉ ወንድሞቻችንም ሰላምታ ያቀርቡላችኋል።'),
  ('09e61f15-2749-5eda-aa1a-cb226b6f7953', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 13, 22, 'ቅዱሳንም ሁሉ፥ ይልቁንም ከቄሣር ቤተ ሰብእ የሆኑ ሰላምታ ያቀርቡላችኋል።'),
  ('1bdf97f1-5ec9-587a-a54a-b87af7f307b1', '49fba4ee-aae0-59da-aae6-5e359b697e94', '4a7f083c-57da-5469-a3c6-1446af0983f6', 14, 23, 'የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከእናንተ ጋር ይሁን፤ አሜን።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c3485010-d50d-5280-adfc-aa3af8d2fa3f', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 1, 1, 'በእግዚአብሔር ፈቃድ ከጌታችን ከኢየሱስ ክርስቶስ ሐዋርያ ከጳውሎስና ከወንድማችን ከጢሞቴዎስ፥'),
  ('2c217df7-95c6-5965-a0b0-1aff12e2f8d2', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 2, 2, 'በቈላስይስ ላሉ ቅዱሳንና በኢየሱስ ክርስቶስ ላመኑ ወንድሞቻችን፥ ከአባታችን ከእግዚአብሔር ከጌታችን ከኢየሱስ ክርስቶስም ሰላምና ጸጋ ለእናንተ ይሁን።'),
  ('1d184703-c0e5-58d5-a390-2c5421cf1fd3', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 3, 3, 'የጌታችን የኢየሱስ ክርስቶስን አባት እግዚአብሔርን ዘወትር ስለ እናንተ እናመሰግነዋለን።'),
  ('03f61312-ae7c-52ef-ac1b-89d2184ea28d', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 4, 4, 'በኢየሱስ ክርስቶስ ማመናችሁንና ቅዱሳንንም ሁሉ መውደዳችሁን ከሰማንበት ጊዜ ጀምሮ፥ ስለ እናንተ እንጸልያለን።'),
  ('5515e2b4-feb9-5935-a019-a45cf449b8ff', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 5, 5, 'የእውነት ቃል በሆነው በወንጌል ትምህርት፥ አስቀድሞ ስለ ሰማችሁት፥ በሰማይ ስለ ተዘጋጀላችሁ ተስፋችሁም እንጸልያለን።'),
  ('fa6efac5-0680-5413-abd8-289fa8638692', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 6, 6, 'ይህም ወደ እናንተ የደረሰውን የእግዚአብሔርን ጸጋ በእውነት ከሰማችሁበትና ከአያችሁበት ቀን ጀምሮ በመላው ዓለም ያድግና ያፈራ ዘንድ ነው።'),
  ('8617d7f7-06ba-5737-a464-0ec147a3f41b', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 7, 7, 'ስለ እናንተ የሚላክ በክርስቶስ የታመነ፥ የእኛም ወንድማችንና አገልጋያችን ከሚሆን ከኤጳፍራስ ተምራችኋል።'),
  ('6e2a690c-609f-5156-a26e-0fb2776c1a43', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '2cabdd09-c7ab-5a38-a6f6-45553a6b7c92', 8, 8, 'እርሱም በመንፈስ መዋደዳችሁን ነገረን።'),
  ('cee9d758-5655-55c1-a0d0-a8d47919a278', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 1, 9, 'ስለዚህም እኛ ዜናችሁን ከሰማን ጀምሮ፥ በፍጹም ጥበብና በፍጹም መንፈሳዊ ምክር የእግዚአብሔርን ፈቃድ ማወቅን ትፈጽሙ ዘንድ፥ ስለ እናንተ መጸለይንና መለመንን አልተውንም።'),
  ('a264c02d-dc2c-515f-a96b-9b076b808b67', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 2, 10, 'ወደ እግዚአብሔር በሚገባችሁ ትሄዱ ዘንድ፥ በበጎ ሥራ ሁሉ ፍሬ እያፈራችሁ፥ እግዚአብሔርንም በማወቅ እያደጋችሁ፥ በሁሉ ደስ ታሰኙት ዘንድ።'),
  ('f3943357-88cf-5851-a6b6-68f5f52b5ef0', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 3, 11, 'በፍጹም ኀይል፥ በክብሩ ጽናት፥ በፍጹም ትዕግሥት፥ በተስፋና በደስታም ጸንታችሁ።'),
  ('9adcebf6-0525-53bd-af8a-f4e865ced58a', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 4, 12, 'በብርሃን ቅዱሳን ለሚታደሉት ርስት የበቃን ያደረገንን እግዚአብሔር አብን አመስግኑት።'),
  ('9cd7cd67-65d0-5c22-a679-3306ac5ecf41', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 5, 13, 'ከጨለማ አገዛዝ አዳነን፤ ወደ ተወደደው ልጁ መንግሥትም መለሰን።'),
  ('8d7dbf3d-3255-5edc-a3b1-bdd4d23dba69', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 6, 14, 'ድኅነትን ያገኘንበት፥ ኀጢአታችንም የተሠረየበት ነው።'),
  ('effedcd2-7990-5011-a62f-ca45567caa23', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 7, 15, 'ይኸውም የማይታይ እግዚአብሔርን የሚመስለው፥ ከፍጥረቱ ሁሉ በላይ የሆነ በኵር ነው።'),
  ('06679bf8-f178-5a01-a863-19bf13beed61', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 8, 16, 'በእርሱ ቃልነት እግዚአብሔር ሁሉን ፈጥሮአልና በሰማይ ያለውን፥ በምድርም ያለውን፥ የሚታየውንና የማይታየውን፥ መናብርትም ቢሆኑ፥ አጋእዝትም ቢሆኑ፥ መኳንንትም ቢሆኑ፥ ቀደምትም ቢሆኑ፥ ሁሉን በእርሱ ቃልነት ፈጥሮአቸዋልና፤ ሁሉም በእጁ ሆነ፤ ሁሉም በእርሱ ለእርሱ ተፈጠረ፤'),
  ('5eae018d-5136-5ffd-a560-22d68f848e8e', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 9, 17, 'እርሱ ከሁሉ አስቀድሞ ነበረ፤ ሁሉም በእርሱ ጸና።'),
  ('9878f2c6-c65b-56b9-a3e0-bf988b463ba4', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 10, 18, 'እርሱ የቤተ ክርስቲያን ራስ ነው፤ በኵር እርሱ ለሁሉ ራስ ይሆን ዘንድ ከሙታን ሁሉ አስቀድሞ ተነሥቶአልና።'),
  ('68b64607-5ef1-5817-a5d9-6bc00d21ee1a', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 11, 19, 'ሁሉ በእርሱ ፍጹም ሆኖ ይኖር ዘንድ፥ ወዶአልና።'),
  ('e49686e8-7d07-5380-a3bf-e4ae19d52d9a', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 12, 20, 'ሁሉንም በእርሱ ይቅር ይለው ዘንድ በመስቀሉ ባፈሰሰው ደም በምድርና በሰማያት ላሉ ሰላምን አደረገ።'),
  ('ff40717e-f1d1-5981-aa28-aba23f1e2318', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 13, 21, 'እናንተም ቀድሞ በአሳባችሁና በክፉ ሥራችሁ ከእግዚአብሔር የተለያችሁና ጠላቶች ነበራችሁ።'),
  ('5237e3f6-347e-59a8-a2e9-998752a00249', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', 'c3c91280-894c-5db9-a8bd-919481a0ecab', 14, 22, 'አሁን ግን በፊቱ ለመቆም የተመረጣችሁና ንጹሓን፥ ቅዱሳንም ያደርጋችሁ ዘንድ በሥጋው ሰውነት በሞቱ ይቅር አላችሁ።'),
  ('5341eb5e-1179-5f78-a42a-454295f135b9', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '5ca486c4-5910-5901-a84b-3d420d4548c1', 1, 23, 'እንግዲህ ከሰማችሁት ከሰማይ በታች በመላው ዓለም ከተሰበከው እኔ ጳውሎስም አዋጅ ነጋሪና መልእክተኛ ሆኜ ከተሾምሁለት፥ ከወንጌል ትምህርት ተስፋ የመሠረታችሁ አቅዋም ሳይናወጥ ጨክናችሁ በሃይማኖት ብትጸኑ፥'),
  ('7317273d-03a8-58d5-a35f-1e9e10730309', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '5ca486c4-5910-5901-a84b-3d420d4548c1', 2, 24, 'አሁንም በመከራዬ ደስ ይለኛል፤ አካሉ ስለ ሆነች ስለ ቤተ ክርስቲያን፥ ከክርስቶስ መከራ ጥቂቱን በሥጋዬ እፈጽማለሁ።'),
  ('98347521-f99e-5ff8-afd3-8e0dc4f30565', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '5ca486c4-5910-5901-a84b-3d420d4548c1', 3, 25, 'ስለ እናንተ በሰጠኝ በእግዚአብሔር ሥርዐት እኔ መልእክተኛ ሆኜ የተሾምሁላት።'),
  ('031111b8-a653-5659-a79e-cd26dd5081b3', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '5ca486c4-5910-5901-a84b-3d420d4548c1', 4, 26, 'እግዚአብሔር የተናገረውን፥ ዓለም ሳይፈጠር፥ ሰውም ሳይፈጠር ተሰውሮ የነበረውን ምክሩን እፈጽም ዘንድ።'),
  ('0792ed24-6d54-5cf9-a8ae-4ae31bb31261', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '5ca486c4-5910-5901-a84b-3d420d4548c1', 5, 27, 'ዛሬ ግን እግዚአብሔር የዚህን ምክር የክብር ባለጸግነት በአሕዛብ ላይ እንዲገልጽላቸው ለፈቀደላቸው ለቅዱሳን ተገለጠላቸው፤ የምንከብርበት አለኝታችን በእናንተ አድሮ ያለ ክርስቶስ ነውና።'),
  ('5bb3ed12-60d1-521b-a7f5-041b33797735', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '5ca486c4-5910-5901-a84b-3d420d4548c1', 6, 28, 'እርሱም ኢየሱስ ክርስቶስን በማመን ፍጹም የሚሆነውን ሰው እናቀርበው ዘንድ፥ እኛ የምናስተምርለት፥ ሰውን ሁሉ ወደ እርሱ የምንጠራለትና የምንገሥጽለት፥ ሥራውንም በጥበብ ሁሉ የምንናገርለት ነው።'),
  ('eb04d22d-51b9-50fd-ab8b-ac079ea1cf91', 'ef4e48cb-21ef-5e61-a49e-69c21d77ef3d', '5ca486c4-5910-5901-a84b-3d420d4548c1', 7, 29, 'በኀይሉ እንደሚረዳኝ እንደ ረድኤቱ መጠን ስለ እርሱ እደክማለሁ፤ እጋደላለሁም።'),
  ('44992ea1-7d70-58c7-a6ee-df9245e79939', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 1, 1, 'ስለ እናንተ እና በሎዶቅያ ስላሉ፥ ፊቴንም በሥጋ ስላላዩት ምእመናን ሁሉ ምን ያህል እንደምጋደል ልታውቁ እወዳለሁ።'),
  ('cf268037-2a7b-52d8-a847-aa758b7a94b2', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 2, 2, 'ይኸውም ልቡናቸው ደስ ይለው ዘንድ፥ ትምህርታቸውም በማወቅ፥ በፍቅርና ፍጹምነት ባለው ባለጸግነት፥ በጥበብና በሃይማኖት፥ ስለ ክርስቶስም የሆነውን የእግዚአብሔርን ምክር በማወቅ ይጸና ዘንድ ነው።'),
  ('f61a2e57-d526-5061-a067-bfd5093d330f', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 3, 3, 'የተሰወረ የጥበብና የምክር መዝገብ ሁሉ በእርሱ ዘንድ አለ።'),
  ('ba665474-88d6-51cd-ad96-cc44fb742b7c', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 4, 4, 'ይህንም የምላችሁ በሚያባብል ነገር የሚያስታችሁ እንዳይኖር ነው።'),
  ('9019c532-ed12-5606-aad7-5f1773d60ddf', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 5, 5, 'እኔ በሥጋ ከእናንተ ዘንድ ባልኖርም እንኳን፥ በመንፈስ ከእናንተ ጋር ነኝ፤ እነሆ ጠባያችሁንና ሥርዐታችሁን፥ በክርስቶስም ያለ የእምነታችሁን ጽናት ስለ አየሁ ደስ ይለኛል።'),
  ('a6fb4d01-c4a3-5006-adb9-ff7ba1bee39f', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 6, 6, 'እንግዲህ ጌታችን ኢየሱስ ክርስቶስን እንደ ተቀበላችሁት፥ በእርሱ ተመላለሱ።'),
  ('b6f0d2e9-8ce3-5a17-ae5b-5b5c24d277b0', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 7, 7, 'በእርሱ ተመሥርታችሁ ታነጹ፤ በምስጋናው ትበዙ ዘንድ፥ በተማራችሁት ሃይማኖት ጽኑ።'),
  ('b3913acb-ccb0-59a8-a750-7d5d08655399', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 8, 8, 'ለዚህ ዓለም ስሕተት፥ በክርስቶስ ሕግ ያይደለ፥ በሰው ሠራሽ ሥርዐት ለከንቱ የሚያታልሉ ሰዎች በነገር ማራቀቅ እንዳያታልሉአችሁ፥ ተጠንቀቁ።'),
  ('a3653ce1-9bf1-549f-ac2d-efb506511a97', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 9, 9, 'በእርሱ ፍጹም መለኮቱ በሥጋ ተገልጦ ይኖራልና።'),
  ('c1ad2b01-292f-54bc-a371-6ece78071cb1', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 10, 10, 'እናንተም በእርሱ ፍጹማን ሁኑ፤ እርሱ ለአለቅነት ሁሉና ለሥልጣን ሁሉ ራስ ነውና።'),
  ('eed844af-9d04-55f3-aab2-b9d2551fbc34', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 11, 11, 'የኀጢአትን ሰውነት ሸለፈት በመግፈፍ በክርስቶስ መገረዝ በሰው እጅ የአልተደረገ መገረዝን በእርሱ ሆናችሁ ተገረዛችሁ።'),
  ('14d85da0-718c-5f4b-ade2-2171b435f6ad', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 12, 12, 'በጥምቀትም ከእርሱ ጋር ተቀብራችኋል፤ በእርስዋም ከሙታን ለይቶ ባስነሣው በእግዚአብሔር ረዳትነትና በሃይማኖት ከእርሱ ጋር ተነሥታችኋል።'),
  ('1122e6bb-5e59-56cc-a77f-e7fba8a96344', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 13, 13, 'እናንተም በኀጢአታችሁና ሥጋችሁን ባለመገረዝ ሙታን ነበራችሁና፥ ከእርሱ ጋር ሕያዋን አደረጋችሁ፤ ኀጢአታችሁንም ሁሉ ይቅር አላችሁ።'),
  ('3de43c55-9724-5e67-a32b-a01bdf4c3217', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 14, 14, 'ከባላጋራችን የተነሣ በትእዛዝ የተጻፈውን የዕዳችንን ደብዳቤ ደመሰሰልን፤ ከመካከላችንም አራቀው፤ በመስቀሉም ቸነከረው።'),
  ('68143198-711c-5428-aaaa-085d1277a314', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 15, 15, 'አለቆችንና ገዢዎችን በመግፈፉ በግልጥ አሳያቸው፤ ራቁቱን በመሆኑም አሳፈራቸው።'),
  ('21e4a0bd-e543-5bf9-a7e9-db2c3b458e1c', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 16, 16, 'እንግዲህ በመብልም ቢሆን፥ በመጠጥም ቢሆን፥ በልዩ ልዩ በዓላትም ቢሆን፥ በመባቻም ቢሆን፥ በሰንበትም ቢሆን የሚነቅፋችሁ እንዳይኖር ተጠንቀቁ።'),
  ('822cd53b-6af3-53da-a9b5-d48b18fb44aa', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 17, 17, 'ይህ ሁሉ ይመጣ ዘንድ ላለው ጥላ ነውና። አካሉ ግን የክርስቶስ ነው።'),
  ('29120495-b661-5023-a9bc-5187072f659f', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 18, 18, 'በመታለልና ራስን ዝቅ በማድረግ ለመላእክት አምልኮ ትታዘዙ ዘንድ ወድዶ፥ በአላየውም በከንቱ የሥጋው ምክር እየተመካ የሚያሰንፋችሁ አይኑር።'),
  ('1f947579-c6f2-5c5c-a66f-3cd38fd7925e', '409939ed-18ab-5392-addd-eddee4a00388', 'b126449c-f14c-552e-a136-c997d57a73a0', 19, 19, 'ሥጋ ሁሉ ጸንቶ በሚኖርበት፥ በሥርና በጅማትም በሚስማማበት፥ በእግዚአብሔርም በሚያድግበትና በሚጸናበት፥ በሚሞላበትም በራስ አይጸናም።'),
  ('8082fe1e-4d77-51c4-a0b1-c566382837af', '409939ed-18ab-5392-addd-eddee4a00388', '7113e7dd-83ef-59b1-ab9e-b14e84f71d0a', 1, 20, 'ከዚህ ዓለም ኑሮ ከክርስቶስ ጋር ከሞታችሁ እንደገና በዓለም እንደሚኖሩ ሰዎች እንዴት ትሠራላችሁ?'),
  ('981d4298-b905-58cf-a516-62355aa076ea', '409939ed-18ab-5392-addd-eddee4a00388', '7113e7dd-83ef-59b1-ab9e-b14e84f71d0a', 2, 21, 'እንዴትስ ይህን አትዳስስ፥ ይህን አትንካ፥ ይህንም አትቅመስ ይሉአችኋል?'),
  ('5fe4181d-6d74-5ef6-a83a-236c34463289', '409939ed-18ab-5392-addd-eddee4a00388', '7113e7dd-83ef-59b1-ab9e-b14e84f71d0a', 3, 22, 'ይህ ሁሉ እንደ ሰው ትእዛዝና ትምህርት ለጥፋት ነውና።'),
  ('4e288bd4-ac12-5a96-a501-410c79b66c72', '409939ed-18ab-5392-addd-eddee4a00388', '7113e7dd-83ef-59b1-ab9e-b14e84f71d0a', 4, 23, 'ይህም ስለ ልብ ትሕትናና እግዚአብሔርንም ስለ መፍራት፥ ለሥጋ ስለ አለማዘን ጥበብን ይመስላል፤ ነገር ግን ከሥጋ በላይ ነው እንጂ ምንም ክብር የለውም።'),
  ('b11561fb-13d5-55f5-acc4-b82b65c29fda', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 1, 1, 'ከክርስቶስ ጋር ከተነሣችሁ ክርስቶስ በእግዚአብሔር ቀኝ ተቀምጦ በአለበት በላይ ያለውን ሹ።'),
  ('6167ad73-4794-5429-a3dd-d0dbdae1a702', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 2, 2, 'የላይኛውን አስቡ፤ በምድር ያለውንም አይደለም።'),
  ('e8448437-906d-5ae6-a9c1-0df329a3a737', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 3, 3, 'እናንተ ፈጽማችሁ ሞታችኋልና፤ ሕይወታችሁም ከክርስቶስ ጋራ በእግዚአብሔር ዘንድ የተሠወረች ናትና።'),
  ('4842b9e6-ee75-5da7-ace0-c9cf3493b0db', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 4, 4, 'ሕይወታችሁ ክርስቶስ በሚገለጥበት ጊዜ፥ ያንጊዜ ከእርሱ ጋር በፍጹም ክብር ትገለጣላችሁ።'),
  ('7b8b5356-6b0a-541d-a00b-fa16bb816d0f', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 5, 5, 'ምድራዊ ሰውነታችሁንም ከዝሙትና ከርኵሰት፥ ከጥፋትና ከክፉ ምኞት፥ ጣዖት ማምለክ ከሆነው ከቅሚያም ግደሉት።'),
  ('3e8cc7f5-0e8a-5a5e-a133-413d9922e8cd', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 6, 6, 'በእነርሱም ምክንያት በማይታዘዙ ልጆች ላይ የእግዚአብሔር መቅሠፍት ይመጣል።'),
  ('fb16724c-0e49-5b92-a252-1af617ebc424', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 7, 7, 'እናንተም ቀድሞ በዚህ ሥራ በነበራችሁ ጊዜ የሄዳችሁበት ነው።'),
  ('f67da286-2dd6-5e2a-af1d-25f290c260b2', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 8, 8, 'አሁንም ቍጣንና ብስጭትን፥ ክፋትንና ስድብን፥ የሚያሳፍረውንም ነገር ተዉ፤ ከንቱ ነገርም ከአፋችሁ አይውጣ።'),
  ('0db3375a-da21-5d80-a404-16a8f886bc1e', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 9, 9, 'አሮጌውን ሰው ከሥራው ጋር ተዉት እንጂ፤ ወንድሞቻችሁን አቷሹ።'),
  ('b37d6d2e-d258-5091-afa9-bfc9596129b8', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 10, 10, 'ፈጣሪውን ለመምሰል በዕውቀት የሚታደሰውን አዲሱን ሰው ልበሱት።'),
  ('c521f59a-cf95-5acb-aa16-17d2d89fc82a', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 11, 11, 'በእርሱ ዘንድ አይሁዳዊ፥ ግሪካዊም፥ የተገዘረ፥ ያልተገዘረም፥ አረመኔም፥ ባላገርም፥ ቤተ ሰብእና አሳዳሪ ማለት የለም ነገር ግን ክርስቶስ ለሁሉ በሁሉም ዘንድ ነው።'),
  ('778ecec5-43c1-5b4c-a503-8d21bbe9d044', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 12, 12, 'እንግዲህ እግዚአብሔር እንደ መረጣቸው ቅዱሳንና ወዳጆች፥ ምሕረትንና ርኅራኄን፥ ቸርነትንና ትሕትናን፥ የውሀትንና ትዕግሥትን ልበሱት።'),
  ('bd3be48e-49f2-58d2-a473-428f416b9a25', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 13, 13, 'ባልንጀሮቻችሁን ታገሡአቸው፤ እርስ በርሳችሁ ይቅር ተባባሉ፤ ባልንጀሮቻችሁን የነቀፋችሁበትን ሥራ ተዉ፤ ክርስቶስ ይቅር እንዳላችሁ እናንተም እንዲሁ አድርጉ።'),
  ('2c2ae60c-89ac-5086-a97d-ab44c09034fb', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 14, 14, 'ከዚህም ሁሉ ጋር ዘወትር ተፋቀሩ፤ የመጨረሻው ማሰሪያ እርሱ ነውና።'),
  ('8820531f-382e-55f1-ab2f-8554fc1812ba', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 15, 15, 'በአንድ አካል የተጠራችሁለት የክርስቶስ ሰላም በልባችሁ ጸንቶ ይኑር፤ ክርስቶስንም በማመስገን ኑሩ።'),
  ('e6465c7f-0eba-596d-a961-75410302d182', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 16, 16, 'በጥበብ ሁሉ እንድትበለጽጉ የእግዚአብሔር ቃል በእናንተ ዘንድ ይጽና፤ በመንፈስም ራሳችሁን አስተምሩ፤ ገሥፁ፤ መዝሙርንና ምስጋናን፥ የቅድስና ማሕሌትንም በልባችሁ በጸጋ ለእግዚአብሔር ዘምሩ።'),
  ('09856542-b452-5364-a767-fae407aaf8b0', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', '443ad502-98b2-5009-a006-daade6137b3a', 17, 17, 'በቃልም ቢሆን፥ ወይም በሥራ የምታደርጉትን ሁሉ በጌታችን በኢየሱስ ክርስቶስ ስም አድርጉ፤ ስለ እርሱም እግዚአብሔር አብን አመስግኑት።'),
  ('3dd482a9-cd2c-5127-a991-e7963d8e7cfd', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 1, 18, 'ሚስቶች ሆይ ለእግዚአብሔር እንደምትታዘዙ ለባሎቻችሁ ታዘዙ።'),
  ('fe7c3dc0-b867-5e21-ad22-4bba9760ff94', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 2, 19, 'ባሎች ሆይ ሚስቶቻችሁን ውደዱ፤ አትንቀፉአቸውም።'),
  ('35e9ad02-ccec-5284-a051-f877d4167046', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 3, 20, 'ልጆች ሆይ ለወላጆቻችሁ በሁሉ ታዘዙ፤ እንዲህ ማድረግ ይገባልና፤ ይህም እግዚአብሔርን ደስ ያሰኛልና።'),
  ('a2e32012-07af-541e-a567-cba1ca288397', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 4, 21, 'አባቶች ሆይ እንዳያዝኑ ልጆቻችሁን አታበሳጩ።'),
  ('3ba7d499-10fb-56b9-a58f-38c39a8fedc4', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 5, 22, 'አገልጋዮች ሆይ በቅን ልብ እግዚአብሔርን በመፍራት እንጂ ለሰው ደስ እንደምታሰኙ ለታይታ የምትገዙ ሳትሆኑ፥ በሥጋ ጌቶቻችሁ ለሆኑ በሁሉ ታዘዙ።'),
  ('b56d887b-b11d-5a19-af6d-0caf15908ef1', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 6, 23, 'ለሰው ሳይሆን ለጌታ እንደምታደርጉ የምታደርጉትን ሁሉ ከልብ አድርጉት።'),
  ('8e900705-b5ae-52f3-ac55-fef590ce8a94', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 7, 24, 'ከእግዚአብሔር ዋጋችሁን እንደምትቀበሉ ታውቃላችሁ፤ ለክርስቶስ ትገዛላችሁና፤'),
  ('f951b4a3-8cc2-53f9-abdd-8783610f1ead', 'b3367ade-af18-5d1d-aad5-bb9241754b0c', 'c5fafef0-7967-5060-afa2-58d00a7c3445', 8, 25, 'የሚበድል ግን ፍዳውን ያገኛል፤ እርሱም አያደላለትም።'),
  ('f50d436a-a31a-5242-ad90-720a0921f061', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '979bddc2-bc0c-5b98-abf2-5ead14a11b5a', 1, 1, 'ጌቶች ሆይ፥ ለአገልጋዮቻችሁ ትክክለኛውን አድርጉላቸው፤ እውነትንም ፍረዱ፤ በሰማይ ጌታ እንዳላችሁ ታውቃላችሁና።'),
  ('22d84d3d-811b-5728-a867-d3eaeeb58d32', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '161a29fe-bc89-51f9-ad31-5c86b0df982d', 1, 2, 'በምስጋና እየተጋችሁ ለጸሎት ፅሙዳን ሁኑ።'),
  ('03a997c7-ca4f-59dc-ad53-e6862e75a368', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '161a29fe-bc89-51f9-ad31-5c86b0df982d', 2, 3, 'ስለ እርሱ የታሰርሁለትን የእግዚአብሔርን ምሥጢር እንድንናገር፥ እግዚአብሔር የቃሉን በር ይከፍትልን ዘንድ ለእኛም ደግሞ ጸልዩልን፤ ለምኑልንም፤'),
  ('fec16049-c058-55f3-ad0e-f6aea5246992', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '161a29fe-bc89-51f9-ad31-5c86b0df982d', 3, 4, 'ልናገርም እንደሚገባኝ እገልጠው ዘንድ ጸልዩልኝ።'),
  ('11fb0be1-8bfa-5ca3-a9f4-d89e5cd4b1ea', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '161a29fe-bc89-51f9-ad31-5c86b0df982d', 4, 5, 'ዘመኑን እየዋጃችሁ ከሃይማኖት ወደ ተለዩ ሰዎች በማስተዋል ሂዱ።'),
  ('8f37b15d-6603-5e8b-a803-de78f5ae537b', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '161a29fe-bc89-51f9-ad31-5c86b0df982d', 5, 6, 'ለእያንዳንዱ እንዴት እንደምትመልሱ ታውቁ ዘንድ ንግግራችሁ ሁልጊዜ በጨው እንደ ተቀመመ በጸጋ ይሁን።'),
  ('81d6a71a-becb-53b4-ab29-1c77c1690430', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', 'd2652c3f-387c-55a5-a8aa-f2b06ec18b17', 1, 7, 'የተወደደ ወንድማችንና የታመነ አገልጋይ፥ በጌታ ሥራም ተባባሪያችን የሆነ ቲኪቆስ የእኔን ዜና ይነግራችኋል።'),
  ('aec61a96-4302-59fb-aa2e-4814bb6638bd', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', 'd2652c3f-387c-55a5-a8aa-f2b06ec18b17', 2, 8, 'ስለዚህ ሥራ ወደ እናንተ የላክሁት ዜናዬን ታውቁ ዘንድ፥ ልባችሁንም ያጽናና ዘንድ ነው።'),
  ('cda92617-f0f4-51b1-a889-58740c7f6cb9', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', 'd2652c3f-387c-55a5-a8aa-f2b06ec18b17', 3, 9, 'ወገናችሁ ከሆነው ከምንወደውና ከታመነው ወንድማችን ከአናሲሞስ ጋር፥ እነርሱ ሥራችንንና ያለንበትን ያስረዱአችኋል።'),
  ('12e71648-d420-5b59-ac50-546c3867aa4b', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 1, 10, 'ከእኔ ጋር የተማረከው አርስጥሮኮስ፥ ወደ እናንተ በሚመጣ ጊዜ ትቀበሉት ዘንድ ስለ እርሱ ያዘዝኋችሁ የበርናባስ የአባቱ ወንድም ልጅ ማርቆስም፥'),
  ('8eb8f223-f169-52d1-afe5-6572d5a85a7d', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 2, 11, 'ኢዮስጦስ የተባለ ኢያሱም፥ ከግዙራን ሰዎች ወገን የሚሆኑ እነዚህ ሰላም ይሏችኋል። በእግዚአብሔር መንግሥት ሥራ ረዳቶች እነዚህ ብቻ ናቸው፤ እነርሱም እኔን አጽናንተውኛል።'),
  ('4ca42da1-782b-596b-a24f-30173e36d2f0', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 3, 12, 'ከእናንተ ወገን የሚሆን ኤጳፍራስም ሰላም ይላችኋል፥ እርሱ የክርስቶስ አገልጋይ ነው፤ እግዚአብሔር በሚወደው ነገር ሁሉ ምሉኣንና ፍጹማን እንድትሆኑ፥ ስለ እናንተ ዘወትር ይጸልያል፤ ይማልዳልም።'),
  ('3200be21-87af-5e03-a489-94333c75cf98', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 4, 13, 'እጅግ እንደሚወዳችሁና ስለ እናንተ በሎዶቅያና በኢያራ ከተማ ስላሉትም እንደሚቈረቈር እኔ ምስክሩ ነኝ።'),
  ('f0837dff-6fe1-5010-ae7b-4bb8d630bfda', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 5, 14, 'ወዳጃችን ባለ መድኃኒቱ ሉቃስም ሰላም ብሎአችኋል፤ ዴማስም ሰላም ይላችኋል።'),
  ('d968afc2-2ce4-55a1-a980-0bcb12fa9db1', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 6, 15, 'በሎዶቅያ ላሉት ወንድሞቻችንና ለንምፋን፥ በቤቱም ላለች ቤተ ክርስቲያን ሰላምታ አቅርቡልኝ።'),
  ('12d056e6-21e7-5264-a9c8-a107fff39583', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 7, 16, 'ይህችን መልእክት እናንተ አንብባችሁ፥ በቤተ ክርስቲያን ያነብቡአት ዘንድ ወደ ሎዶቅያ ላኩአት፤ ዳግመኛም እናንተ ከሎዶቅያ የጻፍኋትን መልእክት አንብቡአት።'),
  ('9cdbcf8f-6203-5f98-a733-769334b1b620', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 8, 17, 'አክርጳንም “ከእግዚአብሔር የተሾምህባትን መልእክትህን እንድትፈጽማት ተጠንቀቅ” በሉት።'),
  ('f962a26f-32ba-5231-ad36-b5c2c801c598', 'dd217142-79af-5fd1-acf8-85e5900e8d2b', '15958674-b67f-5e47-a1ab-e814b09bb6c7', 9, 18, 'እኔ ጳውሎስ በእጄ ጽፌ ሰላም አልኋችሁ፤ እስራቴን አስቡ፤ ጸጋ ከእናንተ ጋር ይሁን፤ አሜን።'),
  ('093d36ce-6336-53e7-ae64-98dd82f8f99b', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '753a619a-ba12-5fca-a840-9e6f48a11e6c', 1, 1, 'ጳውሎስና ስልዋኖስ ጢሞቴዎስም፥ በእግዚአብሔር አብ በጌታ በኢየሱስ ክርስቶስም ወደምትሆን ወደ ተሰሎንቄ ሰዎች ቤተ ክርስቲያን፤ ከእግዚአብሔር ከአባታችን ከጌታ ከኢየሱስ ክርስቶስም ጸጋ ሰላምም ለእናንተ ይሁን።'),
  ('66d0ea55-188a-5f90-a69b-4972dce4e046', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '52a2de24-c637-57cb-a3ad-1b969fcfdb20', 1, 2, 'በጸሎታችን ጊዜ ስለ እናንተ ስናሳስብ፥ የእምነታችሁን ሥራ የፍቅራችሁንም ድካም በጌታችንም በኢየሱስ ክርስቶስ ያለውን የተስፋችሁን መጽናት በአምላካችንና በአባታችን ፊት ሳናቋርጥ እያሰብን፥ እግዚአብሔርን ሁል ጊዜ በሁላችሁ ምክንያት እናመሰግናለን፤'),
  ('b8a24909-4ccc-5c35-a731-2a67d7f8dcb0', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '52a2de24-c637-57cb-a3ad-1b969fcfdb20', 2, 4, 'በእግዚአብሔር የምትወደዱ ወንድሞች ሆይ! እንደ ተመረጣችሁ አውቀናልና።'),
  ('bf355d9e-f9aa-5d58-a599-28b0946fb274', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '52a2de24-c637-57cb-a3ad-1b969fcfdb20', 3, 5, 'ወንጌላችን በኀይልና በመንፈስ ቅዱስ በብዙ መረዳትም እንጂ በቃል ብቻ ወደ እናንተ አልመጣምና፤ በእናንተ ዘንድ ስለ እናንተ እንዴት እንደ ነበርን ታውቃላችሁ።'),
  ('dd83af94-4d69-53be-a174-7480a6797f4e', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '52a2de24-c637-57cb-a3ad-1b969fcfdb20', 4, 6, 'ደግሞ እናንተ ቃሉን በብዙ መከራ ከመንፈስ ቅዱስ ደስታ ጋር ተቀብላችሁ፥ እኛንና ጌታን የምትመስሉ ሆናችሁ፤'),
  ('99b1c0ff-ad17-58f3-ac05-3c2834c0ea90', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '52a2de24-c637-57cb-a3ad-1b969fcfdb20', 5, 7, 'ስለዚህም በመቄዶንያና በአካይያ ላሉት ምእመናን ሁሉ ምሳሌ ሆናችሁላቸው።'),
  ('bee7b220-5ba1-5e75-a01b-2b9b10f9fbaf', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '52a2de24-c637-57cb-a3ad-1b969fcfdb20', 6, 8, 'ከእናንተ ወጥቶ የጌታ ቃል በመቄዶንያና በአካይያ ብቻ አልተሰማምና፤ ነገር ግን ምንም እንድንናገር እስከማያስፈልግ ድረስ፥ በእግዚአብሔር ዘንድ የሚሆን እምነታችሁ በሁሉ ስፍራ ተወርቶአል።'),
  ('d17b6876-ed53-56eb-a247-d401b5a48e10', 'f3b06d4c-1682-5355-a36a-3f2b5429b0c0', '52a2de24-c637-57cb-a3ad-1b969fcfdb20', 7, 9, 'እነርሱ ራሳቸው ወደ እናንተ መግባታችን እንዴት እንደነበረ ስለ እኛ ይናገራሉና፤ ለሕያውና ለእውነተኛ አምላክም ታገለግሉ ዘንድ፥ ከሙታንም ያስነሣውን ልጁን እርሱንም ኢየሱስን ከሚመጣው ቍጣ የሚያድነንን ከሰማይ ትጠብቁ ዘንድ፥ ከጣዖቶች ወደ እግዚአብሔር እንዴት እንደተመለሳችሁ ይናገራሉ።'),
  ('351f6897-4d5b-5ab9-afe1-aa9521104c18', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 1, 1, 'ወንድሞች ሆይ! ራሳችሁ ወደ እናንተ መግባታችን ከንቱ እንዳልሆነ ታውቃላችሁ።'),
  ('254055fd-d2c5-5ece-a1d1-f327cb1d64e5', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 2, 2, 'ነገር ግን እንደምታውቁት በፊልጵስዩስ አስቀድመን መከራ ተቀብለን ተንገላትተንም፥ በብዙ ገድል የእግዚአብሔርን ወንጌል ለእናንተ እንናገር ዘንድ በአምላካችን ደፈርን።'),
  ('54fb1e49-245e-5472-a102-41d30e98c66c', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 3, 3, 'ልመናችን ከስሕተት ወይም ከርኵሰት ወይም ከተንኰል አልነበረምና፤'),
  ('dad91dbe-7b5e-5f84-a192-4878358b10a7', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 4, 4, 'ነገር ግን ወንጌልን አደራ ይሰጠን ዘንድ እግዚአብሔር የታመንን ሆነን እንዳገኘን መጠን፥ እንዲሁ እንናገራለን፤ ልባችንን የሚመረምር እግዚአብሔርን እንጂ ሰውን ደስ እንደምናሰኝ አይደለም።'),
  ('2e4ffc33-d2e2-50d8-a606-c844c24a26af', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 5, 5, 'እንደምታውቁ፥ እያቈላመጥን ከቶ አልተናገርንም፤ እግዚአብሔርም እንደሚመሰክር እያመካኘን በመጐምጀት አልሠራንም፤'),
  ('a3749db6-f34c-570e-af55-14f4240daf31', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 6, 6, 'የክርስቶስም ሐዋርያት እንደ መሆናችን ልንከብድባችሁ ስንችል፥ ከእናንተ ቢሆን ወይም ከሌሎች ክብርን ከሰው አልፈለግንም።'),
  ('f9301dc1-abf7-5083-ac37-fdbd0f1b9885', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 7, 7, 'ነገር ግን ሞግዚት የራስዋን ልጆች እንደምትከባከብ፥ በመካከላችሁ የዋሆች ሆንን፤'),
  ('2b0c8671-e8c5-5659-ae77-50bb3ddfc001', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 8, 8, 'እንዲሁም እያፈቀርናችሁ የእግዚአብሔርን ወንጌል ለማካፈል ብቻ ሳይሆን የገዛ ነፍሳችንን ደግሞ እናካፍላችሁ ዘንድ በጎ ፈቃዳችን ነበረ፤ ለእኛ የተወደዳችሁ ሆናችሁ ነበርና።'),
  ('befbf502-c6f0-59ac-a96e-8812f221723b', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 9, 9, 'ወንድሞች ሆይ! ድካማችንና ጥረታችን ትዝ ይላችኋል፤ ከእናንተ በአንዱ ስንኳ እንዳንከብድበት ሌሊትና ቀን እየሠራን፥ የእግዚአብሔርን ወንጌል ለእናንተ ሰበክን።'),
  ('c034abc6-5c50-5f1a-aebc-ad679bc9fd1e', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 10, 10, 'በእናንተ በምታምኑ ዘንድ እንዴት ባለ ቅድስናና ጽድቅ ነቀፋም በሌለበት ኑሮ እንደ ሄድን፥ እናንተና እግዚአብሔር ምስክሮች ናችሁ፤'),
  ('f3a25596-b5a4-59ad-ac27-9da03054a811', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 11, 11, 'ወደ መንግሥቱ ወደ ክብሩም ለጠራችሁ ለእግዚአብሔር እንደሚገባ ትመላለሱ ዘንድ እየመከርንና እያጸናን እየመሰከርንላችሁም፥ አባት ለልጆቹ እንደሚሆን ለእያንዳንዳችሁ እንደ ሆንን ታውቃላችሁና።'),
  ('b6565031-d5b6-5235-a7bc-08502bb0bafd', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 12, 13, 'ስለዚህም የመልእክትን ቃል እርሱም የእግዚአብሔር ቃል ከእኛ በተቀበላችሁ ጊዜ፥ በእውነት እንዳለ በእናንተ በምታምኑ ደግሞ እንደሚሠራ እንደ እግዚአብሔር ቃል እንጂ እንደ ሰው ቃል አድርጋችሁ ስላልተቀበላችሁት፥ እኛ ደግሞ እግዚአብሔርን ሳናቋርጥ እናመሰግናለን።'),
  ('20644fc3-30d0-581b-a353-f12c06b0c99a', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 13, 14, 'እናንተ ወንድሞች ሆይ! በይሁዳ የሚኖሩትን በክርስቶስ ኢየሱስ ያሉትን የእግዚአብሔርን ማኅበሮች የምትመስሉ ሆናችኋልና፤ እነርሱ ከአይሁድ መከራ እንደ ተቀበሉ፥ እናንተ ደግሞ ያንን መከራ ከአገራችሁ ሰዎች ተቀብላችኋልና።'),
  ('0742a37b-33ae-5dbf-a38a-124d1d59cbf9', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 14, 15, 'እነዚያም ጌታን ኢየሱስን ደግሞ ገደሉ፤ ነቢያትንም እኛንም አሳደዱ፤ እግዚአብሔርንም ደስ አያሰኙም፤ ሰዎችንም ሁሉ ይቃወማሉ፤'),
  ('a2bcbf3b-4fb5-53bb-a026-46b50f0c5144', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'a85bcf58-009b-5795-a919-bb6428535252', 15, 16, 'ሁልጊዜ ኀጢአታቸውን ይፈጽሙ ዘንድ አሕዛብ እንዲድኑ እንዳንናገራቸው ይከለክሉናልና። ነገር ግን ቍጣው ወደ እነርሱ ፈጽሞ ደርሶአል።'),
  ('4e642b45-aaa8-5b4d-a12b-9042f05595ce', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'f09334eb-cc3d-5c97-aaaf-203e72e3267e', 1, 17, 'እኛ ግን ወንድሞች ሆይ! በልብ ያይደለ ፊት ለፊት ለጥቂት ጊዜ አጥተናችሁ፥ በብዙ ናፍቆት ፊታችሁን ለማየት እጅግ ሞከርን፤'),
  ('190b442f-4024-5e5a-aea1-ea41b2c38f03', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'f09334eb-cc3d-5c97-aaaf-203e72e3267e', 2, 18, 'ወደ እናንተ ልንመጣ ወደን ነበርና፤ እኔ ጳውሎስም አንድና ሁለት ጊዜ፥ ሰይጣን ግን አዘገየን።'),
  ('d0bd65b6-f5d5-5628-a250-c4e05985fd8c', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'f09334eb-cc3d-5c97-aaaf-203e72e3267e', 3, 19, 'ተስፋችን ወይስ ደስታችን ወይስ የትምክህታችን አክሊል ማን ነው? በጌታችን በኢየሱስ ፊት በመምጣቱ እናንተ አይደላችሁምን?'),
  ('3480e0d5-a2f2-5dda-ad8e-13ca30e35fcf', '0a9d9e0c-9f4c-51f8-af29-c5ba1519cac9', 'f09334eb-cc3d-5c97-aaaf-203e72e3267e', 4, 20, 'እናንተ ክብራችን ደስታችንም ናችሁና።'),
  ('46343e42-6c20-5238-a615-d9982f6cb1b1', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 1, 1, 'ስለዚህ ወደ ፊት እንታገሥ ዘንድ ባልተቻለን ጊዜ፥ በአቴና ብቻችንን ልንቀር በጎ ፈቃዳችን ሆነ።'),
  ('f9826c62-c3b8-51a8-a764-8f5752029326', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 2, 2, 'ስለ እምነታችሁም እንዲያጸናችሁና እንዲመክራችሁ ወንድማችንን የእግዚአብሔርንም አገልጋይ ከእኛ ጋርም አብሮ በክርስቶስ ወንጌል የሚሠራውን ጢሞቴዎስን ላክነው፤'),
  ('d2d6e291-98de-5f6f-a680-7cee7b522c3d', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 3, 3, 'በዚህ መከራ ማንም እንዳይናወጥ፥ ለዚህ እንደ ተመረጥን ራሳችሁ ታውቃላችሁና።'),
  ('7abac529-c4be-52d5-aa1f-ac5dc85debaf', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 4, 4, 'በእውነት ከእናንተ ጋር ሳለን፥ መከራ እንቀበል ዘንድ እንዳለን አስቀድመን እንነግራችሁ ነበር፤ እንዲሁም ደግሞ ሆነ፤ ይህንም ታውቃላችሁ።'),
  ('a6aa1805-5213-5d87-abfa-9db795159177', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 5, 5, 'ስለዚህ እኔ ደግሞ ወደ ፊት እታገሥ ዘንድ ባልተቻለኝ ጊዜ “ፈታኝ ምናልባት ፈትኖአቸዋል፤ ድካማችንም ከንቱ ሆኖአል፤” ብዬ እምነታችሁን ለማወቅ ላክሁ።'),
  ('4b71d246-92f7-525f-ad1a-8018e165aa10', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 6, 6, 'አሁን ግን ጢሞቴዎስ ከእናንተ ዘንድ ወደ እኛ መጥቶ ስለ እምነታችሁና ስለ ፍቅራችሁ የምሥራች ብሎ በነገረን ጊዜ፥ እኛም እናያችሁ ዘንድ እንደምንናፍቅ ታዩን ዘንድ እየናፈቃችሁ ሁልጊዜ በመልካም እንደምታስቡን በነገረን ጊዜ፥'),
  ('8d20714f-40c3-5ee2-a727-e0c7843453cf', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 7, 7, 'ስለዚህ ወንድሞች ሆይ! በእምነታችሁ በኩል በችግራችንና በመከራችን ሁሉ ስለ እናንተ ተጽናናን፤'),
  ('ae97801e-3e5a-5287-a44d-3aadcc12135a', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 8, 8, 'እናንተ በጌታ ጸንታችሁ ብትቆሙ፥ አሁን በሕይወት እንኖራለንና።'),
  ('fbf7c15a-b872-5ff1-a082-8592a92a4c7c', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 9, 9, 'ፊታችሁን ልናይ በእምነታችሁም የጎደለውን ልንሞላበት ሌሊትና ቀን ከመጠን ይልቅ እየጸለይን በአምላካችን ፊት ከእናንተ የተነሣ ስለምንደሰተው ደስታ ሁሉ ለእግዚአብሔር በእናንተ ምክንያት ምን ያህል ምስጋና እናስረክብ ዘንድ እንችላለን?'),
  ('8dc042aa-23f8-558b-aabc-ded308cdb3a6', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 10, 11, 'አምላካችንና አባታችን ራሱ ጌታችንም ኢየሱስ ክርስቶስ ወደ እናንተ መንገዳችንን ያቅና፤'),
  ('7ee585d9-8d6a-5308-a350-0f19e71787ff', '350f8926-63c4-556c-a1fd-0e0b6e500741', 'dfbb471f-5bcc-550b-a38d-9cfd45031593', 11, 12, 'ጌታችንም ኢየሱስ ክርስቶስ ከቅዱሳኑ ሁሉ ጋር ሲመጣ፥ በአምላካችንና በአባታችን ፊት በቅድስና ነቀፋ የሌለበት አድርጎ ልባችሁን ያጸና ዘንድ፥ እኛ ደግሞ ለእናንተ እንደምንሆን ጌታ እርስ በእርሳችሁ ያላችሁን ለሁሉም የሚሆን ፍቅራችሁን ያብዛ፤ ይጨምርም።'),
  ('abca8f52-42b7-5df8-ab06-0f2b478757a2', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 1, 1, 'እንግዲህ በቀረውስ ወንድሞች ሆይ! ልትመላለሱ እግዚአብሔርንም ደስ ልታሰኙ እንዴት እንደሚገባችሁ ከእኛ ዘንድ እንደ ተቀበላችሁ፥ እናንተ ደግሞ እንደምትመላለሱ፥ ከፊት ይልቅ ትበዙ ዘንድ በጌታ በኢየሱስ እንለምናችኋለን፤ እንመክራችሁማለን።'),
  ('1d616452-4169-5c7d-ad59-e40e30eea394', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 2, 2, 'በጌታ በኢየሱስ የትኛውን ትእዛዝ እንደ ሰጠናችሁ ታውቃላችሁና።'),
  ('a14f47f5-9f16-51fa-a200-33f668b2bad7', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 3, 3, 'ይህ የእግዚአብሔር ፈቃድ እርሱም መቀደሳችሁ ነውና፤'),
  ('3c4f581b-006c-53cd-ae6e-e3f731574426', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 4, 4, 'ከዝሙት እንድትርቁ፥ እግዚአብሔርን እንደማያውቁ አሕዛብ በፍትወት ምኞት አይደለም እንጂ፤ ከእናንተ እያንዳንዱ የራሱን ዕቃ በቅድስናና በክብር ያገኝ ዘንድ እንዲያውቅ፤'),
  ('c767ee76-61c2-5e26-a1fd-dcda555c0c0d', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 5, 6, 'አስቀድመን ደግሞ እንዳልናችሁና እንደ መሰከርንላችሁ፥ ጌታ ስለዚህ ነገር ሁሉ የሚበቀል ነውና፥ ማንም በዚህ ነገር አይተላለፍ፤ ወንድሙንም አያታልል።'),
  ('33adb38e-d79c-578c-a5bc-2f846deb36dd', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 6, 7, 'ለርኵሰት ሳይሆን እግዚአብሔር በቅድስና ጠርቶናልና።'),
  ('9b3ab01d-bd43-5eec-ae87-fa822bbb2f97', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 7, 8, 'እንግዲህ የማይቀበል ሰውን ያልተቀበለ አይደለም፤ መንፈስ ቅዱስን በእናንተ እንዲኖር የሰጠውን እግዚአብሔርን ነው እንጂ።'),
  ('fee6d092-009f-5081-ad37-4baeab8c4c98', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 8, 9, 'እናንተ ራሳችሁ እርስ በርሳችሁ ልትዋደዱ በእግዚአብሔር ተምራችኋልና፥ ስለ ወንድማማች መዋደድ ማንም ይጽፍላችሁ ዘንድ አያስፈልጋችሁም፤'),
  ('7a949a12-318a-51bd-a389-8eae1b6f1c12', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', '4845f6a3-60bd-52a0-a89c-f0b6a0ada87f', 9, 10, 'እንዲሁ በመቄዶንያ ሁሉ ላሉት ወንድሞች ሁሉ ታደርጋላችሁና። ነገ ግን ወንድሞች ሆይ!ከፊት ይልቅ ልትበዙ፥ በጸጥታም ትኖሩ ዘንድ ልትቀኑ፥ የራሳችሁንም ጉዳይ ልትጠነቅቁ፥ እንዳዘዝናችሁም በውጭ ባሉት ዘንድ በአገባብ እንድትመላለሱ፥ አንዳችም እንዳያስፈልጋችሁ በእጃችሁ ልትሠሩ እንለምናችኋለን።'),
  ('5a675121-dad7-5df4-a090-da86767054d3', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', 'a7ea2dc3-eeb5-558f-ae62-f16716f4acdf', 1, 13, 'ነገር ግን ወንድሞች ሆይ!ተስፋ እንደሌላቸው እንደ ሌሎች ደግሞ እንዳታዝኑ፥ አንቀላፍተው ስላሉቱ ታውቁ ዘንድ እንወዳለን።'),
  ('02ad0d93-b74a-5af6-aaa2-f65cc148dc71', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', 'a7ea2dc3-eeb5-558f-ae62-f16716f4acdf', 2, 14, 'ኢየሱስ እንደ ሞተና እንደ ተነሣ ካመንን፥ እንዲሁም በኢየሱስ ያንቀላፉቱን እግዚአብሔር ከእርሱ ጋር ያመጣቸዋልና።'),
  ('e3d30c7b-9acd-54ec-a8fa-d254d429d24e', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', 'a7ea2dc3-eeb5-558f-ae62-f16716f4acdf', 3, 15, 'በጌታ ቃል የምንላችሁ ይህ ነውና፤ እኛ ሕያዋን ሆነን ጌታ እስኪመጣ ድረስ የምንቀር ያንቀላፉቱን አንቀድምም፤'),
  ('cbdb4fa7-795c-5e56-af46-dbd31e8d25f5', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', 'a7ea2dc3-eeb5-558f-ae62-f16716f4acdf', 4, 16, 'ጌታ ራሱ በትእዛዝ በመላእክትም አለቃ ድምፅ በእግዚአብሔርም መለከት ከሰማይ ይወርዳልና፤ ክርስቶስም የሞቱ አስቀድመው ይነሣሉ፤'),
  ('7d449111-eb7c-5c4c-a8fc-07fde12f4e8d', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', 'a7ea2dc3-eeb5-558f-ae62-f16716f4acdf', 5, 17, 'ከዚያም በኋላ እኛ ሕያዋን ሆነን የምንቀረው ታን በአየር ለመቀበል ከእነርሱ ጋር በደመና እንነጠቃለን፤ እንዲሁም ሁልጊዜ ከጌታ ጋር እንሆናለን።'),
  ('5e327337-bc1a-5a7a-a5e1-c29df2167594', 'f6c4ba8d-0d36-5e72-a985-93834a2864ba', 'a7ea2dc3-eeb5-558f-ae62-f16716f4acdf', 6, 18, 'ስለዚህ እርስ በርሳችሁ በዚህ ቃል ተጽናኑ።'),
  ('96abcf15-e289-5b33-a4ca-14de8fd13e13', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 1, 1, 'ወንድሞች ሆይ! ለ ዘመናትና ስለ ወራት ምንም እንዲጻፍላችሁ አያስፈልጋችሁም፤'),
  ('f3103202-f72c-5366-a2c5-15608d5187f1', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 2, 2, 'የጌታ ቀን ሌባ በሌሊት እንደሚመጣ እንዲሁ ይመጣ ዘንድ ራሳችሁ አጥብቃችሁ አውቃችኋልና።'),
  ('86f9e68b-53e4-535b-a933-312cdc3cbc44', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 3, 3, 'ሰላምና ደኅንነት ነው ሲሉ ያን ጊዜ ምጥ እርጕዝን እንደሚይዛት ጥፋት በድንገት ይመጣባቸዋል፤ከቶም አያመልጡም።'),
  ('88c8b244-1cce-52f3-a5d9-ee8c6ef38427', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 4, 4, 'እናንተ ግን ወንድሞች ሆይ! ቀኑ እንደ ሌባ ይደርስባችሁ ዘንድ በጨለማ አይደላችሁም፤'),
  ('edec622a-b1cf-5c1c-ad38-0385843d65f1', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 5, 5, 'ሁላችሁ የብርሃን ልጆች የቀንም ልጆች ናችሁና፤ እኛ ከሌሊት ወይም ከጨለማ አይደለንም።'),
  ('8ecda9de-abf0-5aad-ab31-300eb338bd55', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 6, 6, 'እንግዲያስ እንንቃ በመጠንም እንኑር እንጂ እንደ ሌሎች አናንቀላፋ።'),
  ('a91a0e02-8c63-5897-a943-358039113974', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 7, 7, 'የሚያንቀላፉ በሌሊት ያንቀላፋሉና፤ የሚሰክሩም በሌሊት ይሰክራሉና፤'),
  ('59cfe47f-697f-57be-ae2e-95cd1784a33d', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 8, 8, 'እኛ ግን ከቀን ስለ ሆንን፥ የእምነትንና የፍቅርን ጥሩር የመዳንንም ተስፋ እንደ ራስ ቁር እየለበስን በመጠን እንኑር፤'),
  ('aaed8146-4f85-5781-a5b5-f4a8f95dc96a', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 9, 9, 'እግዚአብሔር ለቍጣ አልመረጠንምና፤ በጌታችን በኢየሱስ ክርስቶስ መዳንን ለማግኘት ነው እንጂ።'),
  ('62646526-d055-5680-a554-069555735074', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 10, 10, 'የምንነቃም ብንሆን፥ የምናንቀላፋም ብንሆን፥ ከእርሱ ጋር አብረን በሕይወት እንኖር ዘንድ ስለ እኛ ሞተ።'),
  ('a61e4afc-da4a-5726-a1ef-1d563fa3506b', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'bdf3c4ec-2ef2-5e3c-a121-7699c63c40b0', 11, 11, 'ስለዚህ እናንተ ደግሞ እንደምታደርጉ፥ እርስ በርሳችሁ ተመካከሩ፤ አንዱም አንዱም ሌላውን ያንጸው።'),
  ('d7613c00-350b-5004-ae78-6c5f2b765feb', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 1, 12, 'ወንድሞች ሆይ! በመካከላችሁ የሚደክሙትን በጌታም የሚገዙአችሁን የሚገሥጹአችሁንም ታውቁ ዘንድ፥ ስለ ሥራቸውም በፍቅር ከመጠን ይልቅ ታከብሩአቸው ዘንድ እንለምናችኋለን። እርስ በርሳችሁ በሰላም ሁኑ።'),
  ('10175b27-1e30-5faf-a61f-6a5bf20c68c1', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 2, 14, 'ወንድሞች ሆይ! እንመክራችኋለን፤ ያለ ሥርዐት የሚሄዱትን ገሥጹአቸው፤ ድፍረት የሌላቸውን አጽኑአቸው፤ ለደካሞች ትጉላቸው፤ ሰውን ሁሉ ታገሡ።'),
  ('51b6d32f-0947-5fae-a941-01e9048f73e4', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 3, 15, 'ማንም ለሌላው በክፉ ፈንታ ክፉ እንዳይመልስ ተጠንቀቁ፤ ነገር ግን ሁልጊዜ እርስ በርሳችሁ ለሁሉም መልካሙን ለማድረግ ትጉ።'),
  ('2c8d3257-8311-58d6-a0f0-a0712b9ebd35', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 4, 16, 'ሁልጊዜ ደስ ይበላችሁ፤'),
  ('e795de00-f5eb-548f-af74-c2efad0a9140', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 5, 17, 'ሳታቋርጡ ጸልዩ፤ በሁሉ አመስግኑ፤ ይህ የእግዚአብሔር ፈቃድ በክርስቶስ ኢየሱስ ወደ እናንተ ነውና።'),
  ('d70747e3-3187-5583-a143-616fc2139ddf', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 6, 19, 'መንፈስን አታጥፉ፤'),
  ('8f286925-5c9e-5b1a-aaeb-68526543dd6a', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 7, 20, 'ትንቢትን አትናቁ፤ ሁሉን ፈትኑ መልካሙንም ያዙ፤'),
  ('0b93959f-99db-5360-a77b-1723a94e4e6d', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 8, 22, 'ከማናቸውም ዐይነት ክፉ ነገር ራቁ።'),
  ('1b4355f2-e325-590c-a201-3b67bf891b11', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 9, 23, 'የሰላምም አምላክ ራሱ ሁለንተናችሁን ይቀድስ፤ መንፈሳችሁም ነፍሳችሁም ሥጋችሁም ጌታችን ኢየሱስ ክርስቶስ በመጣ ጊዜ ያለ ነቀፋ ፈጽመው ይጠበቁ።'),
  ('92924c03-b8d2-5c13-a2e0-679a664a5e9e', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 10, 24, 'የሚጠራችሁ የታመነ ነው፤ እርሱም ደግሞ ያደርገዋል።'),
  ('cd57ee9f-e45a-551c-a1d2-245b44e8b0c4', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 11, 25, 'ወንድሞች ሆይ! ስለ እኛ ጸልዩ።'),
  ('4e507d8d-7479-548b-afa6-00792cd247db', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 12, 26, 'ከወንድሞች ሁሉ ጋር በተቀደሰ አሳሳም ሰላምታ ተሰጣጡ።'),
  ('7828c998-d280-5996-afc9-8b904dd70199', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 13, 27, 'ይህ መልእክት ለቅዱሳን ወንድሞች ሁሉ እንዲነበብ በጌታ አምላችኋለሁ።'),
  ('2fa0d4c0-8fd0-5c6c-a219-b8d895129bda', '0aed4079-10a3-5a3f-a078-8fc871e77379', 'ff7e65d7-fe67-5a87-a47d-61902536c160', 14, 28, 'የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከእናንተ ጋር ይሁን፤ አሜን።'),
  ('aa169cd5-61a0-5a06-a0a1-efc02c494e5a', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', '64ea2c63-170d-57a6-a93a-61671e4d2472', 1, 1, 'ጳውሎስና ስልዋኖስ ጢሞቴዎስም፥ በእግዚአብሔር በአባታችን በጌታ በኢየሱስ ክርስቶስም ወደምትሆን ወደ ተሰሎንቄ ሰዎች ቤተ ክርስቲያን፤'),
  ('acb5b668-8ef4-5df4-acab-8a64ad52e7e1', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', '64ea2c63-170d-57a6-a93a-61671e4d2472', 2, 2, 'ከእግዚአብሔር ከአባታችን ከጌታ ከኢየሱስ ክርስቶስም ጸጋ ሰላምም ለእናንተ ይሁን።'),
  ('fb2a1f62-36ec-5bad-a09f-6b6b150fb9a4', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', 'b0db2c22-6a98-562e-aa82-f37615dd8403', 1, 3, 'ወንድሞች ሆይ! እምነታችሁ እጅግ ስለሚያድግ፥ የሁላችሁም የእያንዳንዳችሁ ፍቅር እርስ በርሳችሁ ስለሚበዛ፥ ሁልጊዜ ስለ እናንተ እግዚአብሔርን እንደሚገባ ልናመሰግን ግድ አለብን፤'),
  ('5a63aefd-ad66-5a8b-a75e-34bf52807480', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', 'b0db2c22-6a98-562e-aa82-f37615dd8403', 2, 4, 'ስለዚህ በምትታገሱበት በስደታችሁና በመከራችሁ ሁሉ ከመጽናታችሁና ከእምነታችሁ የተነሣ በእግዚአብሔር አብያተ ክርስቲያናት ስለ እናንተ ራሳችን እንመካለን።'),
  ('87c06a46-9d5a-55a8-a56d-a9d489ef00fa', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', 'b0db2c22-6a98-562e-aa82-f37615dd8403', 3, 5, 'ስለ እርሱ ደግሞ መከራ ለምትቀበሉለት ለእግዚአብሔር መንግሥት የምትበቁ ሆናችሁ ትቈጠሩ ዘንድ ይህ የእግዚአብሔር ቅን ፍርድ ምልክት ነው።'),
  ('9056b478-5e2c-5735-a170-6484f785d31b', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', 'b0db2c22-6a98-562e-aa82-f37615dd8403', 4, 6, 'ጌታ ኢየሱስ ከኀያላን መላእክቱ ጋር ከሰማይ በእሳት ነበልባል ሲገለጥ፥ መከራን ለሚያሳዩአችሁ መከራን፥ መከራንም ለምትቀበሉ ከእኛ ጋር ዕረፍትን ብድራት አድርጎ እንዲመልስ በእግዚአብሔር ፊት በእርግጥ ጽድቅ ነውና።'),
  ('363e7c34-9de7-511b-ae1b-80e7f32f7e41', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', 'b0db2c22-6a98-562e-aa82-f37615dd8403', 5, 8, 'እግዚአብሔርን የማያውቁትን፥ ለጌታችንም ለኢየሱስ ክርስቶስ ወንጌል የማይታዘዙትን ይበቀላል፤'),
  ('71299235-f68f-582b-aa72-38412b2335cc', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', 'b0db2c22-6a98-562e-aa82-f37615dd8403', 6, 9, 'በዚያም ቀን በቅዱሳኑ ሊከብር ምስክርነታችንንም አምናችኋልና በሚያምኑት ሁሉ ዘንድ ሊደነቅ ሲመጣ፥ ከጌታ ፊት ከኀይሉም ክብር ርቀው በዘላለም ጥፋት ይቀጣሉ።'),
  ('9470cd80-d1d4-5dfc-ab6e-4059af57b0dc', 'f72ae1d8-bb57-56d0-a52c-7a0f0911667a', 'b0db2c22-6a98-562e-aa82-f37615dd8403', 7, 11, 'ስለዚህም ደግሞ እንደ አምላካችን እንደ ጌታም እንደ ኢየሱስ ክርስቶስ ጸጋ፥ የጌታችን የኢየሱስ ክርስቶስ ስም በእናንተ ዘንድ ሊከብር እናንተም በእርሱ ዘንድ ልትከብሩ፥ አምላካችን ለመጥራቱ የምትበቁ አድርጎ ይቈጥራችሁ ዘንድ፥ የበጎነትንም ፈቃድ ሁሉ የእምነትንም ሥራ በኀይል ይፈጽም ዘንድ ስለ እናንተ ሁልጊዜ እንጸልያለን።'),
  ('c4431f10-a7cf-52fc-a173-78b89cbbf589', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 1, 1, 'ነገር ግን ወንድሞች ሆይ! ስለ ጌታችን ስለ ኢየሱስ ክርስቶስ መምጣትና ወደ እርሱ ስለ መሰብሰባችን፥ በመንፈስ ወይም በቃል ወይም ከእኛ እንደሚመጣ በመልእክት “የጌታ ቀን ደርሶአል፤” ብላችሁ ከአእምሮአችሁ ቶሎ እንዳትናወጡ እንዳትደነግጡም እንለምናችኋለን።'),
  ('1e1ca304-5600-5834-a2ad-bb606cfbb9c7', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 2, 3, 'ማንም በማናቸውም መንገድ አያስታችሁ፤ ክህደቱ አስቀድሞ ሳይመጣና የዐመፅ ሰው እርሱም የጥፋት ልጅ ሳይገለጥ አይደርስምና።'),
  ('ca826ce5-7af9-5b79-aaf8-72e4869ecd18', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 3, 4, '“እኔ እግዚአብሔር ነኝ፤” ብሎ አዋጅ እየነገረ በእግዚአብሔር ቤተ መቅደስ እስኪቀመጥ ድረስ፥ አምላክ ከተባለው ሁሉ፥ ሰዎችም ከሚያመልኩት ሁሉ በላይ ራሱን ከፍ ከፍ የሚያደርገው ተቃዋሚ እርሱ ነው።'),
  ('39d64547-c942-5106-aee8-ab7665b12b2c', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 4, 5, 'ገና ከእናንተ ጋር ሳለሁ ይህን እንዳልኋችሁ ትዝ አይላችሁምን?'),
  ('8b31a37e-f32b-596c-a06a-e6eae60a2f75', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 5, 6, 'በገዛ ራሱ ጊዜም ይገለጥ ዘንድ የሚከለክለውን አሁን ታውቃላችሁ።'),
  ('f4f9024e-2571-5668-acbd-cc8116e30164', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 6, 7, 'የዐመፅ ምሥጢር አሁን ይሠራልና፤ ብቻ ከመንገድ እስኪወገድ ድረስ አሁን የሚከለክል አለ።'),
  ('2153bbaf-318c-5640-a93d-81614deaadf7', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 7, 8, 'በዚያም ጊዜ ጌታ ኢየሱስ በአፉ መንፈስ የሚያጠፋው፥ ሲመጣም በመገለጡ የሚሽረው ዐመፀኛ ይገለጣል፤'),
  ('dfbe62e3-eef6-5af7-a515-97c514a79a01', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 8, 9, 'ይድኑ ዘንድ የእውነት ፍቅር ስላልተቀበሉ ለሚጠፉ፥ የእርሱ መምጣት በተአምራት ሁሉና በምልክቶች በሐሰተኞች ድንቆችም በዐመፅም መታለል ሁሉ እንደ ሰይጣን አሠራር ነው።'),
  ('e443fee6-97d9-5ee0-a806-65355f9195df', '158c75db-44c8-592a-a70a-3ffed2f75cfc', 'e78f6273-2775-5a37-a7e6-07afb6332705', 9, 11, 'ስለዚህም ምክንያት፥ በእውነት ያላመኑ ነገር ግን በዐመፅ ደስ ይላቸው የነበሩ ሁሉ ፍርድን እንዲቀበሉ ሐሰትን ያምኑ ዘንድ እግዚአብሔር የስሕተትን አሠራር ይልክባቸዋል።'),
  ('d81a8782-a697-5360-a95a-d1c2ca3a4c64', '158c75db-44c8-592a-a70a-3ffed2f75cfc', '2d54a84b-3cf7-5f3a-ae19-91dde45d58bd', 1, 13, 'እኛ ግን በጌታ የተወደዳችሁ ወንድሞች ሆይ! ሁልጊዜ ስለ እናንተ እግዚአብሔርን ልናመሰግን ግድ አለብን፤ እግዚአብሔር በመንፈስ መቀደስ እውነትንም በማመን ለመዳን እንደ በኵራት መርጦአችኋልና፤'),
  ('106deb4a-e1aa-5497-a8aa-ce159ea6a465', '158c75db-44c8-592a-a70a-3ffed2f75cfc', '2d54a84b-3cf7-5f3a-ae19-91dde45d58bd', 2, 14, 'ለዚህም የጌታችንን የኢየሱስ ክርስቶስን ክብር ለማግኘት በወንጌላችን ጠራችሁ።'),
  ('53ac1ff1-60bb-54f9-a143-57646007ef96', '158c75db-44c8-592a-a70a-3ffed2f75cfc', '2d54a84b-3cf7-5f3a-ae19-91dde45d58bd', 3, 15, 'እንግዲያስ ወንድሞች ሆይ! ጸንታችሁ ቁሙ፤ በቃላችንም ቢሆን ወይም በመልእክታችን የተማራችሁትን ወግ ያዙ።'),
  ('eaa980af-fcd7-54cc-aabe-4147625c5566', '158c75db-44c8-592a-a70a-3ffed2f75cfc', '2d54a84b-3cf7-5f3a-ae19-91dde45d58bd', 4, 16, 'ራሱ ጌታችን ኢየሱስ ክርስቶስና የወደደን በጸጋም የዘላለምን መጽናናት በጎንም ተስፋ የሰጠን እግዚአብሔር አባታችን ልባችሁን ያጽናኑት፤ በበጎም ሥራና በቃል ሁሉ ያጽኑአችሁ።'),
  ('1aa1689d-0d26-5f26-a671-a9ccce22df8f', '6e343242-2f2c-5017-ad45-41a05de4647e', 'e5443988-19ec-5e57-ae6e-295816a271df', 1, 1, 'በቀረውስ ወንድሞች ሆይ! የጌታ ቃል እንዲሮጥ፥ በእናንተም ዘንድ ደግሞ እንደሚሆን እንዲከበር፥ እምነትም ለሁሉ ስለማይሆን ከዐመፀኞችና ከክፉዎች ሰዎች እንድንድን ስለ እኛ ጸልዩ።'),
  ('00f0da3c-4854-5a41-acc4-c662b5ead551', '6e343242-2f2c-5017-ad45-41a05de4647e', 'e5443988-19ec-5e57-ae6e-295816a271df', 2, 3, 'ነገር ግን የሚያጸናችሁ ከክፉውም የሚጠብቃችሁ ጌታ የታመነ ነው።'),
  ('f763e718-3429-5a65-a3f0-e02e933bcae4', '6e343242-2f2c-5017-ad45-41a05de4647e', 'e5443988-19ec-5e57-ae6e-295816a271df', 3, 4, 'የምናዛችሁንም አሁን እንድታደርጉ ወደ ፊትም ደግሞ እንድታደርጉ ስለ እናንተ በጌታ ታምነናል።'),
  ('2492aef4-db7e-5381-a5b9-1bdbfde5d6dc', '6e343242-2f2c-5017-ad45-41a05de4647e', 'e5443988-19ec-5e57-ae6e-295816a271df', 4, 5, 'ጌታም ወደ እግዚአብሔር ፍቅር ወደ ክርስቶስም ትዕግሥት ልባችንን ያቅናው።'),
  ('51a9782b-e170-5f22-a98e-9953182a2227', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 1, 6, 'ወንድሞች ሆይ! ከእኛ እንደ ተቀበለው ወግ ሳይሆን ያለ ሥርዐት ከሚሄድ ወንድም ሁሉ ትለዩ ዘንድ በጌታችን በኢየሱስ ክርስቶስ ስም እናዛችኋለን።'),
  ('b6d20e9a-61aa-50db-ad0d-231afcf72547', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 2, 7, 'እኛን ልትመስሉ እንዴት እንደሚገባችሁ ራሳችሁ ታውቃላችሁና፤ በእናንተ ዘንድ ያለ ሥርዐት አልሄድንምና፤'),
  ('2f966d92-b1b7-5bc0-a056-a9e739e91b1f', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 3, 8, 'ከእናንተ ዘንድ በአንዱ ስንኳ እንዳንከብድበት ሌሊትና ቀን በድካምና በጥረት እየሠራን እንኖር ነበር እንጂ፥ ከማንም እንጀራን እንዲያው አልበላንም።'),
  ('36efc9db-ffee-51bc-aee6-d7b7f90e0aa7', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 4, 9, 'ይህም እኛን ልትመስሉ ራሳችንን እንደ ምሳሌ እንሰጣችሁ ዘንድ ነበር እንጂ፥ ያለ ሥልጣን ስለ ሆንን አይደለም።'),
  ('3a2a79ab-2ced-5c8b-ad77-02ca870d8c4e', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 5, 10, 'ደግሞ ከእናንተ ጋር ሳለን “ሊሠራ የማይወድ አይብላ፤” ብለን አዘናችሁ ነበርና።'),
  ('1ce566b1-09d1-52cd-ab6a-35281b0cb009', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 6, 11, 'ሥራ ከቶ ሳይሠሩ በሰው ነገር እየገቡ ያለ ሥርዐት ከእናንተ ዘንድ ስለሚሄዱ ስለ አንዳንዶች ሰምተናልና።'),
  ('e1150d1c-b4b4-5de1-a27a-13f132343d74', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 7, 12, 'እንደነዚህ ያሉትንም በጸጥታ እየሠሩ የገዛ እንጀራቸውን ይበሉ ዘንድ በጌታችን በኢየሱስ ክርስቶስ እናዛቸዋለን፤ እንመክራቸውማለን።'),
  ('5ca7ca1a-bfff-5192-aea1-0a12676a2d45', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 8, 13, 'እናንተ ግን ወንድሞች ሆይ! መልካም ሥራን ለመሥራት አትታክቱ።'),
  ('b6cd52ee-e4fb-5b7f-a2bb-96f1f192e304', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 9, 14, 'በዚህ መልእክት ለተላከ ቃላችን የማይታዘዝ ማንም ቢኖር፥ ይህን ተመልከቱት፤ ያፍርም ዘንድ ከእርሱ ጋር አትተባበሩ።'),
  ('1c7399b3-dfb1-5d23-a3de-990e24be062b', '6e343242-2f2c-5017-ad45-41a05de4647e', '0c012914-14d5-5cf8-a130-51d6bf040090', 10, 15, 'ነገር ግን እንደ ወንድም ገሥጹት እንጂ እንደ ጠላት አትቍጠሩት።'),
  ('04b30329-77d4-52bc-a6f0-3b57effc0d82', '6e343242-2f2c-5017-ad45-41a05de4647e', 'f8e9afec-cd82-517e-a4a5-2eecc4dae01c', 1, 16, 'የሰላምም ጌታ ራሱ በሁሉ መንገድ ዘወትር ሰላምን ይስጣችሁ። ጌታ ከሁላችሁ ጋር ይሁን።'),
  ('37d3e12e-0c7c-54c0-a827-a148fffd9f8e', '6e343242-2f2c-5017-ad45-41a05de4647e', 'f8e9afec-cd82-517e-a4a5-2eecc4dae01c', 2, 17, 'በገዛ እጄ የተጻፈ የእኔ የጳውሎስ ሰላምታ ይህ ነው፤ የመልእክቴ ሁሉ ማስረጃ ይህ ነው፤ እንዲህ እጽፋለሁ።'),
  ('4349c680-1232-5e34-ad5b-c25552ad2a81', '6e343242-2f2c-5017-ad45-41a05de4647e', 'f8e9afec-cd82-517e-a4a5-2eecc4dae01c', 3, 18, 'የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከሁላችሁ ጋር ይሁን።'),
  ('a68ab541-6892-5d7b-a283-b5b44350950d', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '95c3d64e-57c6-58c7-ab7e-ba0db7b27b64', 1, 1, 'መድኃኒታችን እግዚአብሔር ተስፋችንም ኢየሱስ ክርስቶስ እንዳዘዘው ትእዛዝ የኢየሱስ ክርስቶስ ሐዋርያ የሆነ ጳውሎስ፥'),
  ('c950b53a-a783-5a9f-a2bd-744abaacda1e', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '95c3d64e-57c6-58c7-ab7e-ba0db7b27b64', 2, 2, 'በእምነት እውነተኛ ልጄ ለሆነ ለጢሞቴዎስ፤ ከእግዚአብሔር ከአባታችን ከክርስቶስ ኢየሱስም ከጌታችን ጸጋና ምሕረት ሰላምም ይሁን።'),
  ('c6191906-53ae-5dd1-a436-e35fe675ed49', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', 'eddd4163-bd32-549c-a601-7d699192c8ff', 1, 3, 'ወደ መቄዶንያ በሄድሁ ጊዜ፥ አንዳንዶች ልዩ ትምህርትን እንዳያስተምሩና ወደ ተረት መጨረሻም ወደሌለው ወደ ትውልዶች ታሪክ እንዳያደምጡ ልታዛቸው በኤፌሶን ትቀመጥ ዘንድ ለመንሁህ፤ እንደ እነዚህ ያሉ ነገሮች ክርክርን ያመጣሉና፤ በእምነት ግን ላለ ለእግዚአብሔር መጋቢነት አይጠቅሙም።'),
  ('4b2eadfd-391e-555d-ab01-e622292538a3', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', 'eddd4163-bd32-549c-a601-7d699192c8ff', 2, 5, 'የትእዛዝ ፍጻሜ ግን ከንጹሕ ልብና ከበጎ ሕሊና ግብዝነትም ከሌለበት እምነት የሚወጣ ፍቅር ነው፤'),
  ('c2e83e58-6664-542c-a26b-e0ebc04a7ee2', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', 'eddd4163-bd32-549c-a601-7d699192c8ff', 3, 6, 'ከእነዚህም አንዳንዶች ስተው የሚሉትን ወይም ስለ እነርሱ አስረግጠው የሚናገሩትን ሳያስተውሉ፥ የሕግ አስተማሪዎች ሊሆኑ እየወደዱ ወደ ከንቱ ንግግር ፈቀቅ ብለዋል።'),
  ('4b080526-d9b6-5d5e-ac04-54641c1af9d9', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', 'eddd4163-bd32-549c-a601-7d699192c8ff', 4, 8, 'ነገር ግን ሰው እንደሚገባ ቢሠራበት ሕግ መልካም እንደ ሆነ እናውቃለን፤'),
  ('2c4ef415-0f69-58a2-aa15-20bc53433a52', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', 'eddd4163-bd32-549c-a601-7d699192c8ff', 5, 9, 'ይኸውም ለበደለኞችና ለማይታዘዙ፥ ለዐመጸኞችና ለኀጢአተኞች፥ ቅድስና ለሌላቸውና ለርኵሳን፥ አባትና እናትን ለሚገድሉ፥ ለነፍሰ ገዳዮችና ለሴሰኞች፥ ከወንድ ጋርም ለሚተኙ፥ በሰዎችም ለሚነግዱ፥ ለውሸተኞችም በውሸትም ለሚምሉ፥ የብሩክ እግዚአብሔርንም ክብር እንደሚገልጥ ለእኔ አደራ እንደ ተሰጠኝ፥ ወንጌል የሆነውን ደኅና ትምህርት ለሚቃወም ለሌላ ነገር ሁሉ ሕግ እንደ ተሠራ እንጂ ለጻድቅ እንዳልተሠራ በማወቅ ነው።'),
  ('2c885f1c-6332-5c0a-a207-c3679c7ffb01', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 1, 12, 'ለአገልግሎቱ ሾሞኝ ታማኝ አድርጎ ስለ ቈጠረኝ፥ ኀይል የሰጠኝን ክርስቶስ ኢየሱስን ጌታችንን አመሰግናለሁ፤'),
  ('64b47ce3-ce3a-5825-a93a-c9cbd5554962', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 2, 13, 'አስቀድሞ ተሳዳቢና አሳዳጅ አንገላችም ምንም ብሆን፥ ይህን አደረገልኝ፤ ነገር ግን ሳላውቅ ባለማመን ስላደረግሁት ምህረትን አገኘሁ፤'),
  ('ac34f3a6-03bf-5ddf-a753-8016de713b6d', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 3, 14, 'የጌታችንም ጸጋ በክርስቶስ ኢየሱስ ካሉ ከእምነትና ከፍቅር ጋር አብልጦ በዛ።'),
  ('deee0dee-bd1c-5d85-aa3f-e3d64245d4c3', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 4, 15, '“ኀጢአተኞችን ሊያድን ክርስቶስ ኢየሱስ ወደ ዓለም መጣ፤” የሚለው ቃል የታመነና ሁሉ እንዲቀበሉት የተገባ ነው፤ ከኀጢአተኞችም ዋና እኔ ነኝ፤'),
  ('d45762c0-664d-53f1-a527-e5cdf99b3525', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 5, 16, 'ስለዚህ ግን የዘላለምን ሕይወት ለማግኘት በእርሱ ያምኑ ዘንድ ላላቸው ሰዎች ምሳሌ እንድሆን፥ ኢየሱስ ክርስቶስ ዋና በምሆን በእኔ ላይ ትዕግስቱን ሁሉ ያሳይ ዘንድ ምህረትን አገኘሁ።'),
  ('e8a861da-380e-5738-addb-da2d8d152989', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 6, 17, 'ብቻውን አምላክ ለሚሆን ለማይጠፋው ለማይታየውም ለዘመናት ንጉሥ ምስጋናና ክብር እስከ ዘላለም ድረስ ይሁን፤ አሜን።'),
  ('86c02c85-2017-5857-ad72-c38532698145', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 7, 18, 'ልጄ ጢሞቴዎስ ሆይ! አስቀድሞ ስለ አንተ እንደ ተነገረው ትንቢት፥ በእርሱ መልካም ጦርነት ትዋጋ ዘንድ ይህችን ትእዛዝ አደራ እሰጥሃለሁ፤'),
  ('ebb33563-648a-551e-a86b-1971c0d01a54', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 8, 19, 'እምነትና በጎ ሕሊና ይኑርህ፤ አንዳንዶች ሕሊናን ጥለው መርከብ አለ መሪ እንደሚጠፋ በእምነት ነገር ጠፍተዋልና፤'),
  ('99394d65-22d1-584e-a0ef-ba92b2f9fcaa', '8e552ab3-94d0-5e26-a0e6-16cd8815fcf7', '1c84f288-d210-551f-a2b4-0c34f24fad78', 9, 20, 'ከእነዚያም እንዳይሳደቡ ይማሩ ዘንድ ለሰይጣን አሳልፌ የሰጠኋቸው ሄሜኔዎስና እስክንድሮስ ናቸው።'),
  ('8b8855cb-f525-59fe-a10b-1fb4f78bc908', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 1, 1, 'እንግዲህ እግዚአብሔርን በመምሰልና በጭምትነት ሁሉ ጸጥና ዝግ ብለን እንድንኖር፥ ልመናና ጸሎት ምልጃም ምስጋናም ስለ ሰዎች ሁሉ ስለ ነገሥታትና ስለ መኳንንትም ሁሉ እንዲደረጉ ከሁሉ በፊት እመክራለሁ።'),
  ('466820c4-518d-53b7-aa2f-7afc45f01c35', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 2, 3, 'ሰዎች ሁሉ ሊድኑና እውነቱን ወደ ማወቅ ሊደርሱ በሚወድ በእግዚአብሔር በመድኃኒታችን ፊት መልካምና ደስ የሚያሰኝ ይህ ነው።'),
  ('5335ad8f-5736-5ea1-a7b5-cbb71ed5bd8f', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 3, 5, 'አንድ እግዚአብሔር አለና፤ በእግዚአብሔርና በሰውም መካከል ያለው መካከለኛው ደግሞ አንድ አለ፤ እርሱም ሰው የሆነ ክርስቶስ ኢየሱስ ነው፤'),
  ('677d5fca-1f46-51b4-abc1-2c36a60abb49', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 4, 6, 'ራሱንም ለሁሉ ቤዛ ሰጠ፤ ይህም በገዛ ዘመኑ ምስክርነቱ ነበረ፤'),
  ('7ed7f3a6-156b-5a48-a23f-17fe45467eb2', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 5, 7, 'እኔም ለዚህ ነገር አዋጅ ነጋሪና ሐዋርያ በእምነትና በእውነትም የአሕዛብ አስተማሪ ለመሆን ተሾምሁ፤ እውነት እናገራለሁ፤ አልዋሽም።'),
  ('dc303330-70ca-5668-a74f-374d61198d7a', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 6, 8, 'እንግዲህ ወንዶች በስፍራ ሁሉ አለ ቍጣና አለ ክፉ አሳብ የተቀደሱትን እጆች እያነሡ እንዲጸልዩ እፈቅዳለሁ።'),
  ('0b6a236f-6de9-5ee5-a48d-94455c738063', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 7, 9, 'እንዲሁም ደግሞ ሴቶች በሚገባ ልብስ ከእፍረትና ራሳቸውን ከመግዛት ጋር ሰውነታቸውን ይሸልሙ፤ እግዚአብሔርን እንፈራለን ለሚሉት ሴቶች እንደሚገባ መልካም በማድረግ እንጂ በሽሩባና በወርቅ ወይም በዕንቍ ወይም ዋጋው እጅግ በከበረ ልብስ አይሸለሙ።'),
  ('c6f38a5a-dcbf-52b7-a24d-b117c013fda0', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 8, 11, 'ሴት በነገር ሁሉ እየተገዛች በዝግታ ትማር፤'),
  ('aeba4a91-c31f-5f96-a2cc-255feb8c5bc9', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 9, 12, 'ሴት ግን በዝግታ ትኑር እንጂ ልታስተምር ወይም በወንድ ላይ ልትሰለጥን አልፈቅድም።'),
  ('cb346a4f-de2d-5ce5-a904-0e68e95641ef', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 10, 13, 'አዳም ቀድሞ ተፈጥሮአልና፤ በኋላም ሔዋን ተፈጠረች።'),
  ('9ad46cd4-169c-594a-a3c4-ebd54889f580', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 11, 14, 'የተታለለም አዳም አይደለም፤ ሴቲቱ ግን ተታልላ በመተላለፍ ወደቀች፤'),
  ('f603f96c-0667-57a1-a9e5-b33f811ef123', 'c67c57c9-c8e8-5f26-a1a0-434952775d08', 'ad123e34-926e-5424-a3a8-5a0fb0154253', 12, 15, 'ነገር ግን በእምነትና በፍቅር በቅድስናም ራሳቸውን እየገዙ ቢኖሩ በመውለድ ትድናለች።'),
  ('c0812602-ba46-5457-a3e2-0ada7b01a9f3', 'deba481d-c512-5960-ab2e-6709d673e27f', '7901e9f0-4943-53fa-aa14-d4bec23b5b3a', 1, 1, '“ማንም ኤጲስ ቆጶስነትን ቢፈልግ መልካምን ሥራ ይመኛል፤” የሚለው ቃል የታመነ ነው።'),
  ('20de3b0b-dc0a-5cc5-a21a-7b76e0649b3f', 'deba481d-c512-5960-ab2e-6709d673e27f', '7901e9f0-4943-53fa-aa14-d4bec23b5b3a', 2, 2, 'እንግዲህ ኤጲስ ቆጶስ እንዲህ ሊሆን ይገባዋል፤ የማይነቀፍ፥ የአንዲት ሚስት ባል፥ ልከኛ፥ ራሱን የሚገዛ፥ እንደሚገባው የሚሠራ፥ እንግዳ ተቀባይ፥ ለማስተማር የሚበቃ፥'),
  ('64526315-2a9a-5285-a517-bf7a9b37965d', 'deba481d-c512-5960-ab2e-6709d673e27f', '7901e9f0-4943-53fa-aa14-d4bec23b5b3a', 3, 3, 'የማይሰክር፥ የማይጨቃጨቅ ነገር ግን ገር የሆነ፥ የማይከራከር፥ ገንዘብን የማይወድ፥'),
  ('6f1eda36-e840-546b-a223-b2aa4fae16b5', 'deba481d-c512-5960-ab2e-6709d673e27f', '7901e9f0-4943-53fa-aa14-d4bec23b5b3a', 4, 4, 'ልጆቹን በጭምትነት ሁሉ እየገዛ የራሱን ቤት በመልካም የሚያስተዳድር፤'),
  ('d97959e7-c73f-508c-a6bb-1de4513f4070', 'deba481d-c512-5960-ab2e-6709d673e27f', '7901e9f0-4943-53fa-aa14-d4bec23b5b3a', 5, 5, 'ሰው ግን የራሱን ቤት እንዲያስተዳድር ባያውቅ፥ የእግዚአብሔርን ቤተ ክርስቲያን እንዴት ይጠብቃታል?'),
  ('e2f67d94-38fe-576d-a052-474348455750', 'deba481d-c512-5960-ab2e-6709d673e27f', '7901e9f0-4943-53fa-aa14-d4bec23b5b3a', 6, 6, 'በትዕቢት ተነፍቶ በዲያቢሎስ ፍርድ እንዳይወድቅ፥ አዲስ ክርስቲያን አይሁን።'),
  ('6f4c4dc8-a83c-512e-a7c3-563be9c079aa', 'deba481d-c512-5960-ab2e-6709d673e27f', '7901e9f0-4943-53fa-aa14-d4bec23b5b3a', 7, 7, 'በዲያቢሎስ ነቀፋና ወጥመድም እንዳይወድቅ፥ በውጭ ካሉት ሰዎች ደግሞ መልካም ምስክር ሊኖረው ይገባዋል።'),
  ('69826b06-50b2-5295-a132-c33a61802633', 'deba481d-c512-5960-ab2e-6709d673e27f', 'c08fb833-5d5e-5a85-a1b1-23f9e1f78bd7', 1, 8, 'እንዲሁም ዲያቆናት ጭምቶች፥ በሁለት ቃል የማይናገሩ፥ ለብዙ ወይን ጠጅ የማይጎመጁ፥ ለነውረኛ ረብ የማይስገበገቡ፥'),
  ('6a772ec0-317f-5e6e-a0a5-f45516654cbf', 'deba481d-c512-5960-ab2e-6709d673e27f', 'c08fb833-5d5e-5a85-a1b1-23f9e1f78bd7', 2, 9, 'በንጹሕ ሕሊና የሃይማኖትን ምሥጢር የሚይዙ ሊሆኑ ይገባቸዋል።'),
  ('a12b8f24-2f49-516b-a6bd-77ceb517816f', 'deba481d-c512-5960-ab2e-6709d673e27f', 'c08fb833-5d5e-5a85-a1b1-23f9e1f78bd7', 3, 10, 'እነዚህም ደግሞ አስቀድሞ ይፈተኑ፤ ከዚያም በኋላ ያለ ነቀፋ ቢሆኑ በዲቁና ሥራ ያገልግሉ።')
